      2: begin
        e.re   = v[0];
        e.re_v = 1'b1;
      end
      3: begin
        e.sf   = v[0];
        e.sf_v = 1'b1;
      end
      4: begin
        e.tm   = v[1:0];
        e.tm_v = 1'b1;
      end
      5: begin
        e.te   = v[0];
        e.te_v = 1'b1;
      end
      6: begin
        e.wc   = v[1:0];
        e.wc_v = 1'b1;
      end
      7: begin
        e.ts   = v;
        e.ts_v = 1'b1;
      end
      8: begin
        e.tl   = v[0];
        e.tl_v = 1'b1;
      end
      9: begin
        e.tf   = v[1:0];
        e.tf_v = 1'b1;
      end
      10: begin
        e.dc   = v[0];
        e.dc_v = 1'b1;
      end
      default: e.pt_v = 1'b1;
    endcase
    u_sep_esrc_startup_health_cg.sample(e);
  endtask

