  // ---------------------------------------------------------------------
  // Common events of entries 1.40 to 1.53.
  // ---------------------------------------------------------------------
  // Window edges of the graded-window gate.
  int unsigned cz_owner_q = FcovOwnNone;
  wire cz_win_open = (graded_owner != FcovOwnNone) && (graded_owner != cz_owner_q);
  function automatic logic cz_ended(input int unsigned own);
    return (cz_owner_q == own) && (graded_owner != own);
  endfunction
  // A hardware set request: the {d, de} pair of a register field, both 1.
  function automatic logic cz_dd(input logic [1:0] p);
    return p === 2'b11;
  endfunction

  // A completed single-beat write with any response (the read-only write of
  // cp_component_id), and the clock after an OKAY write with its address
  // and lane data.
  wire cz_wr_any = !in_reset && b_hs && (aw_out_q == 4'd1) && (w_beats_q == 2'd1);
  logic cz_w1 = 1'b0;
  logic [31:0] cz_w1_a = '0;
  logic [31:0] cz_w1_d = '0;

  // TRNG reset window and the TRNG domain.
  wire cz_trng = (trng_rst_i === 1'b1);
  logic cz_trng_q = 1'b0;
  wire cz_trng_rise = cz_trng && !cz_trng_q;
  wire cz_trng_fall = !cz_trng && cz_trng_q;
  wire cz_es_on = cy_ip[5] && cy_ip_q[5] && !cz_trng && !cz_trng_q;

  // ESRC state.
  wire cz_men = cy_t(esrc_reg_out_i.CTRL.MODULE_ENABLE.value);
  wire cz_boot = cy_t(esrc_boot_done_i);
  wire cz_idle = cy_t(esrc_sm_idle_i);
  wire cz_lock = cy_t(esrc_reg_out_i.FIPS_LOCK.LOCK.value);
  wire cz_atune = cy_t(esrc_reg_out_i.CTRL.AUTOTUNE_ENABLE.value);
  wire cz_whiten = cy_t(esrc_reg_out_i.CTRL.SHA256_WHITENING_ENABLE.value);
  wire cz_bypass = cy_t(esrc_reg_out_i.CTRL.BYPASS_ENTROPY_COMPRESSOR.value);
  wire cz_strobe = cy_t(esrc_decor_valid_i);
  wire cz_cvld = cy_t(esrc_compress_vld_i);
  wire cz_wpush = cy_t(esrc_whiten_push_i);
  wire cz_bpush = cy_t(esrc_biw_obs_push_i);
  wire cz_npush = cy_t(esrc_noise_obs_push_i);
  wire cz_sha_busy = cy_t(esrc_reg_in_i.SHA256_STATUS.BUSY.next);
  wire [3:0] cz_sha_out = esrc_reg_in_i.SHA256_STATUS.OUTPUT_COUNT.next;
  wire [7:0] cz_hts = esrc_reg_in_i.HEALTH_TEST_STATUS.HEALTH_STATUS.next;
  wire [15:0] cz_rep_cnt = esrc_reg_in_i.REPETITION_TEST_COUNT.REPETITION_COUNT.next;
  wire [15:0] cz_any_fail = esrc_reg_in_i.ALERT_SUMMARY_FAIL_COUNTS.ANY_FAIL_COUNT.next;
  wire [15:0] cz_thr = esrc_reg_out_i.ALERT_THRESHOLD.THRESHOLD.value;
  wire [31:0] cz_tot_rep = esrc_reg_in_i.REPCNT_TOTAL_FAILS.FAIL_COUNT.next;
  wire [31:0] cz_tot_ahi = esrc_reg_in_i.APT_HI_TOTAL_FAILS.FAIL_COUNT.next;
  wire [31:0] cz_tot_alo = esrc_reg_in_i.APT_LO_TOTAL_FAILS.FAIL_COUNT.next;
  wire [31:0] cz_tot_mhi = esrc_reg_in_i.MARKOV_HI_TOTAL_FAILS.FAIL_COUNT.next;
  wire [31:0] cz_tot_mlo = esrc_reg_in_i.MARKOV_LO_TOTAL_FAILS.FAIL_COUNT.next;
  wire [6:0] cz_flvl = esrc_reg_in_i.FIFO_STATUS.LEVEL.next;
  wire [5:0] cz_fwp = esrc_reg_in_i.FIFO_STATUS.WPTR.next;
  wire [5:0] cz_frp = esrc_reg_in_i.FIFO_STATUS.RPTR.next;
  wire [2:0] cz_ht_en = esrc_reg_out_i.HEALTH_TEST_CTRL.ENABLE.value;
  wire [15:0] cz_wsize = esrc_reg_out_i.HEALTH_TEST_WINDOW_SIZE.SIZE.value;
  // RAW_ENABLE of the observe paths, [0] noise, [1] biw.
  wire [1:0] cz_raw = {
    cy_t(esrc_reg_out_i.BIW_OBS_CTRL.RAW_ENABLE.value),
    cy_t(esrc_reg_out_i.NOISE_OBS_CTRL.RAW_ENABLE.value)
  };
  // A window of whole 64-word periods: the sampler counts it in 64-strobe blocks.
  wire cz_wsize_ok = !$isunknown(cz_wsize) && (cz_wsize >= 16'd64) && (cz_wsize[5:0] == 6'd0);
  wire [9:0] cz_wblocks = cz_wsize[15:6];
  wire cz_thr_known = !$isunknown(cz_thr);
  wire cz_rep_known = !$isunknown(cz_rep_cnt);
  wire cz_lo_tot_known = !$isunknown({cz_tot_alo, cz_tot_mlo});
  wire cz_hi_tot_known = !$isunknown(cz_tot_ahi);
  wire cz_dt_known = !$isunknown(esrc_detune_i);

  // INTR_STATUS, INTR_ENABLE and INTR_TEST of the eight ESRC sources;
  // source i is register bit 4i.
  logic [7:0] cz_ist;
  logic [7:0] cz_ien;
  logic [7:0] cz_itst;
  always_comb begin
    cz_ist = {
      cy_t(esrc_reg_out_i.INTR_STATUS.NOISE_OBS_OVERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_STATUS.BIW_OBS_OVERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_STATUS.AUTOTUNE_FAIL.value),
      cy_t(esrc_reg_out_i.INTR_STATUS.PERSISTENT_FAILURE.value),
      cy_t(esrc_reg_out_i.INTR_STATUS.FIFO_UNDERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_STATUS.FIFO_OVERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_STATUS.FIFO_ERROR.value),
      cy_t(esrc_reg_out_i.INTR_STATUS.HEALTH_TEST_FAILED.value)
    };
    cz_ien = {
      cy_t(esrc_reg_out_i.INTR_ENABLE.NOISE_OBS_OVERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_ENABLE.BIW_OBS_OVERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_ENABLE.AUTOTUNE_FAIL.value),
      cy_t(esrc_reg_out_i.INTR_ENABLE.PERSISTENT_FAILURE.value),
      cy_t(esrc_reg_out_i.INTR_ENABLE.FIFO_UNDERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_ENABLE.FIFO_OVERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_ENABLE.FIFO_ERROR.value),
      cy_t(esrc_reg_out_i.INTR_ENABLE.HEALTH_TEST_FAILED.value)
    };
    cz_itst = {
      cy_t(esrc_reg_out_i.INTR_TEST.NOISE_OBS_OVERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_TEST.BIW_OBS_OVERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_TEST.AUTOTUNE_FAIL.value),
      cy_t(esrc_reg_out_i.INTR_TEST.PERSISTENT_FAILURE.value),
      cy_t(esrc_reg_out_i.INTR_TEST.FIFO_UNDERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_TEST.FIFO_OVERFLOW.value),
      cy_t(esrc_reg_out_i.INTR_TEST.FIFO_ERROR.value),
      cy_t(esrc_reg_out_i.INTR_TEST.HEALTH_TEST_FAILED.value)
    };
  end
  logic [7:0] cz_ist_q = '0;
  logic [7:0] cz_itst_q = '0;
  logic [7:0] cz_itst_q2 = '0;
  wire  [7:0] cz_itst_rec = cz_itst | cz_itst_q | cz_itst_q2;
  wire  [7:0] cz_ist_rise = cz_ist & ~cz_ist_q;

  // Health status of the 12 generators.
  logic [7:0] cz_gst[12];
  always_comb begin
    cz_gst[0]  = esrc_reg_in_i.GENERATOR_0_HEALTH_STATUS.STATUS.next;
    cz_gst[1]  = esrc_reg_in_i.GENERATOR_1_HEALTH_STATUS.STATUS.next;
    cz_gst[2]  = esrc_reg_in_i.GENERATOR_2_HEALTH_STATUS.STATUS.next;
    cz_gst[3]  = esrc_reg_in_i.GENERATOR_3_HEALTH_STATUS.STATUS.next;
    cz_gst[4]  = esrc_reg_in_i.GENERATOR_4_HEALTH_STATUS.STATUS.next;
    cz_gst[5]  = esrc_reg_in_i.GENERATOR_5_HEALTH_STATUS.STATUS.next;
    cz_gst[6]  = esrc_reg_in_i.GENERATOR_6_HEALTH_STATUS.STATUS.next;
    cz_gst[7]  = esrc_reg_in_i.GENERATOR_7_HEALTH_STATUS.STATUS.next;
    cz_gst[8]  = esrc_reg_in_i.GENERATOR_8_HEALTH_STATUS.STATUS.next;
    cz_gst[9]  = esrc_reg_in_i.GENERATOR_9_HEALTH_STATUS.STATUS.next;
    cz_gst[10] = esrc_reg_in_i.GENERATOR_10_HEALTH_STATUS.STATUS.next;
    cz_gst[11] = esrc_reg_in_i.GENERATOR_11_HEALTH_STATUS.STATUS.next;
  end
  logic [7:0] cz_gst_q[12] = '{default: '0};
  // Lane of a GENERATOR_<n>_HEALTH_STATUS address, -1 for another address.
  function automatic int cz_gen_lane(input logic [31:0] a);
    case (a)
      ENTROPY_SOURCE_GENERATOR_0_HEALTH_STATUS_REG_ADDR: return 0;
      ENTROPY_SOURCE_GENERATOR_1_HEALTH_STATUS_REG_ADDR: return 1;
      ENTROPY_SOURCE_GENERATOR_2_HEALTH_STATUS_REG_ADDR: return 2;
      ENTROPY_SOURCE_GENERATOR_3_HEALTH_STATUS_REG_ADDR: return 3;
      ENTROPY_SOURCE_GENERATOR_4_HEALTH_STATUS_REG_ADDR: return 4;
      ENTROPY_SOURCE_GENERATOR_5_HEALTH_STATUS_REG_ADDR: return 5;
      ENTROPY_SOURCE_GENERATOR_6_HEALTH_STATUS_REG_ADDR: return 6;
      ENTROPY_SOURCE_GENERATOR_7_HEALTH_STATUS_REG_ADDR: return 7;
      ENTROPY_SOURCE_GENERATOR_8_HEALTH_STATUS_REG_ADDR: return 8;
      ENTROPY_SOURCE_GENERATOR_9_HEALTH_STATUS_REG_ADDR: return 9;
      ENTROPY_SOURCE_GENERATOR_10_HEALTH_STATUS_REG_ADDR: return 10;
      ENTROPY_SOURCE_GENERATOR_11_HEALTH_STATUS_REG_ADDR: return 11;
      default: return -1;
    endcase
  endfunction

  // Stored values at the AW handshake of the write in flight (one
  // outstanding write: the value before the write lands).
  logic [7:0] cz_aw_ist = '0;
  logic [15:0] cz_aw_csctrl = '0;
  logic [2:0] cz_aw_csff = '0;
  logic cz_aw_csrw = 1'b0;
  logic [15:0] cz_aw_edctrl = '0;
  logic cz_aw_edrw = 1'b0;
  logic [2:0] cz_aw_sel = '0;
  logic [11:0] cz_aw_detune = '0;
  // Stored-value trigger: the clock after an OKAY write to the ESRC block,
  // or the clock where a graded window opens.
  logic cz_esw1 = 1'b0;
  wire cz_sv_ev = cz_win_open || cz_esw1;

  // CSRNG and EDN stored control.
  wire [15:0] cz_csctrl = {
    csrng_reg2hw_i.ctrl.fips_force_enable.q,
    csrng_reg2hw_i.ctrl.read_int_state.q,
    csrng_reg2hw_i.ctrl.sw_app_enable.q,
    csrng_reg2hw_i.ctrl.enable.q
  };
  wire [15:0] cz_edctrl = {
    edn_reg2hw_i.ctrl.cmd_fifo_rst.q,
    edn_reg2hw_i.ctrl.auto_req_mode.q,
    edn_reg2hw_i.ctrl.boot_req_mode.q,
    edn_reg2hw_i.ctrl.edn_enable.q
  };
  localparam logic [31:0] CzCsCtrlMask = 32'(CSRNG_CTRL_ENABLE_MASK | CSRNG_CTRL_SW_APP_ENABLE_MASK |
      CSRNG_CTRL_READ_INT_STATE_MASK | CSRNG_CTRL_FIPS_FORCE_ENABLE_MASK);
  localparam logic [31:0] CzEdCtrlMask = 32'(EDN_CTRL_EDN_ENABLE_MASK | EDN_CTRL_BOOT_REQ_MODE_MASK |
      EDN_CTRL_AUTO_REQ_MODE_MASK | EDN_CTRL_CMD_FIFO_RST_MASK);

  // External stream select, 2-state.
  logic [2:0] cz_sel;
  always_comb begin
    for (int i = 0; i < 3; i++) cz_sel[i] = (ext_trng_sel_i[i] === 1'b1);
  end

  always @(posedge clk_i) begin
    cz_owner_q <= graded_owner;
    cz_w1      <= wr_ev;
    cz_w1_a    <= aw_addr_q;
    cz_w1_d    <= wr_data;
    cz_esw1    <= wr_ev && (blk_of(aw_addr_q) == BLK_ESRC);
    cz_trng_q  <= cz_trng;
    cz_ist_q   <= cz_ist;
    cz_itst_q  <= cz_itst;
    cz_itst_q2 <= cz_itst_q;
    for (int j = 0; j < 12; j++) cz_gst_q[j] <= cz_gst[j];
    if (aw_hs) begin
      cz_aw_ist    <= cz_ist;
      cz_aw_csctrl <= cz_csctrl;
      cz_aw_csff   <= csrng_reg2hw_i.fips_force.q;
      cz_aw_csrw   <= cy_t(csrng_regwen_i);
      cz_aw_edctrl <= cz_edctrl;
      cz_aw_edrw   <= cy_t(edn_regwen_i);
      cz_aw_sel    <= cz_sel;
      cz_aw_detune <= esrc_detune_i;
    end
  end

  // ---------------------------------------------------------------------
  // sep_crypto_intr_cg: x_esrc_status_enable and cp_esrc_raise_path.
  // ---------------------------------------------------------------------
  wire cz_es_hw_own = cy_own_eshp || cy_own_espa || cy_own_estune || cy_own_esfifo || cy_own_esobs;
  always @(posedge clk_i) begin
    // One cell per source at an OKAY read of INTR_STATUS: the status bit of
    // the read data and the stored enable bit.
    if (rd_ev && (ar_addr_q == ENTROPY_SOURCE_INTR_STATUS_REG_ADDR) && cy_rd_known && cz_es_on &&
        (cy_own_eswalk || cz_es_hw_own)) begin
      for (int i = 0; i < 8; i++) cy_intr(6, 6'({3'(i), rd_data[4*i], cz_ien[i]}));
    end
    // A status bit that rises with no INTR_TEST write of the bit.
    if (cz_es_on && cz_es_hw_own) begin
      for (int i = 0; i < 8; i++) begin
        if (cz_ist_rise[i] && !cz_itst_rec[i] && (i != 3)) cy_intr(7, 6'(i));
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_crypto_reg_lock_cg: x_fips_field (1.47), cp_module_enable_locked
  // (1.40), x_csrng_regwen and x_edn_regwen (1.49).
  // ---------------------------------------------------------------------
  logic cz_lock_q = 1'b0;
  logic [1:0] cz_ff_on = '0;  // armed after the lock, [0] noise, [1] biw
  logic [1:0] cz_ff_raw = '0;  // RAW_ENABLE at the lock
  logic [1:0] cz_ff_w1 = '0;  // locked at 0: a write of 1 landed under the lock
  logic [1:0] cz_ff_up = '0;  // locked at 0: the level rose after that write
  logic [6:0] cz_nlvl_q = '0;
  logic [6:0] cz_blvl_q = '0;
  logic cz_me_arm = 1'b0;
  logic cz_me_bad = 1'b0;
  always @(posedge clk_i) begin
    logic [1:0] raw;
    logic [6:0] lvl[2];
    logic [6:0] lvl_q[2];
    raw    = cz_raw;
    lvl[0] = esrc_noise_obs_level_i;
    lvl[1] = esrc_biw_obs_level_i;
    lvl_q[0] = cz_nlvl_q;
    lvl_q[1] = cz_blvl_q;
    cz_lock_q <= cz_lock;
    cz_nlvl_q <= esrc_noise_obs_level_i;
    cz_blvl_q <= esrc_biw_obs_level_i;

    // x_fips_field. Locked at 1: the observe level rises after the lock
    // while RAW_ENABLE is still 1 (capture continues; the BIW FIFO has no
    // flush, so no drain is required). Locked at 0: after a write of 1 to RAW_ENABLE
    // under the lock, an OKAY read of the observe STATUS returns LEVEL 0 and
    // the level has not risen since the write.
    if (!cy_own_esobs || !cz_es_on || !cz_lock) begin
      cz_ff_on <= '0;
      cz_ff_w1 <= '0;
      cz_ff_up <= '0;
    end else if (!cz_lock_q) begin
      cz_ff_on  <= 2'b11;
      cz_ff_raw <= raw;
      cz_ff_w1  <= '0;
      cz_ff_up  <= '0;
    end else begin
      for (int f = 0; f < 2; f++) begin
        logic [31:0] ctl_a;
        logic [31:0] ctl_m;
        logic [31:0] sts_a;
        logic [31:0] sts_m;
        ctl_a = (f == 0) ? ENTROPY_SOURCE_NOISE_OBS_CTRL_REG_ADDR : ENTROPY_SOURCE_BIW_OBS_CTRL_REG_ADDR;
        ctl_m = (f == 0) ? 32'(ENTROPY_SOURCE_NOISE_OBS_CTRL_RAW_ENABLE_MASK) :
            32'(ENTROPY_SOURCE_BIW_OBS_CTRL_RAW_ENABLE_MASK);
        sts_a = (f == 0) ? ENTROPY_SOURCE_NOISE_OBS_STATUS_REG_ADDR :
            ENTROPY_SOURCE_BIW_OBS_STATUS_REG_ADDR;
        sts_m = (f == 0) ? 32'(ENTROPY_SOURCE_NOISE_OBS_STATUS_LEVEL_MASK) :
            32'(ENTROPY_SOURCE_BIW_OBS_STATUS_LEVEL_MASK);
        if (cz_ff_on[f] && cz_ff_raw[f] && raw[f] && (lvl[f] > lvl_q[f])) begin
          cz_lk(0, {1'(f), 1'b1});
          cz_ff_on[f] <= 1'b0;
        end
        if (cz_ff_on[f] && !cz_ff_raw[f]) begin
          if (cz_w1 && (cz_w1_a == ctl_a) && ((cz_w1_d & ctl_m) != 32'h0) && !raw[f]) begin
            cz_ff_w1[f] <= 1'b1;
            cz_ff_up[f] <= 1'b0;
          end else if (cz_ff_w1[f]) begin
            if (lvl[f] > lvl_q[f]) cz_ff_up[f] <= 1'b1;
            if (rd_ev && (ar_addr_q == sts_a) && cy_rd_known && ((rd_data & sts_m) == 32'h0) &&
                !cz_ff_up[f] && !raw[f]) begin
              cz_lk(0, {1'(f), 1'b0});
              cz_ff_on[f] <= 1'b0;
            end
          end
        end
      end
    end

    // cp_module_enable_locked: a write of 0 to MODULE_ENABLE under the lock;
    // the stored bit stays 1 and main_sm_idle stays 0 to the end of the
    // observation interval (the next CTRL write, a TRNG reset or the close
    // of the window).
    if (cz_me_arm) begin
      logic bad;
      logic fin;
      bad = cz_me_bad || cz_idle || !cz_men;
      fin = cz_ended(FcovOwnSepEsrcCsrRwWalkRandTest);
      fin |= cz_w1 && (cz_w1_a == ENTROPY_SOURCE_CTRL_REG_ADDR);
      if (fin) begin
        if (!bad) cz_lk(1, 2'd0);
        cz_me_arm <= 1'b0;
      end else if (cz_trng || !cy_ip[5]) begin
        cz_me_arm <= 1'b0;
      end
      cz_me_bad <= bad;
    end
    if (cy_own_eswalk && cz_es_on && cz_w1 && (cz_w1_a == ENTROPY_SOURCE_CTRL_REG_ADDR) &&
        ((cz_w1_d & 32'(ENTROPY_SOURCE_CTRL_MODULE_ENABLE_MASK)) == 32'h0) && cz_lock && cz_men &&
        !cz_idle) begin
      cz_me_arm <= 1'b1;
      cz_me_bad <= 1'b0;
    end

    // x_csrng_regwen, x_edn_regwen: a write under REGWEN 0 whose field bits
    // differ from the stored value leaves the stored value unchanged; a
    // write of 1 to REGWEN after 0 leaves 0.
    if (cy_own_drw && cz_w1 && cy_ip[5] && !cz_trng) begin
      if ((cz_w1_a == CSRNG_CTRL_REG_ADDR) && !cz_aw_csrw &&
          ((cz_w1_d & CzCsCtrlMask) != 32'(cz_aw_csctrl)) && (cz_csctrl == cz_aw_csctrl)) begin
        cz_lk(2, 2'd0);
      end
      if ((cz_w1_a == CSRNG_FIPS_FORCE_REG_ADDR) && !cz_aw_csrw &&
          ((cz_w1_d & 32'(CSRNG_FIPS_FORCE_FIPS_FORCE_MASK)) != 32'(cz_aw_csff)) &&
          (csrng_reg2hw_i.fips_force.q == cz_aw_csff)) begin
        cz_lk(2, 2'd1);
      end
      if ((cz_w1_a == CSRNG_REGWEN_REG_ADDR) && !cz_aw_csrw &&
          ((cz_w1_d & 32'(CSRNG_REGWEN_REGWEN_MASK)) != 32'h0) && (csrng_regwen_i === 1'b0)) begin
        cz_lk(2, 2'd2);
      end
      if ((cz_w1_a == EDN_CTRL_REG_ADDR) && !cz_aw_edrw &&
          ((cz_w1_d & CzEdCtrlMask) != 32'(cz_aw_edctrl)) && (cz_edctrl == cz_aw_edctrl)) begin
        cz_lk(3, 2'd0);
      end
      if ((cz_w1_a == EDN_REGWEN_REG_ADDR) && !cz_aw_edrw && (cz_w1_d[0] == 1'b1) &&
          (edn_regwen_i === 1'b0)) begin
        cz_lk(3, 2'd1);
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_crypto_alert_cg cp_csrng_recov_seq (1.50). Set: the
  // CMD_STAGE_INVALID_CMD_SEQ_ALERT set request while the last command
  // presented to CSRNG is an instantiate and an earlier instantiate was
  // presented since the TRNG reset. Clear: a read of 1, a write of 0 and a
  // read of 0 with no set request between.
  // ---------------------------------------------------------------------
  logic [1:0] cz_ins_n = '0;  // instantiates since the TRNG reset, saturating
  logic cz_last_ins = 1'b0;
  logic cz_app0_v_q = 1'b0;
  logic cz_rs_one = 1'b0;
  logic cz_rs_w0 = 1'b0;
  wire cz_rs_set = cz_dd(csrng_hw2reg_i.recov_alert_sts.cmd_stage_invalid_cmd_seq_alert);
  localparam logic [31:0] CzRsMask = 32'(CSRNG_RECOV_ALERT_STS_CMD_STAGE_INVALID_CMD_SEQ_ALERT_MASK);
  always @(posedge clk_i) begin
    logic app0_new;
    logic [1:0] n;
    logic last;
    app0_new = cy_t(csrng_app0_req_i.csrng_req_valid) && !cz_app0_v_q;
    cz_app0_v_q <= cy_t(csrng_app0_req_i.csrng_req_valid);
    n    = cz_ins_n;
    last = cz_last_ins;
    if (wr_ev && (aw_addr_q == CSRNG_CMD_REQ_REG_ADDR)) begin
      last = (wr_data[3:0] == 4'h1);
      if (last && (n != 2'd3)) n = n + 2'd1;
    end
    if (app0_new) begin
      last = (csrng_app0_req_i.csrng_req_bus[3:0] == 4'h1);
      if (last && (n != 2'd3)) n = n + 2'd1;
    end
    if (cz_rs_set && cz_last_ins && (cz_ins_n >= 2'd2) && cy_own_dcmd) cz_alert(1'b0);
    if (cz_trng || !cy_ip[5]) begin
      n    = '0;
      last = 1'b0;
    end
    cz_ins_n    <= n;
    cz_last_ins <= last;

    if (!cy_own_dcmd || cz_trng || cz_rs_set) begin
      cz_rs_one <= 1'b0;
      cz_rs_w0  <= 1'b0;
    end else begin
      if (wr_ev && (aw_addr_q == CSRNG_RECOV_ALERT_STS_REG_ADDR) && cz_rs_one &&
          ((wr_data & CzRsMask) == 32'h0)) begin
        cz_rs_w0 <= 1'b1;
      end
      if (rd_ev && (ar_addr_q == CSRNG_RECOV_ALERT_STS_REG_ADDR) && cy_rd_known) begin
        if ((rd_data & CzRsMask) != 32'h0) begin
          cz_rs_one <= 1'b1;
          cz_rs_w0  <= 1'b0;
        end else if (cz_rs_one && cz_rs_w0) begin
          cz_alert(1'b1);
          cz_rs_one <= 1'b0;
          cz_rs_w0  <= 1'b0;
        end
      end
    end
  end

  // ---------------------------------------------------------------------
  // Decorrelator-input windows (1.41, 1.45). At each decorrelator strobe
  // the sampler takes the input bit of every lane (esrc_decor_noise_i) and
  // counts the ones of each 64-strobe block. A window of W strobes
  // (HEALTH_TEST_WINDOW_SIZE) is classed from the signal: every block of the
  // window holds 0 ones (constant 0), 45 (biased high), 19 (biased low) or
  // 64 (constant 1). A window with blocks of different counts has no class.
  // The count restarts at a MODULE_ENABLE rise, a window size change and the
  // TRNG reset.
  // ---------------------------------------------------------------------
  localparam logic [2:0] CzClsNone = 3'd0;
  localparam logic [2:0] CzClsZero = 3'd1;
  localparam logic [2:0] CzClsHigh = 3'd2;
  localparam logic [2:0] CzClsLow = 3'd3;
  localparam logic [2:0] CzClsOne = 3'd4;
  function automatic logic [2:0] cz_cls(input logic [6:0] c);
    case (c)
      7'd0: return CzClsZero;
      7'd45: return CzClsHigh;
      7'd19: return CzClsLow;
      7'd64: return CzClsOne;
      default: return CzClsNone;
    endcase
  endfunction

  longint unsigned cz_strobes = 0;  // strobes counted with the module running
  logic [6:0] cz_ln_ones[12] = '{default: '0};
  logic [6:0] cz_ln_first[12] = '{default: '0};
  logic [6:0] cz_ln_last[12] = '{default: '0};  // ones of the last whole block
  logic [11:0] cz_ln_same = '0;
  logic [11:0] cz_ln_known = '0;  // every bit of the window was 0 or 1
  logic [2:0] cz_ln_cls[12] = '{default: CzClsNone};
  logic [2:0] cz_ln_cls_p[12] = '{default: CzClsNone};
  logic [5:0] cz_blk_pos = '0;
  logic [9:0] cz_blk_n = '0;
  logic cz_win_done = 1'b0;  // a window ended at the last strobe
  logic cz_men_q = 1'b0;
  logic [15:0] cz_wsize_q = '0;
  // Runs of strobes with every lane 0 or every lane 1, and the snapshot of
  // the failure state at the start of each run.
  int unsigned cz_zrun = 0;
  int unsigned cz_orun = 0;
  logic [7:0] cz_z_hts = '0;
  logic cz_z_tot0 = 1'b0;  // APT_LO and MARKOV_LO totals both 0 at the run start
  logic cz_z_htf = 1'b0;
  logic cz_z_boot = 1'b0;
  logic [7:0] cz_o_hts = '0;
  logic cz_o_ahi0 = 1'b0;
  logic cz_o_boot = 1'b0;
  logic [2:0] cz_z_done = '0;
  logic cz_o_done = 1'b0;
  // Decorrelator input unchanged over the last strobes (cp_byte_mask).
  logic [11:0] cz_ns_prev = '0;
  int unsigned cz_ns_same = 0;

  always @(posedge clk_i) begin
    logic restart;
    cz_win_done <= 1'b0;
    cz_men_q    <= cz_men;
    cz_wsize_q  <= cz_wsize;
    restart = !cz_es_on || !cz_men || (cz_men && !cz_men_q) || (cz_wsize != cz_wsize_q) ||
        !cz_wsize_ok;
    if (restart) begin
      cz_blk_pos  <= '0;
      cz_blk_n    <= '0;
      cz_ln_ones  <= '{default: '0};
      cz_ln_same  <= '1;
      cz_ln_known <= '1;
      cz_zrun     <= 0;
      cz_orun     <= 0;
      cz_ns_same  <= 0;
    end else if (cz_strobe) begin
      logic [11:0] bits;
      logic [11:0] known;
      logic last_blk;
      for (int j = 0; j < 12; j++) begin
        bits[j]  = (esrc_decor_noise_i[j] === 1'b1);
        known[j] = !$isunknown(esrc_decor_noise_i[j]);
      end
      cz_strobes <= cz_strobes + 1;
      last_blk = (cz_blk_pos == 6'd63);
      for (int j = 0; j < 12; j++) begin
        logic [6:0] c;
        logic same;
        c = cz_ln_ones[j] + 7'(bits[j]);
        if (last_blk) begin
          same = (cz_blk_n == 10'd0) ? 1'b1 : (cz_ln_same[j] && (c == cz_ln_first[j]));
          if (cz_blk_n == 10'd0) cz_ln_first[j] <= c;
          cz_ln_last[j] <= c;
          cz_ln_ones[j] <= '0;
          if ((cz_blk_n + 10'd1) == cz_wblocks) begin
            cz_ln_cls_p[j] <= cz_ln_cls[j];
            cz_ln_cls[j] <= (same && cz_ln_known[j] && known[j]) ? cz_cls(c) : CzClsNone;
            cz_ln_same[j] <= 1'b1;
            cz_ln_known[j] <= 1'b1;
          end else begin
            cz_ln_same[j]  <= same;
            cz_ln_known[j] <= cz_ln_known[j] && known[j];
          end
        end else begin
          cz_ln_ones[j]  <= c;
          cz_ln_known[j] <= cz_ln_known[j] && known[j];
        end
      end
      cz_blk_pos <= cz_blk_pos + 6'd1;
      if (last_blk) begin
        if ((cz_blk_n + 10'd1) == cz_wblocks) begin
          cz_blk_n    <= '0;
          cz_win_done <= 1'b1;
        end else begin
          cz_blk_n <= cz_blk_n + 10'd1;
        end
      end
      // Constant runs on all 12 lanes.
      if ((&known) && (bits == 12'h000)) begin
        if (cz_zrun == 0) begin
          cz_z_hts  <= cz_hts;
          cz_z_tot0 <= (cz_tot_alo == 32'h0) && (cz_tot_mlo == 32'h0);
          cz_z_htf  <= cz_ist[0];
          cz_z_boot <= cz_boot;
          cz_z_done <= '0;
        end
        cz_zrun <= cz_zrun + 1;
      end else begin
        cz_zrun <= 0;
      end
      if ((&known) && (bits == 12'hFFF)) begin
        if (cz_orun == 0) begin
          cz_o_hts  <= cz_hts;
          cz_o_ahi0 <= (cz_tot_ahi == 32'h0);
          cz_o_boot <= cz_boot;
          cz_o_done <= 1'b0;
        end
        cz_orun <= cz_orun + 1;
      end else begin
        cz_orun <= 0;
      end
      cz_ns_prev <= esrc_decor_noise_i;
      cz_ns_same <= ((&known) && (esrc_decor_noise_i == cz_ns_prev)) ? cz_ns_same + 1 : 0;
    end
  end

  // ---------------------------------------------------------------------
  // sep_esrc_noise_gen_cg (1.41, 1.43).
  // ---------------------------------------------------------------------
  logic [2:0] cz_dt_wait = '0;
  logic [11:0] cz_dt_pre = '0;
  logic cz_atune_q = 1'b0;
  logic [11:0] cz_detune_q = '0;
  wire cz_dtq_known = !$isunknown(cz_detune_q);
  always @(posedge clk_i) begin
    cz_atune_q  <= cz_atune;
    cz_detune_q <= esrc_detune_i;
    // cp_detune_mode: four clocks after an OKAY write of RING_OSC_TUNE, the
    // effective detune against the stored DETUNE mask.
    if (cy_own_estune && cz_es_on && cz_w1 && (cz_w1_a == ENTROPY_SOURCE_RING_OSC_TUNE_REG_ADDR)) begin
      cz_dt_wait <= 3'd4;
      cz_dt_pre  <= cz_aw_detune;
    end else if (cz_dt_wait != 3'd0) begin
      if (!cy_own_estune || !cz_es_on) begin
        cz_dt_wait <= '0;
      end else if (cz_dt_wait == 3'd1) begin
        logic [11:0] m;
        m = esrc_reg_out_i.RING_OSC_TUNE.DETUNE.value;
        cz_dt_wait <= '0;
        if (!cz_atune && (m == 12'h000) && (esrc_detune_i === 12'h000)) cz_ngen(0, 4'd0);
        else if (!cz_atune && (m != 12'h000) && (esrc_detune_i === m)) cz_ngen(0, 4'd1);
        else if (cz_atune && (m != 12'h000) && (esrc_detune_i === cz_dt_pre) &&
                 (esrc_detune_i !== m)) begin
          cz_ngen(0, 4'd2);
        end
      end else begin
        cz_dt_wait <= cz_dt_wait - 3'd1;
      end
    end
    // cp_detune_lane: with AUTOTUNE_ENABLE 1 on this and the last clock, a
    // detune bit of a lane toggles on the clock after a clock with a failure
    // status of that lane. The generator status input carries a failure as
    // a pulse and the tune state of the lane registers its rise, so the
    // toggle comes one clock after the pulse starts.
    if (cy_own_estune && cz_es_on && cz_atune && cz_atune_q && cz_dt_known && cz_dtq_known) begin
      for (int j = 0; j < 12; j++) begin
        if ((esrc_detune_i[j] != cz_detune_q[j]) && (cz_gst_q[j] != 8'h00)) cz_ngen(1, 4'(j));
      end
    end
    // cp_lane_pattern: the class of each lane at the end of a window.
    if (cy_own_eshp && cz_win_done) begin
      for (int j = 0; j < 12; j++) begin
        case (cz_ln_cls[j])
          CzClsZero: cz_ngen(2, 4'd0);
          CzClsHigh: cz_ngen(2, 4'd1);
          CzClsLow: cz_ngen(2, 4'd2);
          default: ;
        endcase
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_esrc_startup_health_cg (1.40, 1.41, 1.42, 1.44).
  // ---------------------------------------------------------------------
  logic [31:0] cz_cid_rd = '0;
  logic cz_cid_rd_v = 1'b0;
  logic cz_cid_wr = 1'b0;
  logic cz_boot_q = 1'b0;
  logic cz_eb_fall = 1'b0;
  logic cz_re_arm = 1'b0;
  logic [6:0] cz_re_cnt = '0;
  logic cz_re_tot = 1'b0;
  logic cz_tf_arm = 1'b0;
  logic [1:0] cz_tm_kind = '0;
  logic cz_tm_arm = 1'b0;
  int unsigned cz_tm_cnt = 0;
  logic cz_sf_nodig = 1'b0;  // no digest in flight at the MODULE_ENABLE rise
  logic [7:0] cz_hts_q = '0;
  logic [2:0] cz_ht_en_q = '0;
  logic cz_dc_arm = 1'b0;
  longint unsigned cz_dc_t0 = 0;
  localparam logic [31:0] CzCidMask = 32'(ENTROPY_SOURCE_COMPONENT_ID_NAME_MASK |
      ENTROPY_SOURCE_COMPONENT_ID_MAJOR_VERSION_MASK | ENTROPY_SOURCE_COMPONENT_ID_MINOR_VERSION_MASK);
  wire cz_eb_own = cy_own_eshp || cy_own_espa || cy_own_esboot;
  wire cz_men_rise = cz_men && !cz_men_q;
  wire cz_men_fall = !cz_men && cz_men_q;
  wire [31:0] cz_tot_any = cz_tot_rep | cz_tot_ahi | cz_tot_alo | cz_tot_mhi | cz_tot_mlo;
  logic [31:0] cz_tot_rep_q = '0;

  always @(posedge clk_i) begin
    cz_boot_q    <= cz_boot;
    cz_hts_q     <= cz_hts;
    cz_ht_en_q   <= cz_ht_en;
    cz_tot_rep_q <= cz_tot_rep;

    // cp_component_id: a read of COMPONENT_ID, a write of its complement
    // (any response), and a read whose field bits equal the first read.
    if (!cy_own_eswalk) begin
      cz_cid_rd_v <= 1'b0;
      cz_cid_wr   <= 1'b0;
    end else begin
      if (cz_wr_any && (aw_addr_q == ENTROPY_SOURCE_COMPONENT_ID_REG_ADDR)) begin
        cz_cid_wr <= cz_cid_rd_v && (wr_data == ~cz_cid_rd);
      end
      if (rd_ev && (ar_addr_q == ENTROPY_SOURCE_COMPONENT_ID_REG_ADDR) && cy_rd_known) begin
        if (cz_cid_wr && ((rd_data & CzCidMask) == (cz_cid_rd & CzCidMask))) cz_sth(0, 4'd0);
        cz_cid_rd   <= rd_data;
        cz_cid_rd_v <= 1'b1;
        cz_cid_wr   <= 1'b0;
      end
    end

    // x_enable_boot: the MODULE_ENABLE rise (with BOOT_PHASE_DONE), the
    // BOOT_PHASE_DONE rise with MODULE_ENABLE 1, and main_sm_idle after the
    // MODULE_ENABLE fall.
    if (!cz_es_on || !cz_eb_own) begin
      cz_eb_fall <= 1'b0;
    end else begin
      if (cz_men_rise) cz_sth(1, {2'b00, 1'b1, cz_boot});
      if (cz_men && cz_boot && !cz_boot_q && !cz_men_rise) cz_sth(1, 4'b0011);
      if (cz_men_fall) cz_eb_fall <= 1'b1;
      else if (cz_men) cz_eb_fall <= 1'b0;
      else if (cz_eb_fall && cz_idle) begin
        cz_sth(1, 4'b0000);
        cz_eb_fall <= 1'b0;
      end
    end

    // cp_restart_edge and cp_total_fails: a MODULE_ENABLE rise with
    // REPCNT_TOTAL_FAILS non-zero before it. Within CySettle clocks the five
    // totals read 0 (REPCNT alone for cp_total_fails); BOOT_PHASE_DONE rises
    // later with MODULE_ENABLE still 1.
    if (!cz_es_on || !cy_own_esboot || cz_men_fall) begin
      cz_re_arm <= 1'b0;
      cz_tf_arm <= 1'b0;
    end else if (cz_men_rise && (cz_tot_rep_q != 32'h0) && !$isunknown(cz_tot_rep_q)) begin
      cz_re_arm <= 1'b1;
      cz_tf_arm <= 1'b1;
      cz_re_tot <= 1'b0;
      cz_re_cnt <= '0;
    end else begin
      if (cz_tf_arm || (cz_re_arm && !cz_re_tot)) begin
        if (cz_re_cnt >= 7'(CySettle)) begin
          cz_tf_arm <= 1'b0;
          cz_re_tot <= 1'b1;
        end
        cz_re_cnt <= cz_re_cnt + 7'd1;
        if (cz_tf_arm && (cz_tot_rep == 32'h0)) begin
          cz_falt(1, 6'd0);
          cz_tf_arm <= 1'b0;
        end
        if (cz_re_arm && !cz_re_tot && (cz_tot_any == 32'h0)) begin
          cz_sth(2, 4'd0);
          cz_re_tot <= 1'b1;
        end
      end
      if (cz_re_arm && cz_boot && !cz_boot_q) begin
        cz_sth(2, 4'd1);
        cz_re_arm <= 1'b0;
      end
    end

    // cp_startup_fail_hold: a health-test failure pulse in the startup
    // window, and (illegal) a whitener input, a BIW observe push or, with no
    // digest in flight at the MODULE_ENABLE rise, a conditioner output with
    // MODULE_ENABLE 1 and BOOT_PHASE_DONE 0.
    if (cz_men_rise) cz_sf_nodig <= !cz_sha_busy && (cz_sha_out == 4'd0);
    if (cy_own_esboot && cz_es_on && cz_men && cz_men_q && !cz_boot) begin
      if (cy_t(esrc_ht_fail_i)) cz_sth(3, 4'd0);
      if (cz_wpush || cz_bpush || (cz_cvld && cz_sf_nodig)) cz_sth(3, 4'd1);
    end

    // cp_toggle_moment: the class at the MODULE_ENABLE fall; main_sm_idle
    // reads 1 within CzCmdBound clocks.
    if (!cz_es_on || !cy_own_esboot || cz_men_rise) begin
      cz_tm_arm <= 1'b0;
    end else if (cz_men_fall) begin
      cz_tm_arm  <= 1'b1;
      cz_tm_cnt  <= 0;
      cz_tm_kind <= ((cz_tot_rep_q != 32'h0) && !cz_boot_q) ? 2'd2 : (cz_boot_q ? 2'd1 : 2'd0);
    end else if (cz_tm_arm) begin
      if (cz_idle) begin
        cz_sth(4, {2'b00, cz_tm_kind});
        cz_tm_arm <= 1'b0;
      end else if (cz_tm_cnt >= CzCmdBound) begin
        cz_tm_arm <= 1'b0;
      end
      cz_tm_cnt <= cz_tm_cnt + 1;
    end

    // Stored-value points: cp_test_enable_set, cp_window_class.
    if (cy_own_eshp && cz_es_on && cz_sv_ev) begin
      if (cz_ht_en == 3'd6) cz_sth(5, 4'd0);
      if (cz_ht_en == 3'd5) cz_sth(5, 4'd1);
    end
    if ((cy_own_eshp || cy_own_espa) && cz_es_on && cz_sv_ev && !$isunknown(cz_wsize)) begin
      if (cz_wsize < 16'd1024) cz_sth(6, 4'd0);
      else if (cz_wsize == 16'd1024) cz_sth(6, 4'd1);
      else if (cz_wsize == 16'd2048) cz_sth(6, 4'd2);
      else if (cz_wsize > 16'd2048) cz_sth(6, 4'd3);
    end

    // x_tester_side and cp_test_level (1.41). Trip: a generator status bit
    // rises (bit 3 is classed high or low from the ones of the last whole
    // 64-strobe block of the lane). Pass: two windows in a row of the same
    // biased class end with bits 0, 4 and 5 clear and the tester enabled.
    if (cy_own_eshp && cz_es_on) begin
      logic gen_rise;
      gen_rise = 1'b0;
      for (int j = 0; j < 12; j++) begin
        logic [7:0] r;
        r = cz_gst[j] & ~cz_gst_q[j];
        if (!$isunknown(cz_gst[j]) && (r != 8'h00)) begin
          gen_rise = 1'b1;
          if (r[0]) cz_sth(7, 4'b000_0);
          if (r[4]) cz_sth(7, 4'b011_0);
          if (r[5]) cz_sth(7, 4'b100_0);
          if (r[3] && (cz_ln_last[j] > 7'd32)) cz_sth(7, 4'b001_0);
          if (r[3] && (cz_ln_last[j] < 7'd32)) cz_sth(7, 4'b010_0);
        end
        if (cz_win_done && ((cz_ln_cls[j] == CzClsHigh) || (cz_ln_cls[j] == CzClsLow)) &&
            (cz_ln_cls[j] == cz_ln_cls_p[j]) && ((cz_gst[j] & 8'h31) == 8'h00)) begin
          if (cz_ht_en[0]) cz_sth(7, 4'b000_1);
          if (cz_ht_en[2]) cz_sth(7, 4'b011_1);
          if (cz_ht_en[2]) cz_sth(7, 4'b100_1);
        end
      end
      if (gen_rise) cz_sth(8, 4'd0);
      if (!$isunknown(cz_hts) && ((cz_hts[3] && !cz_hts_q[3]) || (cz_hts[5] && !cz_hts_q[5]))) begin
        cz_sth(8, 4'd1);
      end
    end

    // cp_top_failure_set: a run of at least one window of strobes with every
    // lane 0 (or 1) that starts after BOOT_PHASE_DONE; the failure state was
    // clear at the run start and is set at the sample.
    if (cy_own_eshp && cz_es_on && cz_wsize_ok) begin
      if (cz_z_boot && (cz_zrun >= int'(cz_wsize))) begin
        if (!cz_z_done[0] && cz_hts[3] && cz_hts[5] && !(cz_z_hts[3] && cz_z_hts[5])) begin
          cz_sth(9, 4'd0);
          cz_z_done[0] <= 1'b1;
        end
        if (!cz_z_done[1] && cz_z_tot0 && (cz_tot_alo != 32'h0) && (cz_tot_mlo != 32'h0) &&
            cz_lo_tot_known) begin
          cz_sth(9, 4'd1);
          cz_z_done[1] <= 1'b1;
        end
        if (!cz_z_done[2] && !cz_z_htf && cz_ist[0]) begin
          cz_sth(9, 4'd2);
          cz_z_done[2] <= 1'b1;
        end
      end
      if (cz_o_boot && (cz_orun >= int'(cz_wsize)) && !cz_o_done && cz_o_ahi0 && cz_hts[3] &&
          !cz_o_hts[3] && (cz_tot_ahi != 32'h0) && cz_hi_tot_known) begin
        cz_sth(9, 4'd3);
        cz_o_done <= 1'b1;
      end
    end

    // cp_disable_clears (not graded): HEALTH_TEST_CTRL.ENABLE bit 0 falls
    // while the repetition count is non-zero; one window of strobes later the
    // count is recorded as 0 or non-zero.
    if (!cy_own_eshp || !cz_es_on || cz_ht_en[0]) begin
      cz_dc_arm <= 1'b0;
    end else if (!cz_ht_en[0] && cz_ht_en_q[0] && (cz_rep_cnt != 16'h0) && cz_rep_known) begin
      cz_dc_arm <= 1'b1;
      cz_dc_t0  <= cz_strobes;
    end else if (cz_dc_arm && cz_wsize_ok && ((cz_strobes - cz_dc_t0) >= longint'(cz_wsize))) begin
      cz_sth(10, (cz_rep_cnt == 16'h0) ? 4'd0 : 4'd1);
      cz_dc_arm <= 1'b0;
    end

    // cp_prestage_test: an OKAY FIFO_RDATA read with whitening on, every
    // lane stuck at 0, and HEALTH_TEST_STATUS bit 0 set in this run.
    if (cy_own_eshp && cz_es_on && rd_ev && (ar_addr_q == ENTROPY_SOURCE_FIFO_RDATA_REG_ADDR) &&
        cz_whiten && (cz_zrun != 0) && cz_hts[0] && !cz_z_hts[0]) begin
      cz_sth(11, 4'd0);
    end
  end

  // ---------------------------------------------------------------------
  // sep_esrc_fault_alert_cg (1.40, 1.41, 1.42, 1.43, 1.44, 1.46).
  // ---------------------------------------------------------------------
  logic [15:0] cz_af_q = '0;
  logic [15:0] cz_af_peak = '0;
  logic cz_af_alert = 1'b0;
  logic cz_af_men = 1'b0;  // MODULE_ENABLE stayed 1 since the burst start
  longint unsigned cz_af_t_start = 0;
  logic [15:0] cz_af_prev_peak = '0;
  longint unsigned cz_af_prev_end = 0;
  logic cz_af_prev_v = 1'b0;
  logic cz_afc_on = 1'b0;  // esrc_af_clear_bound seen non-zero
  // Strobes up to the clock before the first clock that saw it; the strobe of
  // the last clock (cz_strobe) is added on both ends, so the count matches the
  // word count of the leaf at its write.
  longint unsigned cz_afc_t0 = 0;
  logic cz_sm_alert_q = 1'b0;
  logic cz_hang = 1'b0;  // AlertHang entered, no exit yet
  logic cz_hg_arm = 1'b0;  // entry: waiting for the halt hold
  logic cz_hg_pf = 1'b0;
  int unsigned cz_hg_cnt = 0;
  logic cz_wc_alert = 1'b0;  // write of 1 to MAIN_SM_STATUS.ALERT in AlertHang
  logic cz_wc_pf = 1'b0;  // PERSISTENT_FAILURE cleared by a write of 1 in AlertHang
  logic cz_wc_arm = 1'b0;
  int unsigned cz_wc_cnt = 0;
  logic cz_ex_men = 1'b0;
  logic cz_ex_men_up = 1'b0;
  logic cz_ex_rst = 1'b0;
  logic [6:0] cz_flvl_q = '0;
  // cp_autotune.
  logic [11:0] cz_au_off = '0;
  logic [11:0] cz_au_off_bad = '0;
  logic [11:0] cz_au_on = '0;
  logic [11:0] cz_au_tog = '0;
  logic [1:0] cz_au_burst = '0;
  longint unsigned cz_au_last_tog = 0;
  logic cz_au_any_tog = 1'b0;
  // A lane status rises from 0 at this clock; the tune FSM of the lane
  // toggles its detune on that rise. History of the last two clocks.
  logic [11:0] cz_au_rise_now;
  always_comb begin
    for (int j = 0; j < 12; j++) begin
      cz_au_rise_now[j] = (cz_gst[j] != 8'h00) && (cz_gst_q[j] == 8'h00) && !$isunknown(cz_gst[j]);
    end
  end
  logic [11:0] cz_au_rise[2] = '{default: '0};
  // cp_fifo_integrity.
  logic cz_par_q = 1'b0;
  logic cz_ptr_q = 1'b0;
  logic cz_par_arm = 1'b0;
  logic cz_ptr_arm = 1'b0;
  logic cz_ptr_taint = 1'b0;  // from a pointer-copy inject to the next TRNG reset
  logic [11:0] cz_g3_rd1 = '0;  // the last OKAY read of the lane status had bit 3 set
  logic [11:0] cz_g3_w1 = '0;  // then a write of 1 to bit 3 of that status
  logic [3:0] cz_par_rec = '0;
  logic [3:0] cz_ovf_rec = '0;
  localparam logic [31:0] CzAlertMask = 32'(ENTROPY_SOURCE_MAIN_SM_STATUS_ALERT_MASK);

  always @(posedge clk_i) begin
    logic sm_alert;
    sm_alert = cy_t(esrc_sm_alert_i);
    cz_sm_alert_q <= sm_alert;
    cz_af_q       <= cz_any_fail;
    cz_flvl_q     <= cz_flvl;
    cz_par_q      <= esrc_par_inj_i;
    cz_ptr_q      <= esrc_ptr_inj_i;
    cz_par_rec    <= {cz_par_rec[2:0], esrc_par_inj_i};
    cz_ovf_rec    <= {cz_ovf_rec[2:0], cy_t(esrc_fifo_ovf_i)};

    // x_gen_latch (1.41): bit 3 latched per lane, bit 3 cleared by a write
    // of 1 to the status of the lane, and bits 0, 4, 5 latched on all lanes.
    // The status input carries a failure as a pulse, not the latched field
    // (sw rw, hw w), so the cleared cell is taken from the read data: an
    // OKAY read with bit 3 set, a write of 1 to bit 3, then the next OKAY
    // read of that status with bit 3 clear.
    if (!cy_own_eshp || !cz_es_on) begin
      cz_g3_rd1 <= '0;
      cz_g3_w1  <= '0;
    end else begin
      if (wr_ev && (cz_gen_lane(aw_addr_q) >= 0)) begin
        int j;
        j = cz_gen_lane(aw_addr_q);
        cz_g3_w1[j] <= cz_g3_rd1[j] && wr_data[3];
      end
      if (rd_ev && cy_rd_known && (cz_gen_lane(ar_addr_q) >= 0)) begin
        int j;
        j = cz_gen_lane(ar_addr_q);
        if (cz_g3_w1[j] && !rd_data[3]) cz_falt(0, {2'b01, 4'(j)});
        cz_g3_rd1[j] <= rd_data[3];
        cz_g3_w1[j]  <= 1'b0;
      end
    end
    if (cy_own_eshp && cz_es_on) begin
      for (int j = 0; j < 12; j++) begin
        if ((cz_gst[j][3] === 1'b1) && (cz_gst_q[j][3] === 1'b0)) cz_falt(0, {2'b00, 4'(j)});
      end
      for (int b = 0; b < 3; b++) begin
        int unsigned k;
        logic all_now;
        logic all_q;
        k = (b == 0) ? 0 : ((b == 1) ? 4 : 5);
        all_now = 1'b1;
        all_q = 1'b1;
        for (int j = 0; j < 12; j++) begin
          all_now &= (cz_gst[j][k] === 1'b1);
          all_q &= (cz_gst_q[j][k] === 1'b1);
        end
        if (all_now && !all_q) cz_falt(0, {2'b10, 4'(b)});
      end
    end

    // cp_alert_threshold (1.42): the stored value at the stored-value
    // trigger and at an OKAY read of ALERT_THRESHOLD.
    if (cy_own_espa && cz_es_on && cz_thr_known &&
        (cz_sv_ev || (rd_ev && (ar_addr_q == ENTROPY_SOURCE_ALERT_THRESHOLD_REG_ADDR)))) begin
      case (cz_thr)
        16'd0: cz_falt(2, 6'd0);
        16'd4: cz_falt(2, 6'd1);
        16'd5: cz_falt(2, 6'd2);
        16'd7: cz_falt(2, 6'd3);
        default: ;
      endcase
    end

    // cp_any_fail and the "no entry" cells of cp_alert_hang (1.42). A burst
    // runs from an ANY_FAIL_COUNT rise from 0 to its fall to 0 with
    // MODULE_ENABLE 1 throughout. "Falls to 0" samples a fall at most
    // esrc_af_clear_bound strobes after the first clock that saw the bound, the
    // count-clear bound that the leaf writes after the last failing word.
    if (esrc_af_clear_bound == 0) begin
      cz_afc_on <= 1'b0;
    end else if (!cz_afc_on) begin
      cz_afc_on <= 1'b1;
      cz_afc_t0 <= cz_strobes + longint'(cz_strobe);
    end
    if (!cy_own_espa || !cz_es_on || $isunknown(cz_any_fail)) begin
      cz_af_peak    <= '0;
      cz_af_alert   <= 1'b0;
      cz_af_men     <= 1'b0;
      cz_af_prev_v  <= 1'b0;
    end else begin
      if (cz_any_fail > cz_af_q) begin
        if (cz_thr != 16'd0) cz_falt(3, (cz_any_fail < cz_thr) ? 6'd0 : 6'd1);
        else if ((cz_any_fail > 16'd8) && (cz_af_q <= 16'd8)) cz_falt(3, 6'd2);
        if (cz_af_q == 16'h0) begin
          cz_af_peak    <= cz_any_fail;
          cz_af_alert   <= 1'b0;
          cz_af_men     <= cz_men;
          cz_af_t_start <= cz_strobes;
        end else if (cz_any_fail > cz_af_peak) begin
          cz_af_peak <= cz_any_fail;
        end
      end
      if (sm_alert && !cz_sm_alert_q) cz_af_alert <= 1'b1;
      if (!cz_men) cz_af_men <= 1'b0;
      if ((cz_any_fail == 16'h0) && (cz_af_q != 16'h0) && cz_af_men && cz_men && cz_wsize_ok) begin
        if (cz_afc_on &&
            ((cz_strobes + longint'(cz_strobe) - cz_afc_t0) <= longint'(esrc_af_clear_bound))) begin
          cz_falt(3, 6'd3);
        end
        if (!cz_af_alert) begin
          if (cz_thr != 16'd0) begin
            if (cz_af_prev_v && ((cz_af_t_start - cz_af_prev_end) <= 5 * longint'(cz_wsize)) &&
                (32'(cz_af_prev_peak) + 32'(cz_af_peak) >= 32'(cz_thr))) begin
              cz_falt(4, 6'd2);
            end
            if (cz_af_peak < cz_thr) cz_falt(4, 6'd1);
          end else if (cz_af_peak > 16'd8) begin
            cz_falt(4, 6'd3);
          end
        end
        cz_af_prev_peak <= cz_af_peak;
        cz_af_prev_end  <= cz_strobes;
        cz_af_prev_v    <= !cz_af_alert;
      end
    end

    // cp_alert_hang entry and exits (1.42). AlertHang starts at the
    // main_sm_alert rise and ends at a MODULE_ENABLE fall or a TRNG reset.
    if (cz_trng || !cy_ip[5]) begin
      if (cz_hang && cy_own_espa) cz_ex_rst <= 1'b1;
      cz_hang   <= 1'b0;
      cz_hg_arm <= 1'b0;
      cz_wc_arm <= 1'b0;
      cz_wc_alert <= 1'b0;
      cz_wc_pf <= 1'b0;
      cz_ex_men <= 1'b0;
    end else begin
      if (sm_alert && !cz_sm_alert_q && cz_men) begin
        cz_hang   <= 1'b1;
        cz_hg_arm <= cy_own_espa;
        cz_hg_pf  <= 1'b0;
        cz_hg_cnt <= 0;
      end
      // Entry: PERSISTENT_FAILURE is set, and with no digest in flight the
      // FIFO level does not rise for CzHangHold clocks.
      if (cz_hg_arm) begin
        logic pf;
        pf = cz_hg_pf || cz_ist[4];
        cz_hg_pf <= pf;
        if (!cy_own_espa || !cz_men || ((cz_flvl > cz_flvl_q) && !cz_sha_busy)) begin
          cz_hg_arm <= 1'b0;
        end else if (cz_sha_busy || (cz_sha_out != 4'd0)) begin
          cz_hg_cnt <= 0;
        end else if (cz_hg_cnt >= CzHangHold) begin
          if (pf) cz_falt(4, 6'd0);
          cz_hg_arm <= 1'b0;
        end else begin
          cz_hg_cnt <= cz_hg_cnt + 1;
        end
      end
      // Write-one clear in AlertHang: a write of 1 to MAIN_SM_STATUS.ALERT
      // and the PERSISTENT_FAILURE fall by a write of 1; the FIFO level then
      // does not rise for CzHangHold clocks, or up to the MODULE_ENABLE fall
      // that ends the hang if that comes first.
      if (cz_hang && cy_own_espa && cz_men) begin
        logic wa;
        logic wp;
        wa = cz_wc_alert || (cz_w1 && (cz_w1_a == ENTROPY_SOURCE_MAIN_SM_STATUS_REG_ADDR) &&
            ((cz_w1_d & CzAlertMask) != 32'h0));
        wp = (cz_wc_pf && !cz_ist[4]) || (cz_w1 && (cz_w1_a == ENTROPY_SOURCE_INTR_STATUS_REG_ADDR) &&
            ((cz_w1_d & 32'(ENTROPY_SOURCE_INTR_STATUS_PERSISTENT_FAILURE_MASK)) != 32'h0) &&
            cz_aw_ist[4] && !cz_ist[4]);
        cz_wc_alert <= wa;
        cz_wc_pf    <= wp;
        if (wa && wp && !cz_wc_arm) begin
          cz_wc_arm <= 1'b1;
          cz_wc_cnt <= 0;
        end
        if (cz_wc_arm) begin
          if ((cz_flvl > cz_flvl_q) || cz_ist[4]) begin
            cz_wc_arm <= 1'b0;
          end else if (cz_wc_cnt >= CzHangHold) begin
            cz_falt(4, 6'd4);
            cz_wc_arm <= 1'b0;
          end else begin
            cz_wc_cnt <= cz_wc_cnt + 1;
          end
        end
      end else begin
        if (cz_wc_arm && cz_hang && cy_own_espa && cz_men_fall) cz_falt(4, 6'd4);
        cz_wc_arm <= 1'b0;
      end
      if (cz_men_fall) begin
        cz_ex_rst    <= 1'b0;
        cz_ex_men    <= cz_hang && cy_own_espa;
        cz_ex_men_up <= 1'b0;
        cz_hang      <= 1'b0;
        cz_hg_arm    <= 1'b0;
        cz_wc_alert  <= 1'b0;
        cz_wc_pf     <= 1'b0;
      end
      if (cz_ex_men) begin
        if (cz_men_rise) cz_ex_men_up <= 1'b1;
        if (cz_ex_men_up && cz_men && cz_boot && !cz_boot_q) begin
          if (cy_own_espa) cz_falt(4, 6'd5);
          cz_ex_men <= 1'b0;
        end
      end
      // Exit by TRNG reset: after the reset, with MODULE_ENABLE at its reset
      // value 1 and no MODULE_ENABLE fall, BOOT_PHASE_DONE rises (the main
      // state machine runs the startup test again) with PERSISTENT_FAILURE 0.
      if (cz_ex_rst && cz_men && cz_boot && !cz_boot_q) begin
        if (!cz_ist[4] && cy_own_espa) cz_falt(4, 6'd6);
        cz_ex_rst <= 1'b0;
      end
    end
    if (cz_ended(FcovOwnSepEsrcPersistentAlertRandTest)) cz_ex_rst <= 1'b0;

    // cp_autotune (1.43). A lane fails: its generator status rises from 0.
    // Autotune off: at the write-one clear of that status, AUTOTUNE_FAIL
    // stayed 0 and the detune did not change since the failure. Autotune
    // on: AUTOTUNE_FAIL is set and the detune bit of the lane toggled. A
    // burst is a group of toggles of the lane; a gap of CzTuneGap strobes
    // with no toggle ends it. Illegal: with autotune on, the detune bit of a
    // lane changes with no rise of that lane's status just before. The lane
    // status is a failure pulse, so it can be 0 again at the toggle.
    if (!cy_own_estune || !cz_es_on) begin
      cz_au_off   <= '0;
      cz_au_on    <= '0;
      cz_au_tog   <= '0;
      cz_au_burst <= '0;
      cz_au_any_tog <= 1'b0;
    end else begin
      logic [11:0] tog;
      tog = '0;
      if (cz_dt_known && cz_dtq_known) tog = esrc_detune_i ^ cz_detune_q;
      if (cz_atune && !cz_atune_q) begin
        cz_au_burst   <= '0;
        cz_au_any_tog <= 1'b0;
      end
      for (int j = 0; j < 12; j++) begin
        logic fail;
        fail = (cz_gst[j] != 8'h00) && (cz_gst_q[j] == 8'h00) && !$isunknown(cz_gst[j]);
        if (fail && !cz_atune && !cz_ist[5]) begin
          cz_au_off[j]     <= 1'b1;
          cz_au_off_bad[j] <= 1'b0;
        end else if (cz_au_off[j]) begin
          if (cz_ist[5] || tog[j] || cz_atune) cz_au_off_bad[j] <= 1'b1;
          if ((cz_gst[j] == 8'h00) && (cz_gst_q[j] != 8'h00)) begin
            if (!cz_au_off_bad[j] && !cz_ist[5] && !tog[j]) cz_falt(5, 6'd0);
            cz_au_off[j] <= 1'b0;
          end
        end
        if (fail && cz_atune) begin
          cz_au_on[j]  <= 1'b1;
          cz_au_tog[j] <= 1'b0;
        end else if (cz_au_on[j]) begin
          logic t;
          t = cz_au_tog[j] || (tog[j] && cz_atune_q);
          cz_au_tog[j] <= t;
          if (t && cz_ist[5]) begin
            cz_falt(5, 6'd1);
            cz_au_on[j] <= 1'b0;
          end
        end
      end
      if (cz_atune && cz_atune_q && (tog != 12'h000)) begin
        logic new_burst;
        new_burst = !cz_au_any_tog || ((cz_strobes - cz_au_last_tog) >= longint'(CzTuneGap));
        cz_au_any_tog  <= 1'b1;
        cz_au_last_tog <= cz_strobes;
        if (new_burst && (cz_au_burst != 2'd3)) begin
          if (cz_au_burst <= 2'd2) cz_falt(5, 6'(2 + cz_au_burst));
          cz_au_burst <= cz_au_burst + 2'd1;
        end
      end
      // Illegal: with autotune on, a toggle of a lane with no rise of that
      // lane's status at this clock or the two clocks before it.
      if (cz_atune && cz_atune_q) begin
        for (int j = 0; j < 12; j++) begin
          if (tog[j] && !cz_au_rise_now[j] && !cz_au_rise[0][j] && !cz_au_rise[1][j]) begin
            cz_falt(5, 6'd7);
          end
        end
      end
    end
    cz_au_rise[0] <= cz_au_rise_now;
    cz_au_rise[1] <= cz_au_rise[0];

    // cp_fifo_flags. Overflow (1.46): FIFO_OVERFLOW rises after an overflow
    // push with no INTR_TEST write. Proper-subset clear (1.40): a write of 1
    // to a subset C that holds bits 8 and 12 of the set status bits S, with
    // C a proper subset of S, leaves exactly S & ~C.
    if (cy_own_esfifo && cz_es_on && cz_ist_rise[2] && !cz_itst_rec[2] && (cz_ovf_rec != 4'h0)) begin
      cz_falt(6, 6'd0);
    end
    if (cy_own_eswalk && cz_es_on && cz_w1 && (cz_w1_a == ENTROPY_SOURCE_INTR_STATUS_REG_ADDR)) begin
      logic [7:0] c;
      for (int i = 0; i < 8; i++) c[i] = cz_w1_d[4*i];
      if (c[2] && c[3] && ((c & ~cz_aw_ist) == 8'h00) && (c != cz_aw_ist) &&
          (cz_ist == (cz_aw_ist & ~c))) begin
        cz_falt(6, 6'd1);
      end
    end

    // cp_fifo_integrity (1.46). Parity: FIFO_ERROR, 0 at the inject rise,
    // reads 1 at a FIFO_RDATA pop during the inject. Pointer: FIFO_ERROR, 0
    // at the inject rise, rises during the inject. Write-one clear: the
    // fall of FIFO_ERROR by a write of 1. Illegal: a rise with no inject, no
    // INTR_TEST write, and no pointer inject since the last TRNG reset.
    if (cz_trng || !cy_ip[5]) cz_ptr_taint <= 1'b0;
    else if (esrc_ptr_inj_i) cz_ptr_taint <= 1'b1;
    if (!cy_own_esfifo || !cz_es_on) begin
      cz_par_arm <= 1'b0;
      cz_ptr_arm <= 1'b0;
    end else begin
      if (esrc_par_inj_i && !cz_par_q) cz_par_arm <= !cz_ist[1];
      if (!esrc_par_inj_i) cz_par_arm <= 1'b0;
      if (cz_par_arm && esrc_par_inj_i && rd_ev && (ar_addr_q == ENTROPY_SOURCE_FIFO_RDATA_REG_ADDR)) begin
        if (cz_ist[1]) cz_falt(7, 6'd0);
        cz_par_arm <= 1'b0;
      end
      if (esrc_ptr_inj_i && !cz_ptr_q) cz_ptr_arm <= !cz_ist[1];
      if (!esrc_ptr_inj_i) cz_ptr_arm <= 1'b0;
      if (cz_ptr_arm && esrc_ptr_inj_i && cz_ist_rise[1]) begin
        cz_falt(7, 6'd1);
        cz_ptr_arm <= 1'b0;
      end
      if (cz_w1 && (cz_w1_a == ENTROPY_SOURCE_INTR_STATUS_REG_ADDR) && cz_w1_d[4] && cz_aw_ist[1] &&
          !cz_ist[1]) begin
        cz_falt(7, 6'd2);
      end
      if (cz_ist_rise[1] && !cz_itst_rec[1] && (cz_par_rec == 4'h0) && !esrc_par_inj_i &&
          !cz_ptr_taint && !esrc_ptr_inj_i) begin
        cz_falt(7, 6'd3);
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_esrc_conditioning_cg (1.45, 1.46, 1.47).
  // ---------------------------------------------------------------------
  logic cz_sc_on = 1'b0;  // whitening-off interval
  logic cz_sc_bad = 1'b0;
  int unsigned cz_sc_words = 0;
  logic [3:0] cz_sha_out_q = '0;
  logic cz_churn_q = 1'b0;
  int unsigned cz_churn_push = 0;
  logic cz_ca_done = 1'b0;
  logic [5:0] cz_fwp_q = '0;
  logic [5:0] cz_frp_q = '0;
  logic [1:0] cz_oc_raw0 = '0;  // RAW_ENABLE 0 interval with no push, [0] noise, [1] biw
  int unsigned cz_oc_cnt[2] = '{default: 0};
  logic [3:0] cz_lane_eff_q = '0;
  logic [3:0] cz_lane_eff_q2 = '0;
  logic cz_flush_q = 1'b0;
  logic [1:0] cz_of_pend = '0;  // {pending, kind}
  logic cz_lk_pend = 1'b0;
  logic [6:0] cz_of_lvl = '0;
  localparam logic [11:0] CzBypassAll = 12'hFFF;
  wire [7:0] cz_bmask = esrc_reg_out_i.DECORRELATOR_MASK.ENTROPY_BYTE_MASK.value;
  wire cz_bmask_known = !$isunknown(cz_bmask);
  wire cz_bypass_all = (esrc_reg_out_i.DECORRELATOR_CTRL.BYPASS.value == CzBypassAll);
  wire cz_churn = cy_t(esrc_reg_out_i.FIFO_CTRL.ENTROPY_CHURN_ENABLE.value);
  wire cz_fen = cy_t(esrc_reg_out_i.FIFO_CTRL.ENABLE.value);
  wire [9:0] cz_drate = esrc_reg_out_i.CTRL.DOWNSAMPLE_RATE.value;
  wire [3:0] cz_lane_sel = esrc_reg_out_i.NOISE_OBS_CTRL.LANE_SEL.value;
  // The effective observe lane matches the stored LANE_SEL (12 to 15 select lane 0).
  wire cz_lane_ok = (esrc_noise_obs_lane_i === ((cz_lane_sel < 4'd12) ? cz_lane_sel : 4'd0));
  wire cz_flush = cy_t(esrc_reg_out_i.NOISE_OBS_CTRL.FLUSH.value);
  wire cz_nflush = cy_t(esrc_noise_obs_flush_i);

  always @(posedge clk_i) begin
    logic [1:0] raw;
    raw = cz_raw;
    cz_sha_out_q  <= cz_sha_out;
    cz_churn_q    <= cz_churn;
    cz_fwp_q      <= cz_fwp;
    cz_frp_q      <= cz_frp;
    cz_lane_eff_q <= esrc_noise_obs_lane_i;
    cz_lane_eff_q2 <= cz_lane_eff_q;
    cz_flush_q    <= cz_flush;

    // cp_byte_mask (1.45): at a strobe with every lane bypassed and the
    // lane input unchanged for four strobes, each lane byte equals its
    // input bit in all eight bits ANDed with the stored mask.
    if (cy_own_escond && cz_es_on && cz_men && cz_strobe && (cz_ns_same >= 4) && cz_bypass_all &&
        cz_bmask_known) begin
      logic ok;
      ok = 1'b1;
      for (int j = 0; j < 12; j++) begin
        ok &= (esrc_decor_bytes_i[8*j+:8] === ({8{esrc_decor_noise_i[j]}} & cz_bmask));
      end
      if (ok && (cz_bmask == 8'hFF)) cz_cond(0, 4'd0);
      else if (ok && (cz_bmask != 8'h00)) cz_cond(0, 4'd1);
    end

    // Stored-value points: x_path_matrix, cp_downsample_rate (1.45),
    // cp_fifo_ctrl (1.46), cp_obs_lane_sel (1.47, with the effective lane
    // that the observe path uses: 12 to 15 select lane 0).
    if (cz_es_on && cz_sv_ev) begin
      if (cy_own_escond) begin
        cz_cond(1, {2'b00, cz_bypass, cz_whiten});
        if (cz_bypass && !$isunknown(cz_drate)) begin
          if (cz_drate == 10'd0) cz_cond(2, 4'd0);
          else if (cz_drate == 10'd1) cz_cond(2, 4'd1);
          else if (cz_drate <= 10'd15) cz_cond(2, 4'd2);
          else if (cz_drate == 10'd1023) cz_cond(2, 4'd3);
        end
      end
      if (cy_own_esfifo) cz_cond(5, {2'b00, cz_fen, cz_churn});
      if (cy_own_esobs && cz_lane_ok) begin
        cz_cond(8, cz_lane_sel);
      end
    end

    // cp_sha_counts (1.45). OUTPUT_COUNT reaches 8 and falls to 0. With
    // whitening off, the interval from a clear conditioner to the next
    // whitening rise, TRNG reset or window close keeps OUTPUT_COUNT 0 while
    // pass-through words leave the conditioner.
    if (cy_own_escond && cz_es_on && !$isunknown(cz_sha_out)) begin
      if ((cz_sha_out == 4'd8) && (cz_sha_out_q != 4'd8)) cz_cond(3, 4'd0);
      if ((cz_sha_out == 4'd0) && (cz_sha_out_q != 4'd0)) cz_cond(3, 4'd1);
    end
    if (cz_sc_on) begin
      if (cz_ended(FcovOwnSepEsrcConditioningMatrixRandTest) || cz_whiten || !cz_es_on) begin
        if (!cz_sc_bad && (cz_sc_words != 0)) cz_cond(3, 4'd2);
        cz_sc_on <= 1'b0;
      end else begin
        if (cz_sha_out != 4'd0) cz_sc_bad <= 1'b1;
        if (cz_cvld) cz_sc_words <= cz_sc_words + 1;
      end
    end else if (cy_own_escond && cz_es_on && cz_men && !cz_whiten && !cz_sha_busy &&
                 (cz_sha_out == 4'd0)) begin
      cz_sc_on    <= 1'b1;
      cz_sc_bad   <= 1'b0;
      cz_sc_words <= 0;
    end

    // cp_fifo_occupancy (1.46): level and pointer events of the main FIFO.
    if (cy_own_esfifo && cz_es_on && !$isunknown({cz_flvl, cz_fwp, cz_frp})) begin
      if (cz_flvl != cz_flvl_q) begin
        case (cz_flvl)
          7'd0: cz_cond(4, 4'd0);
          7'd1: cz_cond(4, 4'd1);
          7'd32: cz_cond(4, 4'd2);
          7'd63: cz_cond(4, 4'd3);
          7'd64: cz_cond(4, 4'd4);
          default: ;
        endcase
        if ((cz_flvl == 7'd64) && (cz_fwp == cz_frp)) cz_cond(4, 4'd7);
        if ((cz_flvl == 7'd0) && (cz_fwp == cz_frp)) cz_cond(4, 4'd8);
      end
      if ((cz_fwp == 6'd0) && (cz_fwp_q == 6'd63)) cz_cond(4, 4'd5);
      if ((cz_frp == 6'd0) && (cz_frp_q == 6'd63)) cz_cond(4, 4'd6);
    end

    // cp_churn_age (1.46): a push (write-pointer step) with churn on after
    // at least 32 pushes since the churn enable.
    if (!cz_es_on || !cz_churn) begin
      cz_churn_push <= 0;
      cz_ca_done    <= 1'b0;
    end else if (cz_churn && !cz_churn_q) begin
      cz_churn_push <= 0;
      cz_ca_done    <= 1'b0;
    end else if (cz_fwp != cz_fwp_q) begin
      if ((cz_churn_push >= 32) && !cz_ca_done && cy_own_esfifo) begin
        cz_cond(6, 4'd0);
        cz_ca_done <= 1'b1;
      end
      cz_churn_push <= cz_churn_push + 1;
    end

    // x_obs_capture (1.47): {path, RAW_ENABLE, after BOOT_PHASE_DONE, push}.
    // A push samples its cell; a RAW_ENABLE 0 interval of CzObsQuiet strobes
    // with the module running and no push samples the no-push cell.
    if (cy_own_esobs && cz_es_on && cz_men) begin
      if (cz_npush) cz_cond(7, {1'b0, raw[0], cz_boot, 1'b1});
      if (cz_bpush) cz_cond(7, {1'b1, raw[1], cz_boot, 1'b1});
      for (int f = 0; f < 2; f++) begin
        logic push;
        push = (f == 0) ? cz_npush : cz_bpush;
        if (raw[f] || push) begin
          cz_oc_raw0[f] <= 1'b0;
          cz_oc_cnt[f]  <= 0;
        end else if (!cz_oc_raw0[f]) begin
          if (cz_strobe) cz_oc_cnt[f] <= cz_oc_cnt[f] + 1;
          if (cz_oc_cnt[f] >= CzObsQuiet) begin
            cz_cond(7, {1'(f), 3'b000});
            cz_oc_raw0[f] <= 1'b1;
          end
        end
      end
    end else begin
      cz_oc_raw0 <= '0;
      cz_oc_cnt  <= '{default: 0};
    end

    // cp_obs_flush and cp_obs_lock (1.47): a flush pulse of the noise
    // observe FIFO with words buffered, by a FLUSH write or by a change of
    // the effective lane; the level is lower on the next clock.
    if (cz_of_pend[1]) begin
      if (cy_own_esobs && (esrc_noise_obs_level_i < cz_of_lvl)) begin
        cz_cond(9, {3'b000, cz_of_pend[0]});
        if (cz_lk_pend && !cz_of_pend[0]) cz_cond(11, 4'd0);
      end
      cz_of_pend <= '0;
      cz_lk_pend <= 1'b0;
    end else if (cy_own_esobs && cz_es_on && cz_nflush && (cz_nlvl_q != 7'd0)) begin
      if (cz_flush || cz_flush_q) begin
        cz_of_pend <= 2'b10;
        cz_lk_pend <= cz_lock;
        cz_of_lvl  <= cz_nlvl_q;
      end else if ((esrc_noise_obs_lane_i !== cz_lane_eff_q) ||
                   (cz_lane_eff_q !== cz_lane_eff_q2)) begin
        cz_of_pend <= 2'b11;
        cz_lk_pend <= 1'b0;
        cz_of_lvl  <= cz_nlvl_q;
      end
    end

    // cp_obs_overflow (1.47): the overflow status of each observe FIFO
    // rises with no INTR_TEST write, and falls by a write of 1.
    if (cy_own_esobs && cz_es_on) begin
      if (cz_ist_rise[7] && !cz_itst_rec[7]) cz_cond(10, 4'b0000);
      if (cz_ist_rise[6] && !cz_itst_rec[6]) cz_cond(10, 4'b0010);
      if (cz_w1 && (cz_w1_a == ENTROPY_SOURCE_INTR_STATUS_REG_ADDR)) begin
        if (((cz_w1_d & 32'(ENTROPY_SOURCE_INTR_STATUS_NOISE_OBS_OVERFLOW_MASK)) != 32'h0) &&
            cz_aw_ist[7] && !cz_ist[7])
          cz_cond(10, 4'b0001);
        if (((cz_w1_d & 32'(ENTROPY_SOURCE_INTR_STATUS_BIW_OBS_OVERFLOW_MASK)) != 32'h0) &&
            cz_aw_ist[6] && !cz_ist[6])
          cz_cond(10, 4'b0011);
      end
    end
  end

  // ---------------------------------------------------------------------
  // CSRNG and EDN error codes. A set request is the de/d pair of an
  // ERR_CODE field; the vector carries it at the register bit of the field.
  // ---------------------------------------------------------------------
  longint unsigned cz_clk = 0;
  // ERR_CODE field bits in the order of the packed hw2reg err_code pairs,
  // pair 0 at the low end; each pair is {d, de}.
  localparam logic [31:0] CzCsErrBits[10] = '{
      32'(CSRNG_ERR_CODE_SFIFO_CMD_ERR_MASK),
      32'(CSRNG_ERR_CODE_SFIFO_GENBITS_ERR_MASK),
      32'(CSRNG_ERR_CODE_CMD_STAGE_SM_ERR_MASK),
      32'(CSRNG_ERR_CODE_MAIN_SM_ERR_MASK),
      32'(CSRNG_ERR_CODE_CTR_DRBG_SM_ERR_MASK),
      32'(CSRNG_ERR_CODE_AES_CIPHER_SM_ERR_MASK),
      32'(CSRNG_ERR_CODE_CTR_ERR_MASK),
      32'(CSRNG_ERR_CODE_FIFO_WRITE_ERR_MASK),
      32'(CSRNG_ERR_CODE_FIFO_READ_ERR_MASK),
      32'(CSRNG_ERR_CODE_FIFO_STATE_ERR_MASK)
  };
  localparam logic [31:0] CzEdErrBits[8] = '{
      32'(EDN_ERR_CODE_SFIFO_RESCMD_ERR_MASK),
      32'(EDN_ERR_CODE_SFIFO_GENCMD_ERR_MASK),
      32'(EDN_ERR_CODE_EDN_ACK_SM_ERR_MASK),
      32'(EDN_ERR_CODE_EDN_MAIN_SM_ERR_MASK),
      32'(EDN_ERR_CODE_EDN_CNTR_ERR_MASK),
      32'(EDN_ERR_CODE_FIFO_WRITE_ERR_MASK),
      32'(EDN_ERR_CODE_FIFO_READ_ERR_MASK),
      32'(EDN_ERR_CODE_FIFO_STATE_ERR_MASK)
  };
  wire [19:0] cz_cs_ec = csrng_hw2reg_i.err_code;
  wire [15:0] cz_ed_ec = edn_hw2reg_i.err_code;
  logic [31:0] cz_err_set[2];  // 0 CSRNG, 1 EDN
  always_comb begin
    cz_err_set[0] = '0;
    cz_err_set[1] = '0;
    for (int k = 0; k < 10; k++) begin
      if (cz_dd(cz_cs_ec[2*k+:2])) cz_err_set[0] |= CzCsErrBits[k];
    end
    for (int k = 0; k < 8; k++) begin
      if (cz_dd(cz_ed_ec[2*k+:2])) cz_err_set[1] |= CzEdErrBits[k];
    end
  end
  localparam logic [31:0] CzCsErrMask = 32'(CSRNG_ERR_CODE_SFIFO_CMD_ERR_MASK |
      CSRNG_ERR_CODE_SFIFO_GENBITS_ERR_MASK | CSRNG_ERR_CODE_CMD_STAGE_SM_ERR_MASK |
      CSRNG_ERR_CODE_MAIN_SM_ERR_MASK | CSRNG_ERR_CODE_CTR_DRBG_SM_ERR_MASK |
      CSRNG_ERR_CODE_AES_CIPHER_SM_ERR_MASK | CSRNG_ERR_CODE_CTR_ERR_MASK |
      CSRNG_ERR_CODE_FIFO_WRITE_ERR_MASK | CSRNG_ERR_CODE_FIFO_READ_ERR_MASK |
      CSRNG_ERR_CODE_FIFO_STATE_ERR_MASK);
  localparam logic [31:0] CzEdErrMask = 32'(EDN_ERR_CODE_SFIFO_RESCMD_ERR_MASK |
      EDN_ERR_CODE_SFIFO_GENCMD_ERR_MASK | EDN_ERR_CODE_EDN_ACK_SM_ERR_MASK |
      EDN_ERR_CODE_EDN_MAIN_SM_ERR_MASK | EDN_ERR_CODE_EDN_CNTR_ERR_MASK |
      EDN_ERR_CODE_FIFO_WRITE_ERR_MASK | EDN_ERR_CODE_FIFO_READ_ERR_MASK |
      EDN_ERR_CODE_FIFO_STATE_ERR_MASK);
  // Source bits of the state-machine class of cp_fatal_consequence.
  function automatic logic cz_sm_bit(input int unsigned u, input logic [4:0] b);
    if (u == 0) return b inside {5'd20, 5'd21, 5'd22, 5'd25, 5'd26};
    return b inside {5'd20, 5'd21, 5'd22};
  endfunction

  // ---------------------------------------------------------------------
  // sep_drbg_err_inject_cg (1.48) and the error-code and REGWEN cells of
  // sep_crypto_reset_cg cp_reset_evidence (1.48, 1.49).
  // ---------------------------------------------------------------------
  logic [1:0] cz_es_arm = '0;
  logic [4:0] cz_es_idx[2] = '{default: '0};
  int unsigned cz_es_cnt[2] = '{default: 0};
  logic [1:0] cz_fc_arm = '0;
  logic [1:0] cz_fc_sm = '0;
  int unsigned cz_fc_cnt[2] = '{default: 0};
  logic [1:0] cz_sk_rd1 = '0;  // a read of ERR_CODE showed the tested bit
  logic [1:0] cz_sk_w1c = '0;  // then a write of 1 to the fatal state bit
  logic [1:0] cz_rc_nz = '0;  // the last ERR_CODE read was non-zero on the field bits
  logic [1:0] cz_rc_arm = '0;
  logic [1:0] cz_rw0 = '0;  // the last REGWEN read was 0
  logic [1:0] cz_rw_arm = '0;
  // EDN command FIFOs (0 RESEED_CMD, 1 GENERATE_CMD): words written since
  // the last EDN CTRL write or TRNG reset, and the clock of the last
  // error-code set request of the FIFO.
  logic [4:0] cz_ef_n[2] = '{default: '0};
  logic [1:0] cz_ef_err = '0;
  longint unsigned cz_ef_err_t[2] = '{default: 0};
  logic [1:0] cz_ef13 = '0;
  int unsigned cz_ef13_cnt[2] = '{default: 0};
  logic [1:0] cz_ef14 = '0;
  longint unsigned cz_ef14_t[2] = '{default: 0};
  longint unsigned cz_v32_t = 0;
  longint unsigned cz_aw_t = 0;

  always @(posedge clk_i) begin
    logic [1:0] tq;
    logic [4:0] tidx[2];
    logic [1:0] st;
    cz_clk <= cz_clk + 1;
    if (aw_hs) cz_aw_t <= cz_clk;
    if (cy_vec_rise[32]) cz_v32_t <= cz_clk;
    tq[0]   = cy_t(csrng_reg2hw_i.err_code_test.qe);
    tq[1]   = cy_t(edn_reg2hw_i.err_code_test.qe);
    tidx[0] = csrng_reg2hw_i.err_code_test.q;
    tidx[1] = edn_reg2hw_i.err_code_test.q;
    st[0]   = cy_st[9];
    st[1]   = cy_st[11];

    for (int u = 0; u < 2; u++) begin
      logic [31:0] ec_a;
      logic [31:0] st_a;
      logic [31:0] st_m;
      logic [31:0] rw_a;
      logic [31:0] m;
      ec_a = (u == 0) ? CSRNG_ERR_CODE_REG_ADDR : EDN_ERR_CODE_REG_ADDR;
      st_a = (u == 0) ? CSRNG_INTR_STATE_REG_ADDR : EDN_INTR_STATE_REG_ADDR;
      st_m = (u == 0) ? 32'(CSRNG_INTR_STATE_CS_FATAL_ERR_MASK) :
          32'(EDN_INTR_STATE_EDN_FATAL_ERR_MASK);
      rw_a = (u == 0) ? CSRNG_REGWEN_REG_ADDR : EDN_REGWEN_REG_ADDR;
      m = (u == 0) ? CzCsErrMask : CzEdErrMask;

      // x_err_source and cp_fatal_consequence: an ERR_CODE_TEST write of
      // bit b, then the set request of bit b; the FIFO class sets the fatal
      // state and the state-machine class raises vector bit 32.
      if (!cy_own_dfat || !cy_ip[5] || cz_trng) begin
        cz_es_arm[u] <= 1'b0;
        cz_fc_arm[u] <= 1'b0;
      end else if (tq[u] && !$isunknown(tidx[u])) begin
        if (cz_err_set[u][tidx[u]]) cz_derr(0, {1'(u), tidx[u]});
        cz_es_arm[u] <= !cz_err_set[u][tidx[u]];
        cz_es_idx[u] <= tidx[u];
        cz_es_cnt[u] <= 0;
        cz_fc_arm[u] <= (tidx[u] <= 5'd1) ? !st[u] : (cz_sm_bit(u, tidx[u]) && !cy_vec[32]);
        cz_fc_sm[u]  <= (tidx[u] > 5'd1);
        cz_fc_cnt[u] <= 0;
      end else begin
        if (cz_es_arm[u]) begin
          if (cz_err_set[u][cz_es_idx[u]]) begin
            cz_derr(0, {1'(u), cz_es_idx[u]});
            cz_es_arm[u] <= 1'b0;
          end else if (cz_es_cnt[u] >= CySettle) begin
            cz_es_arm[u] <= 1'b0;
          end
          cz_es_cnt[u] <= cz_es_cnt[u] + 1;
        end
        if (cz_fc_arm[u]) begin
          if (!cz_fc_sm[u] && st[u]) begin
            cz_derr(1, {4'd0, 1'(u), 1'b0});
            cz_fc_arm[u] <= 1'b0;
          end else if (cz_fc_sm[u] && cy_vec_rise[32]) begin
            cz_derr(1, {4'd0, 1'(u), 1'b1});
            cz_fc_arm[u] <= 1'b0;
          end else if (cz_fc_cnt[u] >= CyAlertBound) begin
            cz_fc_arm[u] <= 1'b0;
          end
          cz_fc_cnt[u] <= cz_fc_cnt[u] + 1;
        end
      end

      // cp_sticky survives: a read of ERR_CODE with the tested bit set, a
      // write of 1 to the fatal state bit, and a later read with the bit
      // still set. The EDN bit 0 cell is not a bin.
      if (!cy_own_dfat || !cy_ip[5] || cz_trng || (tq[u] && !$isunknown(tidx[u]))) begin
        cz_sk_rd1[u] <= 1'b0;
        cz_sk_w1c[u] <= 1'b0;
      end else begin
        if (wr_ev && (aw_addr_q == st_a) && ((wr_data & st_m) != 32'h0) && cz_sk_rd1[u]) begin
          cz_sk_w1c[u] <= 1'b1;
        end
        if (rd_ev && (ar_addr_q == ec_a) && cy_rd_known) begin
          if (rd_data[cz_es_idx[u]] && !((u == 1) && (cz_es_idx[u] == 5'd0))) begin
            if (cz_sk_w1c[u]) begin
              cz_derr(2, {4'd0, 1'(u), 1'b0});
              cz_sk_w1c[u] <= 1'b0;
            end
            cz_sk_rd1[u] <= 1'b1;
          end else begin
            cz_sk_rd1[u] <= 1'b0;
            cz_sk_w1c[u] <= 1'b0;
          end
        end
      end

      // cp_sticky clears at the TRNG reset and cp_reset_evidence: the last
      // read before the reset differs from the reset value, the first read
      // after it returns the reset value (ERR_CODE 0 on the field bits,
      // REGWEN 1).
      if (rd_ev && (ar_addr_q == ec_a) && cy_rd_known && !cz_trng) begin
        if (cz_rc_arm[u]) begin
          if ((rd_data & m) == 32'h0) begin
            if (cy_own_dfat) cz_derr(2, {4'd0, 1'(u), 1'b1});
            if (cy_own_dfat) cz_crst(5, 4'(u));
          end
          cz_rc_arm[u] <= 1'b0;
        end
        cz_rc_nz[u] <= ((rd_data & m) != 32'h0);
      end
      if (rd_ev && (ar_addr_q == rw_a) && cy_rd_known && !cz_trng) begin
        if (cz_rw_arm[u]) begin
          if (rd_data[0] && cy_own_drw) cz_crst(5, 4'(2 + u));
          cz_rw_arm[u] <= 1'b0;
        end
        cz_rw0[u] <= !rd_data[0];
      end
      if (cz_trng_rise) begin
        cz_rc_arm[u] <= cz_rc_nz[u];
        cz_rw_arm[u] <= cz_rw0[u];
      end
    end

    // cp_edn_cmd_fifo and cp_auto_fifo_words: words written to RESEED_CMD
    // and GENERATE_CMD since the last EDN CTRL write or TRNG reset. One and
    // 13 words: no error set request of the FIFO. 13 words: no error and no
    // fatal state for CySettle clocks, or up to the AW handshake of the next
    // word to the FIFO if that comes first. 14th word: the error set request of
    // the FIFO, the fatal state and a vector bit 32 rise, each at or after
    // the AW handshake of that word.
    for (int f = 0; f < 2; f++) begin
      logic [31:0] fa;
      logic [31:0] fm;
      fa = (f == 0) ? EDN_RESEED_CMD_REG_ADDR : EDN_GENERATE_CMD_REG_ADDR;
      fm = (f == 0) ? 32'(EDN_ERR_CODE_SFIFO_RESCMD_ERR_MASK) : 32'(EDN_ERR_CODE_SFIFO_GENCMD_ERR_MASK);
      if ((cz_err_set[1] & fm) != 32'h0) begin
        cz_ef_err[f]   <= 1'b1;
        cz_ef_err_t[f] <= cz_clk;
      end
      if (cz_trng || !cy_ip[5] || (wr_ev && (aw_addr_q == EDN_CTRL_REG_ADDR))) begin
        cz_ef_n[f]   <= '0;
        cz_ef_err[f] <= 1'b0;
        cz_ef13[f]   <= 1'b0;
        cz_ef14[f]   <= 1'b0;
      end else begin
        if (wr_ev && (aw_addr_q == fa)) begin
          logic [4:0] n;
          n = (cz_ef_n[f] == 5'd31) ? 5'd31 : cz_ef_n[f] + 5'd1;
          cz_ef_n[f] <= n;
          if (cy_own_dfat && !cz_ef_err[f] && ((n == 5'd1) || (n == 5'd13))) begin
            cz_edn(3, {1'(f), (n == 5'd13)});
          end
          if (cy_own_dfat && !cz_ef_err[f] && (n == 5'd13)) begin
            cz_ef13[f]     <= 1'b1;
            cz_ef13_cnt[f] <= 0;
          end
          if (cy_own_dfat && (n == 5'd14)) begin
            cz_ef14[f]   <= 1'b1;
            cz_ef14_t[f] <= cz_aw_t;
          end
        end
        if (cz_ef13[f]) begin
          if (cz_ef_err[f] || cy_st[11] || !cy_own_dfat) begin
            cz_ef13[f] <= 1'b0;
          end else if ((cz_ef13_cnt[f] >= CySettle) || (aw_hs && (lsu_aw_addr_i == fa))) begin
            cz_derr(3, {4'd0, 1'(f), 1'b0});
            cz_ef13[f] <= 1'b0;
          end
          cz_ef13_cnt[f] <= cz_ef13_cnt[f] + 1;
        end
        if (cz_ef14[f]) begin
          if (cz_ef_err[f] && (cz_ef_err_t[f] >= cz_ef14_t[f]) && cy_st[11] &&
              (cz_v32_t >= cz_ef14_t[f]) && (cz_v32_t != 0)) begin
            if (cy_own_dfat) cz_derr(3, {4'd0, 1'(f), 1'b1});
            cz_ef14[f] <= 1'b0;
          end else if ((cz_clk - cz_ef14_t[f]) > longint'(CyAlertBound)) begin
            cz_ef14[f] <= 1'b0;
          end
        end
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_csrng_cmd_cg and sep_edn_mode_cg (1.50).
  // ---------------------------------------------------------------------
  logic cz_sw_ins_ok = 1'b0;  // a software instantiate completed since the TRNG reset
  logic [1:0] cz_io_arm = '0;  // [0] first, [1] repeated
  int unsigned cz_io_cnt = 0;
  logic cz_hw_arm = 1'b0;
  int unsigned cz_hw_cnt = 0;
  logic cz_app0_ack_q = 1'b0;
  logic cz_app0_new_q = 1'b0;
  logic cz_cs_rdy = 1'b0;
  logic cz_aw_csrdy = 1'b0;
  logic [1:0] cz_csh = '0;  // 1 waiting for CMD_ACK, 2 waiting for CMD_RDY
  int unsigned cz_csh_cnt = 0;
  logic cz_ed_rrdy = 1'b0;
  logic cz_aw_edrrdy = 1'b0;
  logic [1:0] cz_edh = '0;  // [0] waiting for CMD_ACK, [1] waiting for edn_cmd_req_done
  int unsigned cz_edh_cnt = 0;
  logic [3:0] cz_ed_en_q = '0;
  logic cz_ed_boot = 1'b0;
  logic cz_ed_auto = 1'b0;
  wire cz_cs_done_set = cz_dd(csrng_hw2reg_i.intr_state.cs_cmd_req_done);
  wire cz_ed_done_set = cz_dd(edn_hw2reg_i.intr_state.edn_cmd_req_done);
  wire cz_cs_ack_set = cz_dd(csrng_hw2reg_i.sw_cmd_sts.cmd_ack);
  wire cz_ed_ack_set = cz_dd(edn_hw2reg_i.sw_cmd_sts.cmd_ack);

  always @(posedge clk_i) begin
    logic app0_new;
    logic [3:0] en;
    logic [3:0] bm;
    logic [3:0] am;
    app0_new = cy_t(csrng_app0_req_i.csrng_req_valid) && !cz_app0_new_q;
    cz_app0_new_q <= cy_t(csrng_app0_req_i.csrng_req_valid);
    cz_app0_ack_q <= cy_t(csrng_app0_ack_i);
    if (cy_t(csrng_hw2reg_i.sw_cmd_sts.cmd_rdy.de)) begin
      cz_cs_rdy <= cy_t(csrng_hw2reg_i.sw_cmd_sts.cmd_rdy.d);
    end
    if (cy_t(edn_hw2reg_i.sw_cmd_sts.cmd_reg_rdy.de)) begin
      cz_ed_rrdy <= cy_t(edn_hw2reg_i.sw_cmd_sts.cmd_reg_rdy.d);
    end
    if (aw_hs) begin
      cz_aw_csrdy  <= cz_cs_rdy;
      cz_aw_edrrdy <= cz_ed_rrdy;
    end

    // x_inst_outcome. Software port: a CMD_REQ write of the instantiate
    // word, taken at the CSRNG register write strobe; the first since the
    // TRNG reset ends with the cs_cmd_req_done set request, a repeated one
    // with the invalid-sequence alert set request. The alert can set before
    // the bus write response, so the arm is not the response. Hardware port
    // 0: an application-0 request of the instantiate word ends with its
    // acknowledge.
    if (cz_trng || !cy_ip[5]) begin
      cz_sw_ins_ok <= 1'b0;
      cz_io_arm    <= '0;
      cz_hw_arm    <= 1'b0;
    end else begin
      if (cz_io_arm[0] && cz_cs_done_set) begin
        cz_sw_ins_ok <= 1'b1;
        if (cy_own_dcmd) cz_ccmd(0, 3'd0);
        cz_io_arm[0] <= 1'b0;
      end else if (cz_io_arm[1] && cz_rs_set) begin
        if (cy_own_dcmd) cz_ccmd(0, 3'd1);
        cz_io_arm[1] <= 1'b0;
      end else if ((cz_io_arm != 2'b00) && (cz_io_cnt >= CzCmdBound)) begin
        cz_io_arm <= '0;
      end
      cz_io_cnt <= cz_io_cnt + 1;
      if (cy_t(csrng_reg2hw_i.cmd_req.qe)) begin
        cz_io_cnt <= 0;
        if (csrng_reg2hw_i.cmd_req.q == CzCsInstantiate) cz_io_arm <= cz_sw_ins_ok ? 2'b10 : 2'b01;
        else cz_io_arm <= '0;
      end
      if (cz_hw_arm && cy_t(csrng_app0_ack_i) && !cz_app0_ack_q) begin
        if (cy_own_dcmd) cz_ccmd(0, 3'd2);
        cz_hw_arm <= 1'b0;
      end else if (cz_hw_arm && (cz_hw_cnt >= CzCmdBound)) begin
        cz_hw_arm <= 1'b0;
      end
      cz_hw_cnt <= cz_hw_cnt + 1;
      if (app0_new && (csrng_app0_req_i.csrng_req_bus == CzCsInstantiate)) begin
        cz_hw_arm <= 1'b1;
        cz_hw_cnt <= 0;
      end
    end

    // cp_sw_handshake (CSRNG software port): CMD_RDY 1 at the AW handshake
    // of a CMD_REQ write, the CMD_ACK set request after it, then CMD_RDY 1.
    if (!cy_own_dcmd || cz_trng || !cy_ip[5]) begin
      cz_csh <= '0;
    end else begin
      if (wr_ev && (aw_addr_q == CSRNG_CMD_REQ_REG_ADDR)) begin
        if (cz_aw_csrdy) cz_ccmd(1, 3'd0);
        cz_csh     <= 2'd1;
        cz_csh_cnt <= 0;
      end else if (cz_csh == 2'd1) begin
        if (cz_cs_ack_set) begin
          cz_ccmd(1, 3'd1);
          cz_csh <= 2'd2;
        end else if (cz_csh_cnt >= CzCmdBound) begin
          cz_csh <= '0;
        end
        cz_csh_cnt <= cz_csh_cnt + 1;
      end else if (cz_csh == 2'd2) begin
        if (cz_cs_rdy) begin
          cz_ccmd(1, 3'd2);
          cz_csh <= '0;
        end else if (cz_csh_cnt >= CzCmdBound) begin
          cz_csh <= '0;
        end
        cz_csh_cnt <= cz_csh_cnt + 1;
      end
    end

    // cp_sw_port_hs (EDN software port): CMD_REG_RDY 1 at the AW handshake
    // of a SW_CMD_REQ write, then the CMD_ACK and edn_cmd_req_done set
    // requests.
    if (!cy_own_dcmd || cz_trng || !cy_ip[5]) begin
      cz_edh <= '0;
    end else begin
      if (wr_ev && (aw_addr_q == EDN_SW_CMD_REQ_REG_ADDR)) begin
        if (cz_aw_edrrdy) cz_edn(2, 2'd0);
        cz_edh     <= 2'b11;
        cz_edh_cnt <= 0;
      end else if (cz_edh != 2'b00) begin
        if (cz_edh[0] && cz_ed_ack_set) begin
          cz_edn(2, 2'd1);
          cz_edh[0] <= 1'b0;
        end
        if (cz_edh[1] && cz_ed_done_set) begin
          cz_edn(2, 2'd2);
          cz_edh[1] <= 1'b0;
        end
        if (cz_edh_cnt >= CzCmdBound) cz_edh <= '0;
        cz_edh_cnt <= cz_edh_cnt + 1;
      end
    end

    // x_mode_fields: the mode fields at the landed write that sets
    // EDN_ENABLE true.
    en = edn_reg2hw_i.ctrl.edn_enable.q;
    bm = edn_reg2hw_i.ctrl.boot_req_mode.q;
    am = edn_reg2hw_i.ctrl.auto_req_mode.q;
    cz_ed_en_q <= en;
    if (cy_own_dcmd && cy_ip[5] && !cz_trng && (en == CzMubiTrue) && (cz_ed_en_q != CzMubiTrue) &&
        (bm inside {CzMubiTrue, CzMubiFalse}) && (am inside {CzMubiTrue, CzMubiFalse})) begin
      cz_edn(0, {(bm == CzMubiTrue), (am == CzMubiTrue)});
    end

    // cp_reported_mode: the stored HW_CMD_STS mode pair at each landed
    // hardware write of BOOT_MODE or AUTO_MODE.
    if (cz_trng || !cy_ip[5]) begin
      cz_ed_boot <= 1'b0;
      cz_ed_auto <= 1'b0;
    end else begin
      logic bde;
      logic ade;
      logic b;
      logic a;
      bde = cy_t(edn_hw2reg_i.hw_cmd_sts.boot_mode.de);
      ade = cy_t(edn_hw2reg_i.hw_cmd_sts.auto_mode.de);
      b = bde ? cy_t(edn_hw2reg_i.hw_cmd_sts.boot_mode.d) : cz_ed_boot;
      a = ade ? cy_t(edn_hw2reg_i.hw_cmd_sts.auto_mode.d) : cz_ed_auto;
      cz_ed_boot <= b;
      cz_ed_auto <= a;
      if (cy_own_dcmd && (bde || ade) && b) cz_edn(1, {1'b0, a});
      else if (cy_own_dcmd && (bde || ade) && !b && a) cz_edn(1, 2'd2);
      if (cy_own_dcmd && !b && a && cy_t(edn_hw2reg_i.hw_cmd_sts.cmd_type.de)) begin
        if (edn_hw2reg_i.hw_cmd_sts.cmd_type.d == 4'd3) cz_edn(8, 2'd0);
        else if (edn_hw2reg_i.hw_cmd_sts.cmd_type.d == 4'd2) cz_edn(8, 2'd1);
      end
    end
  end

  // ---------------------------------------------------------------------
  // CSRNG and EDN command cells of the DRBG command-sequence owner: the
  // RECOV_ALERT_STS set requests, CMD_STS at the software acknowledge, the
  // reseed limit, the GENBITS gate and the reset read of the EDN boot words.
  // ---------------------------------------------------------------------
  localparam logic [31:0] CzEdBootIns = 32'h0000_0901;  // edn.hjson BOOT_INS_CMD resval
  localparam logic [31:0] CzEdBootGen = 32'h00FF_F003;  // edn.hjson BOOT_GEN_CMD resval
  logic [3:0] cz_cs_acmd = '0;  // acmd of the last software CMD_REQ header word
  logic [3:0] cz_cs_rem = '0;   // additional-data words still due for that header
  logic cz_rl_ref = 1'b0;       // a Generate refused at the limit since the TRNG reset
  logic cz_rl_rsd = 1'b0;       // a Reseed acknowledged after that refusal
  logic cz_ed_wr = 1'b0;        // an EDN register write since the TRNG reset
  logic cz_ed_ack_q = 1'b0;
  wire cz_gb_vld = cy_t(csrng_hw2reg_i.genbits_vld.genbits_vld.d);
  always @(posedge clk_i) begin
    logic [6:0] ra;
    logic [3:0] fa;
    logic cs_ack;
    logic ed_ack_rise;
    ra = {cz_dd(csrng_hw2reg_i.recov_alert_sts.cmd_stage_reseed_cnt_alert),
          cz_dd(csrng_hw2reg_i.recov_alert_sts.cmd_stage_invalid_acmd_alert),
          cz_dd(csrng_hw2reg_i.recov_alert_sts.acmd_flag0_field_alert),
          cz_dd(csrng_hw2reg_i.recov_alert_sts.fips_force_enable_field_alert),
          cz_dd(csrng_hw2reg_i.recov_alert_sts.read_int_state_field_alert),
          cz_dd(csrng_hw2reg_i.recov_alert_sts.sw_app_enable_field_alert),
          cz_dd(csrng_hw2reg_i.recov_alert_sts.enable_field_alert)};
    fa = {cz_dd(edn_hw2reg_i.recov_alert_sts.cmd_fifo_rst_field_alert),
          cz_dd(edn_hw2reg_i.recov_alert_sts.auto_req_mode_field_alert),
          cz_dd(edn_hw2reg_i.recov_alert_sts.boot_req_mode_field_alert),
          cz_dd(edn_hw2reg_i.recov_alert_sts.edn_enable_field_alert)};
    // The CSRNG software acknowledge writes CMD_STS (its de is the ack
    // pulse); the EDN CMD_ACK is a level, so its rise is the acknowledge.
    cs_ack = cy_t(csrng_hw2reg_i.sw_cmd_sts.cmd_sts.de);
    ed_ack_rise = cz_ed_ack_set && !cz_ed_ack_q;
    cz_ed_ack_q <= cz_ed_ack_set;
    if (cy_t(csrng_reg2hw_i.cmd_req.qe)) begin
      if (cz_cs_rem == 4'd0) begin
        cz_cs_acmd <= csrng_reg2hw_i.cmd_req.q[3:0];
        cz_cs_rem  <= csrng_reg2hw_i.cmd_req.q[7:4];
      end else begin
        cz_cs_rem <= cz_cs_rem - 4'd1;
      end
    end
    if (wr_ev && in_blk(aw_addr_q, EDN_REG_MAP_BASE_ADDR, EDN_REG_MAP_SIZE)) cz_ed_wr <= 1'b1;
    if (cz_trng || !cy_ip[5]) begin
      cz_cs_rem <= '0;
      cz_rl_ref <= 1'b0;
      cz_rl_rsd <= 1'b0;
      cz_ed_wr  <= 1'b0;
    end else if (cy_own_dcmd) begin
      for (int b = 0; b < 7; b++) if (ra[b]) cz_ccmd(2, 3'(b));
      for (int b = 0; b < 4; b++) if (fa[b]) cz_edn(5, 2'(b));
      if (cz_dd(edn_hw2reg_i.recov_alert_sts.csrng_ack_err)) cz_edn(7, 2'd0);
      if (cs_ack) begin
        case (csrng_hw2reg_i.sw_cmd_sts.cmd_sts.d)
          3'd1: cz_ccmd(3, 3'd1);
          3'd4: cz_ccmd(3, 3'd2);
          default: ;
        endcase
        if (cz_cs_acmd == 4'h3) begin
          if (csrng_hw2reg_i.sw_cmd_sts.cmd_sts.d == 3'd4) begin
            cz_ccmd(4, 3'd0);
            cz_rl_ref <= 1'b1;
            cz_rl_rsd <= 1'b0;
          end else if (cz_rl_rsd) begin
            cz_ccmd(4, 3'd1);
            cz_rl_rsd <= 1'b0;
          end
        end
        if ((cz_cs_acmd == 4'h2) && cz_rl_ref && (csrng_hw2reg_i.sw_cmd_sts.cmd_sts.d == 3'd0)) begin
          cz_rl_rsd <= 1'b1;
        end
      end
      if (ed_ack_rise) begin
        if (edn_hw2reg_i.sw_cmd_sts.cmd_sts.d == 3'd0) cz_edn(6, 2'd0);
        if (edn_hw2reg_i.sw_cmd_sts.cmd_sts.d == 3'd1) cz_edn(6, 2'd1);
      end
      if (rd_ev && cy_rd_known && (ar_addr_q == CSRNG_GENBITS_REG_ADDR) &&
          (csrng_reg2hw_i.ctrl.sw_app_enable.q != CzMubiTrue) &&
          cz_gb_vld && (rd_data == 32'h0)) begin
        cz_ccmd(5, 3'd0);
      end
      if (rd_ev && cy_rd_known && !cz_ed_wr) begin
        if ((ar_addr_q == EDN_BOOT_INS_CMD_REG_ADDR) && (rd_data == CzEdBootIns)) cz_edn(4, 2'd0);
        if ((ar_addr_q == EDN_BOOT_GEN_CMD_REG_ADDR) && (rd_data == CzEdBootGen)) cz_edn(4, 2'd1);
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_crypto_reset_cg (1.40, 1.51, 1.52): the TRNG reset window points
  // and the ESRC and select-lock cells of cp_reset_evidence.
  // ---------------------------------------------------------------------
  // ESRC read-write fields outside the FIPS_LOCK list and outside CTRL
  // (hw/ip/entropy_source/regs/gen/adoc/entropy_source.adoc): the register,
  // the field bits and the reset value of each.
  localparam int unsigned CzEsRegs = 5;
  function automatic int cz_es_reg(input logic [31:0] a);
    case (a)
      ENTROPY_SOURCE_INTR_ENABLE_REG_ADDR: return 0;
      ENTROPY_SOURCE_HEALTH_TEST_CTRL_REG_ADDR: return 1;
      ENTROPY_SOURCE_HEALTH_TEST_WINDOW_SIZE_REG_ADDR: return 2;
      ENTROPY_SOURCE_HT_WATERMARK_NUM_REG_ADDR: return 3;
      ENTROPY_SOURCE_NOISE_OBS_CTRL_REG_ADDR: return 4;
      default: return -1;
    endcase
  endfunction
  function automatic logic [31:0] cz_es_mask(input int r);
    case (r)
      0:
      return 32'(ENTROPY_SOURCE_INTR_ENABLE_HEALTH_TEST_FAILED_MASK |
          ENTROPY_SOURCE_INTR_ENABLE_FIFO_ERROR_MASK | ENTROPY_SOURCE_INTR_ENABLE_FIFO_OVERFLOW_MASK |
          ENTROPY_SOURCE_INTR_ENABLE_FIFO_UNDERFLOW_MASK |
          ENTROPY_SOURCE_INTR_ENABLE_PERSISTENT_FAILURE_MASK |
          ENTROPY_SOURCE_INTR_ENABLE_AUTOTUNE_FAIL_MASK |
          ENTROPY_SOURCE_INTR_ENABLE_BIW_OBS_OVERFLOW_MASK |
          ENTROPY_SOURCE_INTR_ENABLE_NOISE_OBS_OVERFLOW_MASK);
      1: return 32'(ENTROPY_SOURCE_HEALTH_TEST_CTRL_ENABLE_MASK);
      2: return 32'(ENTROPY_SOURCE_HEALTH_TEST_WINDOW_SIZE_SIZE_MASK);
      3: return 32'(ENTROPY_SOURCE_HT_WATERMARK_NUM_WATERMARK_NUM_MASK);
      default: return 32'(ENTROPY_SOURCE_NOISE_OBS_CTRL_LANE_SEL_MASK);
    endcase
  endfunction
  function automatic logic [31:0] cz_es_rst(input int r);
    case (r)
      0: return 32'(ENTROPY_SOURCE_INTR_ENABLE_REG_DEFAULT);
      1: return 32'(ENTROPY_SOURCE_HEALTH_TEST_CTRL_REG_DEFAULT);
      2: return 32'(ENTROPY_SOURCE_HEALTH_TEST_WINDOW_SIZE_REG_DEFAULT);
      3: return 32'(ENTROPY_SOURCE_HT_WATERMARK_NUM_REG_DEFAULT);
      default: return 32'(ENTROPY_SOURCE_NOISE_OBS_CTRL_REG_DEFAULT);
    endcase
  endfunction
  logic [CzEsRegs-1:0] cz_er_diff = '0;  // the last read differs from the reset value
  logic cz_er_arm = 1'b0;
  logic [CzEsRegs-1:0] cz_er_seen = '0;
  logic [CzEsRegs-1:0] cz_er_ok = '0;
  logic cz_lk_one = 1'b0;  // the last EXT_TRNG_SRC_SEL_LOCK read was 1
  logic cz_lk_arm = 1'b0;
  logic cz_pc_ar = 1'b0;  // the TRNG window was high at the AR handshake
  logic [5:0] cz_pool_ar = '0;  // pool level at the AR handshake
  // Pool level on the clock before the window rise: the clear forces
  // fifo_level to 0 from the rise clock on.
  logic [5:0] cz_pool_pre = '0;
  logic cz_ps_nz = 1'b0;
  logic [1:0] cz_xp_res = '0;  // first handshake after the window fall pending
  logic [3:0] cz_cc_pend = '0;
  logic [3:0] cz_cc_ack = '0;
  logic [3:0] cz_cc_after = '0;
  localparam logic [31:0] CzPoolLvlMask = 32'(SEP_ENTROPY_POOL_STATUS_FIFO_LEVEL_MASK);
  localparam logic [31:0] CzSelMask = 32'(SEP_CPU_CTRL_EXT_TRNG_SRC_SEL_SEL_MASK);
  localparam logic [31:0] CzLockMask = 32'(SEP_CPU_CTRL_EXT_TRNG_SRC_SEL_LOCK_LOCK_MASK);
  // Handshake after the source mux of each stream (0 Key Manager, 1 crypto,
  // 2 pool). With the external select it is the handshake of the external port.
  logic [2:0] cz_mhs;
  always_comb begin
    for (int i = 0; i < 3; i++) begin
      cz_mhs[i] = (mux_req_i[i].tvalid === 1'b1) && (mux_rsp_i[i].tready === 1'b1);
    end
  end

  always @(posedge clk_i) begin
    if (ar_hs) begin
      cz_pc_ar   <= cz_trng;
      cz_pool_ar <= pool_level_i;
    end
    cz_pool_pre <= pool_level_i;

    // cp_clear_ext_sel and cp_pool_scrub at the window rise; the window fall
    // ends cp_pool_scrub and cp_client_in_clear. The level at the window
    // start is the level on the clock before the rise.
    if (cz_trng_rise) begin
      if (cy_own_xrst && cz_sel[1]) cz_crst(0, 4'd0);
      if (cy_own_xrst && cz_sel[2]) cz_crst(0, 4'd1);
      cz_ps_nz <= (cz_pool_pre != 6'd0) && !$isunknown(cz_pool_pre);
    end
    if (cz_trng_fall) begin
      if (cy_own_xrst && cz_ps_nz && (pool_level_i == 6'd0)) cz_crst(3, 4'd0);
      cz_ps_nz  <= 1'b0;
      cz_xp_res <= 2'b11;
    end

    // cp_xfer_phase: an external handshake of stream 1 or 2 with the
    // external select; in the window (illegal), the first after the window
    // fall (resume, also on the fall clock), or another with the window low
    // (before_clear).
    for (int s = 0; s < 2; s++) begin
      if (cz_mhs[s+1] && cz_sel[s+1] && cy_own_xrst) begin
        if (cz_trng) cz_crst(1, {1'b0, 1'(s), 2'b01});
        else if (cz_xp_res[s] || cz_trng_fall) cz_crst(1, {1'b0, 1'(s), 2'b10});
        else cz_crst(1, {1'b0, 1'(s), 2'b00});
      end
      if (cz_mhs[s+1] && cz_sel[s+1] && !cz_trng) cz_xp_res[s] <= 1'b0;
    end

    // cp_pool_in_clear: a pool STATUS read issued and answered in the
    // window, with fifo_level 0.
    if (cy_own_xrst && rd_ev && (ar_addr_q == ENTROPY_POOL_STATUS_REG_ADDR) && cz_pc_ar && cz_trng &&
        cy_rd_known && ((rd_data & CzPoolLvlMask) == 32'h0)) begin
      cz_crst(2, 4'd0);
    end

    // cp_client_in_clear: a client request high at the window rise and
    // held, with no acknowledge in the window; the acknowledge after the
    // fall. An acknowledge in the window is illegal.
    for (int c = 0; c < 4; c++) begin
      logic req;
      req = (edn_req_i[c] === 1'b1);
      if (cz_trng_rise) begin
        cz_cc_pend[c]  <= req;
        cz_cc_ack[c]   <= 1'b0;
        cz_cc_after[c] <= 1'b0;
      end else if (cz_trng) begin
        if (cy_ack[c]) begin
          if (cy_own_xrst) cz_crst(4, {1'b1, 2'(c), 1'b0});
          cz_cc_ack[c] <= 1'b1;
        end
        if (!req) cz_cc_pend[c] <= 1'b0;
      end else if (cz_trng_fall) begin
        if (cz_cc_pend[c] && !cz_cc_ack[c] && cy_own_xrst) cz_crst(4, {1'b0, 2'(c), 1'b0});
        cz_cc_after[c] <= cz_cc_pend[c] && !cz_cc_ack[c];
        cz_cc_pend[c]  <= 1'b0;
      end else if (cz_cc_after[c] && cy_ack[c]) begin
        if (cy_own_xrst) cz_crst(4, {1'b0, 2'(c), 1'b1});
        cz_cc_after[c] <= 1'b0;
      end
    end

    // cp_reset_evidence esrc_regs: every listed register read a value that
    // differs from its reset value on its field bits before the TRNG reset,
    // and its first read after the reset returns the reset value.
    if (rd_ev && cy_rd_known && !cz_trng && (cz_es_reg(ar_addr_q) >= 0)) begin
      int r;
      logic [31:0] m;
      r = cz_es_reg(ar_addr_q);
      m = cz_es_mask(r);
      if (cz_er_arm && !cz_er_seen[r]) begin
        logic [CzEsRegs-1:0] seen;
        logic [CzEsRegs-1:0] ok;
        seen = cz_er_seen;
        ok = cz_er_ok;
        seen[r] = 1'b1;
        ok[r] = ((rd_data & m) == (cz_es_rst(r) & m));
        cz_er_seen <= seen;
        cz_er_ok   <= ok;
        if (&seen) begin
          if ((&ok) && cy_own_eswalk) cz_crst(5, 4'd4);
          cz_er_arm <= 1'b0;
        end
      end
      cz_er_diff[r] <= ((rd_data & m) != (cz_es_rst(r) & m));
    end
    if (cz_trng_rise) begin
      cz_er_arm  <= &cz_er_diff;
      cz_er_seen <= '0;
      cz_er_ok   <= '0;
      cz_er_diff <= '0;
    end

    // cp_reset_evidence cpu_lock_survives: the lock read 1 before the TRNG
    // reset and the first read after it returns 1.
    if (rd_ev && cy_rd_known && !cz_trng && (ar_addr_q == SEP_CPU_CTRL_EXT_TRNG_SRC_SEL_LOCK_REG_ADDR)) begin
      if (cz_lk_arm) begin
        if (((rd_data & CzLockMask) != 32'h0) && cy_own_xhs) cz_crst(5, 4'd5);
        cz_lk_arm <= 1'b0;
      end
      cz_lk_one <= ((rd_data & CzLockMask) != 32'h0);
    end
    if (cz_trng_rise) cz_lk_arm <= cz_lk_one;
  end

  // ---------------------------------------------------------------------
  // sep_entropy_delivery_cg (1.51, 1.52, 1.53).
  // ---------------------------------------------------------------------
  wire cz_dlv_own = cy_own_xhs || cy_own_xrst || cy_own_mix;
  // cp_lock_order state since the last global reset.
  logic cz_lo_sel = 1'b0;  // a select write landed
  logic cz_lo_lock = 1'b0;  // a lock write of 1
  logic cz_lo_after = 1'b0;  // that lock write came after a landed select write
  logic cz_lo_one = 1'b0;  // a lock read returned 1
  logic cz_lo_w0 = 1'b0;  // then a lock write of 0
  logic cz_lo_rst = 1'b0;  // global reset after a lock read of 1
  logic cz_lo_rst_l0 = 1'b0;
  logic cz_lo_rst_s7 = 1'b0;
  logic cz_in_reset_q = 1'b0;
  // External beats, stalls, holds and rings of external words per stream.
  logic [1:0] cz_pp_q = '0;  // partial beat pending on the last clock, [0] crypto, [1] pool
  logic [1:0] cz_st_arm = '0;
  logic [1:0] cz_ho_on = '0;
  logic [1:0] cz_ho_bad = '0;
  logic [1:0] cz_ho_wait = '0;
  logic [31:0] cz_ho_w[2] = '{default: '0};
  logic [2:0] cz_sel_q = '0;
  logic [31:0] cz_ring[2][16] = '{default: '{default: '0}};
  logic [15:0] cz_ring_v[2] = '{default: '0};
  logic [3:0] cz_ring_wp[2] = '{default: '0};
  logic cz_irq_q = 1'b0;
  logic [1:0] cz_irq_arm = '0;  // [0] rise, [1] fall waiting for vector bit 16
  int unsigned cz_irq_cnt = 0;
  logic cz_km_rdy_bad = 1'b0;  // external and post-mux ready differed since the select
  logic [5:0] cz_as_done = '0;
  logic cz_pool_ack_q = 1'b0;

  function automatic logic cz_in_ring(input int s, input logic [31:0] w);
    for (int k = 0; k < 16; k++) begin
      if (cz_ring_v[s][k] && (cz_ring[s][k] == w)) return 1'b1;
    end
    return 1'b0;
  endfunction

  always @(posedge clk_i) begin
    cz_in_reset_q <= in_reset;
    cz_sel_q      <= cz_sel;
    cz_irq_q      <= (ext_trng_irq_i === 1'b1);
    cz_pool_ack_q <= (pool_edn_ack_i === 1'b1);

    // x_sel_stream: one cell per stream at a landed select write (the
    // select equals the written field on the clock after the response).
    // The Key Manager external cell belongs to the sink-mix owner.
    if (cz_w1 && (cz_w1_a == SEP_CPU_CTRL_EXT_TRNG_SRC_SEL_REG_ADDR) &&
        (cz_sel == 3'(cz_w1_d & CzSelMask)) && !in_reset) begin
      cz_lo_sel <= 1'b1;
      for (int i = 0; i < 3; i++) begin
        if (cy_own_mix || ((cy_own_xhs || cy_own_xrst) && !((i == 0) && cz_sel[0]))) begin
          cz_dlv(0, {2'(i), cz_sel[i]});
        end
      end
    end

    // cp_lock_order (1.51).
    if (in_reset && !cz_in_reset_q) begin
      if (cy_own_xhs && !cz_lo_lock && cz_lo_sel) cz_dlv(1, 3'd2);
      cz_lo_rst    <= cz_lo_one;
      cz_lo_rst_l0 <= 1'b0;
      cz_lo_rst_s7 <= 1'b0;
      cz_lo_sel    <= 1'b0;
      cz_lo_lock   <= 1'b0;
      cz_lo_after  <= 1'b0;
      cz_lo_one    <= 1'b0;
      cz_lo_w0     <= 1'b0;
    end else if (!in_reset) begin
      if (cz_ended(FcovOwnSepTrngExtStreamHandshakeRandTest) && !cz_lo_lock && cz_lo_sel) begin
        cz_dlv(1, 3'd2);
      end
      if (wr_ev && (aw_addr_q == SEP_CPU_CTRL_EXT_TRNG_SRC_SEL_LOCK_REG_ADDR)) begin
        if ((wr_data & CzLockMask) != 32'h0) begin
          if (!cz_lo_lock) cz_lo_after <= cz_lo_sel;
          cz_lo_lock <= 1'b1;
        end else if (cz_lo_one) begin
          cz_lo_w0 <= 1'b1;
        end
      end
      if (cz_w1 && (cz_w1_a == SEP_CPU_CTRL_EXT_TRNG_SRC_SEL_REG_ADDR) && cz_lo_one &&
          (3'(cz_w1_d & CzSelMask) != cz_aw_sel) && (cz_sel == cz_aw_sel) && cy_own_xhs) begin
        cz_dlv(1, 3'd4);
      end
      if (rd_ev && cy_rd_known && (ar_addr_q == SEP_CPU_CTRL_EXT_TRNG_SRC_SEL_LOCK_REG_ADDR)) begin
        if ((rd_data & CzLockMask) != 32'h0) begin
          if (!cz_lo_one && cz_lo_lock && cy_own_xhs) cz_dlv(1, cz_lo_after ? 3'd0 : 3'd1);
          if (cz_lo_w0 && cy_own_xhs) cz_dlv(1, 3'd3);
          cz_lo_one <= 1'b1;
          cz_lo_w0  <= 1'b0;
        end else if (cz_lo_rst) begin
          cz_lo_rst_l0 <= 1'b1;
        end
      end
      if (rd_ev && cy_rd_known && (ar_addr_q == SEP_CPU_CTRL_EXT_TRNG_SRC_SEL_REG_ADDR) && cz_lo_rst &&
          ((rd_data & CzSelMask) == 32'(SEP_CPU_CTRL_EXT_TRNG_SRC_SEL_REG_DEFAULT))) begin
        cz_lo_rst_s7 <= 1'b1;
      end
      if (cz_lo_rst && cz_lo_rst_l0 && cz_lo_rst_s7) begin
        if (cy_own_xhs) cz_dlv(1, 3'd5);
        cz_lo_rst <= 1'b0;
      end
    end

    for (int s = 0; s < 2; s++) begin
      int i;
      logic ev;
      logic pend;
      i  = s + 1;
      ev = (ext_trng_req_i[i].tvalid === 1'b1);
      // x_ext_beat: with the external select, a full-strobe beat completes
      // at the mux; a partial-strobe beat stays pending for two clocks.
      pend = cz_sel[i] && ev && (ext_trng_req_i[i].tstrb != 4'hF) && (mux_rsp_i[i].tready === 1'b0);
      if ((cy_own_xhs || cy_own_xrst) && cz_sel[i] && cz_mhs[i] && (ext_trng_req_i[i].tstrb == 4'hF)) begin
        cz_dlv(2, {1'b0, 1'(s), 1'b0});
      end
      if ((cy_own_xhs || cy_own_xrst) && pend && cz_pp_q[s]) cz_dlv(2, {1'b0, 1'(s), 1'b1});
      cz_pp_q[s] <= pend;

      if (cy_own_xhs) begin
        // cp_unselected_drop: with the internal select an external beat
        // completes (external ready 1) and the post-mux valid stays 0.
        if (!cz_sel[i] && ev && (ext_trng_tready_i[i] === 1'b1) && (mux_req_i[i].tvalid === 1'b0)) begin
          cz_dlv(3, {2'b00, 1'(s)});
        end
        // cp_ext_stall: with the external select, ready falls with valid 1
        // and rises again.
        if (!cz_sel[i]) begin
          cz_st_arm[s] <= 1'b0;
        end else if (ev && (ext_trng_tready_i[i] === 1'b0) && !cz_st_arm[s]) begin
          cz_st_arm[s] <= 1'b1;
        end else if (cz_st_arm[s] && (ext_trng_tready_i[i] === 1'b1)) begin
          cz_dlv(4, {2'b00, 1'(s)});
          cz_st_arm[s] <= 1'b0;
        end
      end else begin
        cz_st_arm[s] <= 1'b0;
      end

      // cp_hold_internal: with the external select, the internal endpoint
      // holds valid 1 and a stable word; after the select returns, its first
      // handshake carries that word. That handshake can be on the clock the
      // select returns.
      if (!cy_own_xhs) begin
        cz_ho_on[s]   <= 1'b0;
        cz_ho_wait[s] <= 1'b0;
      end else if (cz_sel[i]) begin
        cz_ho_wait[s] <= 1'b0;
        if (drbg_int_req_i[i].tvalid === 1'b1) begin
          if (!cz_ho_on[s]) begin
            cz_ho_on[s]  <= 1'b1;
            cz_ho_bad[s] <= 1'b0;
            cz_ho_w[s]   <= drbg_int_req_i[i].tdata;
          end else if (drbg_int_req_i[i].tdata != cz_ho_w[s]) begin
            cz_ho_bad[s] <= 1'b1;
          end
        end else if (cz_ho_on[s]) begin
          cz_ho_bad[s] <= 1'b1;
        end
      end else begin
        logic hw;
        hw = cz_ho_wait[s];
        if (cz_ho_on[s] && cz_sel_q[i]) begin
          hw = !cz_ho_bad[s];
          cz_ho_on[s] <= 1'b0;
        end
        if (hw && cz_mhs[i]) begin
          if (mux_req_i[i].tdata == cz_ho_w[s]) cz_dlv(5, {2'b00, 1'(s)});
          hw = 1'b0;
        end
        cz_ho_wait[s] <= hw;
      end

      // Ring of the last 16 external words that the mux passed on.
      if (cz_sel[i] && cz_mhs[i]) begin
        cz_ring[s][cz_ring_wp[s]]   <= mux_req_i[i].tdata;
        cz_ring_v[s][cz_ring_wp[s]] <= 1'b1;
        cz_ring_wp[s]               <= cz_ring_wp[s] + 4'd1;
      end
    end

    // cp_ext_tuser: a word that a consuming adapter accepts and that an
    // external beat carried has edn_fips 1 (illegal 0).
    if (cy_own_xhs) begin
      for (int c = 0; c < 4; c++) begin
        if (cy_ack[c] && cz_sel[1] && cz_in_ring(0, edn_bus_i[32*c+:32])) begin
          cz_dlv(8, {1'b0, (edn_fips_i[c] !== 1'b1), 1'b0});
        end
      end
      if ((pool_edn_ack_i === 1'b1) && cz_sel[2] && cz_in_ring(1, pool_edn_bus_i)) begin
        cz_dlv(8, {1'b0, (pool_edn_fips_i !== 1'b1), 1'b1});
      end
    end

    // cp_pool_pop: an OKAY DATA read at a pool level of 2 to 31 or 32 at
    // the AR handshake; the pool feed (native EDN acknowledge) at level 31,
    // which fills the pool to 32.
    if (cy_own_xhs) begin
      if (rd_ev && (ar_addr_q == ENTROPY_POOL_DATA_REG_ADDR) && !$isunknown(cz_pool_ar)) begin
        if ((cz_pool_ar >= 6'd2) && (cz_pool_ar <= 6'd31)) cz_dlv(6, 3'd0);
        if (cz_pool_ar == 6'd32) cz_dlv(6, 3'd1);
      end
      if ((pool_edn_ack_i === 1'b1) && (pool_level_i == 6'd31)) cz_dlv(6, 3'd2);
    end

    // cp_ext_irq: vector bit 16 follows a rise or fall of ext_trng_irq_i
    // within CySettle clocks.
    if (!cy_own_xhs) begin
      cz_irq_arm <= '0;
    end else begin
      logic irq;
      irq = (ext_trng_irq_i === 1'b1);
      if (irq && !cz_irq_q) begin
        cz_irq_arm <= 2'b01;
        cz_irq_cnt <= 0;
      end else if (!irq && cz_irq_q) begin
        cz_irq_arm <= 2'b10;
        cz_irq_cnt <= 0;
      end else if (cz_irq_arm != 2'b00) begin
        if (cz_irq_arm[0] && irq && cy_vec[16]) begin
          cz_dlv(7, 3'd0);
          cz_irq_arm <= '0;
        end else if (cz_irq_arm[1] && !irq && !cy_vec[16]) begin
          cz_dlv(7, 3'd1);
          cz_irq_arm <= '0;
        end else if (cz_irq_cnt >= CySettle) begin
          cz_irq_arm <= '0;
        end
        cz_irq_cnt <= cz_irq_cnt + 1;
      end
    end

    // cp_km_ext_stream (1.53): with select bit 0 set, a beat completed at
    // external port 0 is the Key Manager beat of the same clock with the
    // same word, and the external ready equals the Key Manager ready on
    // every clock since the select. Illegal: with the internal select of
    // stream 1 or 2, a valid post-mux word differs from the endpoint word.
    if (!cy_own_mix || !cz_sel[0]) begin
      cz_km_rdy_bad <= 1'b0;
    end else begin
      logic rb;
      rb = cz_km_rdy_bad || (ext_trng_tready_i[0] !== mux_rsp_i[0].tready);
      cz_km_rdy_bad <= rb;
      if ((ext_trng_req_i[0].tvalid === 1'b1) && (ext_trng_tready_i[0] === 1'b1)) begin
        if (cz_mhs[0] && (mux_req_i[0].tdata == ext_trng_req_i[0].tdata)) cz_dlv(9, 3'd0);
        if (!rb) cz_dlv(9, 3'd1);
      end
    end
    if (cy_own_mix) begin
      for (int i = 1; i < 3; i++) begin
        if (!cz_sel[i] && (mux_req_i[i].tvalid === 1'b1) &&
            (mux_req_i[i].tdata !== drbg_int_req_i[i].tdata)) begin
          cz_dlv(9, 3'd2);
        end
      end
    end

    // cp_active_sinks (1.53): the first word served to each sink in a
    // graded window.
    if (!cy_own_mix || cz_win_open) begin
      cz_as_done <= '0;
    end else begin
      logic [5:0] ev;
      ev[0] = cz_mhs[0];
      for (int c = 0; c < 4; c++) ev[c+1] = cy_ack[c];
      ev[5] = (pool_edn_ack_i === 1'b1) && !cz_pool_ack_q;
      for (int k = 0; k < 6; k++) begin
        if (ev[k] && !cz_as_done[k]) cz_dlv(10, 3'(k));
      end
      cz_as_done <= cz_as_done | ev;
    end
  end

  // =====================================================================
  // eFuse, lifecycle, SEC_DIS and locked-field groups (docs/SEP_FCOV.adoc,
  // eFuse, lifecycle groups). Every point samples only while graded_owner
  // holds the code of a test that owns the point or the cell. Every point
  // that reads shadow-derived state samples with fuse_sense_done_i high,
  // except the SEC_DIS points the group rows name. The settle counts, windows
  // and timeouts below are choices of the environment; the specification
  // gives none.
  // =====================================================================
  wire ef_own_win = (graded_owner == FcovOwnSepEfuseWindowDecodeResetTest);
  wire ef_own_fld = (graded_owner == FcovOwnSepEfuseFieldLayoutRandTest);
  wire ef_own_cw = (graded_owner == FcovOwnSepLccStateCodewordRandTest);
  wire ef_own_fc = (graded_owner == FcovOwnSepLccFeatCtrlStateMatrixRandTest);
  wire ef_own_tr = (graded_owner == FcovOwnSepEfuseTransientRmaRandTest);
  wire ef_own_tch = (graded_owner == FcovOwnSepEfuseTokenChannelRandTest);
  wire ef_own_tf = (graded_owner == FcovOwnSepEfuseTokenFaultMatrixTest);
  wire ef_own_ifs = (graded_owner == FcovOwnSepEfuseInterfaceStatusRandTest);
  wire ef_own_lock = (graded_owner == FcovOwnSepEfuseLockSlotMatrixRandTest);
  wire ef_own_stm = (graded_owner == FcovOwnSepEfuseSecureTmMatrixRandTest);
  wire ef_own_jtag = (graded_owner == FcovOwnSepEfuseJtagAccessRandTest);
  wire ef_own_sdt = (graded_owner == FcovOwnSepSecDisTimingRandTest);
  wire ef_own_shim = (graded_owner == FcovOwnSepEfuseShimResponseFaultTest);

  localparam int unsigned EfFeatSettle = 8;  // feature-change inputs stable
  localparam int unsigned EfTokSettle = 8;  // token-change inputs stable (N)
  localparam int unsigned EfTransWin = 256;  // x_transient outcome window N
  localparam int unsigned EfWrSettle = 8;  // clocks from a write B to its effect
  localparam int unsigned EfGoSettle = 4;  // clocks after a go before idle counts
  localparam int unsigned EfCmdWin = 64;  // read_rlocked window after idle
  localparam int unsigned EfBothWin = 1024;  // both_enables sample after the go
  localparam int unsigned EfProgN = 64;  // x_prog_lifecycle N
  localparam int unsigned EfLatchWin = 4096;  // digest replacement after release

  // Windows of 0x1093_0000 to 0x1093_FFFF (memory_map.adoc): shadow map,
  // interface control, its unused tail, token registers, the span between the
  // token registers and 0x1093_0600 (not declared), reserved.
  localparam logic [2:0] EfWShadow = 3'd0;
  localparam logic [2:0] EfWCtrlIn = 3'd1;
  localparam logic [2:0] EfWCtrlPast = 3'd2;
  localparam logic [2:0] EfWTokIn = 3'd3;
  localparam logic [2:0] EfWTokGap = 3'd4;
  localparam logic [2:0] EfWRsvd = 3'd5;
  localparam logic [2:0] EfWNone = 3'd7;
  localparam logic [31:0] EfMapBase = SEP_EFUSE_MAP_REG_MAP_BASE_ADDR;
  localparam logic [31:0] EfMapEnd = EfMapBase + SEP_EFUSE_MAP_REG_MAP_SIZE;
  localparam logic [31:0] EfCtrlBase = EFUSE_INTERFACE_CTRL_REG_MAP_BASE_ADDR;
  localparam logic [31:0] EfCtrlEnd = EfCtrlBase + EFUSE_INTERFACE_CTRL_REG_MAP_SIZE;
  localparam logic [31:0] EfMmrBase = EFUSE_MMR_REG_MAP_BASE_ADDR;
  localparam logic [31:0] EfMmrEnd = EfMmrBase + EFUSE_MMR_REG_MAP_SIZE;
  localparam logic [31:0] EfRsvdBase = EfMapBase + 32'h0000_0600;
  localparam logic [31:0] EfRsvdHigh = EfMapBase + 32'h0000_1000;
  localparam logic [31:0] EfWinEnd = EfMapBase + 32'h0001_0000;

  function automatic logic [2:0] ef_win(input logic [31:0] a);
    if (in_win(a, EfMapBase, EfMapEnd)) return EfWShadow;
    if (in_win(a, EfCtrlBase, EfCtrlEnd)) return EfWCtrlIn;
    if (in_win(a, EfCtrlEnd, EfMmrBase)) return EfWCtrlPast;
    if (in_win(a, EfMmrBase, EfMmrEnd)) return EfWTokIn;
    if (in_win(a, EfMmrEnd, EfRsvdBase)) return EfWTokGap;
    if (in_win(a, EfRsvdBase, EfWinEnd)) return EfWRsvd;
    return EfWNone;
  endfunction

  // Register addresses of the interface control and token blocks.
  localparam logic [31:0] EfStatus = EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_REG_ADDR;
  localparam logic [31:0] EfPgCtrl = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_REG_ADDR;
  localparam logic [31:0] EfRdCtrl = EFUSE_INTERFACE_CTRL_EFUSE_READ_CTRL_REG_ADDR;
  localparam logic [31:0] EfPgData = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_INTERFACE_READ_DATA_REG_ADDR;
  localparam logic [31:0] EfRdData = EFUSE_INTERFACE_CTRL_EFUSE_READ_INTERFACE_READ_DATA_REG_ADDR;
  localparam logic [31:0] EfRdTmo = EFUSE_INTERFACE_CTRL_EFUSE_READ_REQ_TIMEOUT_REG_ADDR;
  localparam logic [31:0] EfPgTmo = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_REQ_TIMEOUT_REG_ADDR;
  localparam logic [31:0] EfTokSip = EFUSE_MMR_RMA_SIP_TOKEN_I_0__REG_ADDR;
  localparam logic [31:0] EfTokChip = EFUSE_MMR_RMA_CHIPLET_TOKEN_I_0__REG_ADDR;
  localparam logic [31:0] EfTokSec = EFUSE_MMR_SEC_DISABLE_TOKEN_I_0__REG_ADDR;
  localparam logic [31:0] EfTokEop = EFUSE_MMR_TOKEN_EOP_REG_ADDR;
  localparam logic [31:0] EfMatchSip = EFUSE_MMR_RMA_SIP_TOKEN_MATCH_REG_ADDR;
  localparam logic [31:0] EfMatchChip = EFUSE_MMR_RMA_CHIPLET_TOKEN_MATCH_REG_ADDR;
  localparam logic [31:0] EfMatchSec = EFUSE_MMR_SEC_DISABLE_TOKEN_MATCH_REG_ADDR;
  localparam logic [31:0] EfMatchFault = EFUSE_MMR_TOKEN_MATCH_FAULT_REG_ADDR;
  localparam logic [31:0] EfDemote1 = SEP_LIFECYCLE_CTRL_DEMOTE_1_REG_ADDR;
  localparam logic [31:0] EfDemote2 = SEP_LIFECYCLE_CTRL_DEMOTE_2_REG_ADDR;

  // Field masks of the interface control registers (efuse_interface_ctrl.adoc).
  localparam logic [31:0] EfPgAddrMask = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_EFUSE_ADDR_MASK;
  localparam logic [31:0] EfPgDataMask = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_EFUSE_DATA_MASK;
  localparam logic [31:0] EfPgGoMask = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_EFUSE_PROGRAM_GO_MASK;
  localparam logic [31:0] EfPgEnMask = EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_CTRL_PROGRAM_ENABLE_MASK;
  localparam logic [31:0] EfRdAddrMask = EFUSE_INTERFACE_CTRL_EFUSE_READ_CTRL_EFUSE_ADDR_MASK;
  localparam logic [31:0] EfRdGoMask = EFUSE_INTERFACE_CTRL_EFUSE_READ_CTRL_EFUSE_READ_GO_MASK;
  localparam logic [31:0] EfRdEnMask = EFUSE_INTERFACE_CTRL_EFUSE_READ_CTRL_READ_ENABLE_MASK;
  localparam logic [31:0] EfReqErrMask =
      EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_EFUSE_REQ_ERROR_MASK;
  localparam logic [31:0] EfRdAddrClrMask =
      EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_EFUSE_READ_ADDR_ERROR_CLEAR_MASK;
  localparam logic [31:0] EfPgAddrClrMask =
      EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_EFUSE_PROGRAM_ADDR_ERROR_CLEAR_MASK;
  localparam logic [31:0] EfReqErrClrMask =
      EFUSE_INTERFACE_CTRL_EFUSE_INTERFACE_CTRL_STATUS_EFUSE_REQ_ERROR_CLEAR_MASK;
  localparam logic [31:0] EfPgTmoEnMask =
      EFUSE_INTERFACE_CTRL_EFUSE_PROGRAM_REQ_TIMEOUT_PROGRAM_REQ_TIMEOUT_ENABLE_MASK;
  localparam logic [31:0] EfDemoteMask = 32'(SEP_LIFECYCLE_CTRL_DEMOTE_DEMOTE_MASK);
  localparam logic [31:0] EfDemLockMask = 32'(SEP_LIFECYCLE_CTRL_DEMOTE_LOCK_MASK);
  // The fuse map is 8192 bits (otp_fuse_controller.adoc, Fuse Fields).
  localparam int unsigned EfFuseBits = sep_efuse_pkg::NumEfuseBits;

  // Shadow word index of each field: byte offset / 4 (sep_efuse_map.adoc).
  localparam int unsigned EfWLocks = SEP_EFUSE_MAP_LOCKS_REG_OFFSET / 4;
  localparam int unsigned EfWLocksSp = SEP_EFUSE_MAP_LOCKS_SPARE_REG_OFFSET / 4;
  localparam int unsigned EfWLc = SEP_EFUSE_MAP_LC_STATE_REG_OFFSET / 4;
  localparam int unsigned EfWSboot = SEP_EFUSE_MAP_SBOOT_DIS_REG_OFFSET / 4;
  localparam int unsigned EfWTrans = SEP_EFUSE_MAP_TRANSIENT_RMA_EN_REG_OFFSET / 4;
  localparam int unsigned EfWSipDis = SEP_EFUSE_MAP_SIP_DIS_REG_OFFSET / 4;
  localparam int unsigned EfWSysDis = SEP_EFUSE_MAP_SYS_DIS_REG_OFFSET / 4;
  localparam int unsigned EfWSipDig = SEP_EFUSE_MAP_RMA_SIP_TOKEN_DIGEST_REG_OFFSET / 4;
  localparam int unsigned EfWChipDig = SEP_EFUSE_MAP_RMA_CHIPLET_TOKEN_DIGEST_REG_OFFSET / 4;
  localparam int unsigned EfWRevoke = SEP_EFUSE_MAP_CHIPLET_PUBK_REVOKE_REG_OFFSET / 4;
  localparam int unsigned EfWBl1 = SEP_EFUSE_MAP_BL1_VERSION_REG_OFFSET / 4;
  localparam int unsigned EfWBl2 = SEP_EFUSE_MAP_BL2_VERSION_REG_OFFSET / 4;
  localparam int unsigned EfWStatusRpt = SEP_EFUSE_MAP_STATUS_RPT_REG_OFFSET / 4;
  localparam int unsigned EfWRomCtl = SEP_EFUSE_MAP_ROM_CTL_REG_OFFSET / 4;
  localparam int unsigned EfWSysclk = SEP_EFUSE_MAP_SYSCLK_FREQ_MHZ_REG_OFFSET / 4;
  localparam int unsigned EfWSigners = SEP_EFUSE_MAP_REQUIRED_SIGNERS_REG_OFFSET / 4;
  localparam int unsigned EfWAlgs = SEP_EFUSE_MAP_REQUIRED_ALGS_REG_OFFSET / 4;
  // CHIPLET_PUBK_REVOKE uses bits 25:0 (sep_efuse_map.adoc, CHIPLET_PUBK_REVOKE).
  localparam logic [31:0] EfRevokeAll = 32'h03FF_FFFF;

  // Lock slot n starts at EfSlotOff[n] and ends at EfSlotOff[n+1]
  // (sep_efuse_map.adoc, LOCKS and LOCKS_SPARE: slot 0 LC_STATE to slot 40
  // spare8, in RDL field order). The LOCKS words are not a slot.
  localparam int unsigned EfSlots = 41;
  localparam logic [10:0] EfSlotOff[42] = '{
      11'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SBOOT_DIS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_TRANSIENT_RMA_EN_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_DIS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYS_DIS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_RMA_SIP_TOKEN_DIGEST_REG_OFFSET),
      11'(SEP_EFUSE_MAP_RMA_CHIPLET_TOKEN_DIGEST_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CLASS_KEY_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_REVOKE_REG_OFFSET),
      11'(SEP_EFUSE_MAP_BL1_VERSION_REG_OFFSET),
      11'(SEP_EFUSE_MAP_BL2_VERSION_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_UID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_PUBK_HASH0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_UID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYS_PUBK_HASH_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYS_UID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_STATUS_RPT_REG_OFFSET),
      11'(SEP_EFUSE_MAP_ROM_CTL_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYSCLK_FREQ_MHZ_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_HASH0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_HASH1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_REQUIRED_SIGNERS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_REQUIRED_ALGS_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_PQC_HASH0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_CHIPLET_PUBK_PQC_HASH1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_PUBK_PQC_HASH0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SYS_PUBK_PQC_HASH_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_PUBK_HASH1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SIP_PUBK_PQC_HASH1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SEP_CHIPLET_ID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SEP_SIP_ID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SEP_SYS_ID_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE0_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE1_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE2_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE3_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE4_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE5_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE6_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE7_REG_OFFSET),
      11'(SEP_EFUSE_MAP_SPARE8_REG_OFFSET),
      11'(SEP_EFUSE_MAP_REG_MAP_SIZE)
  };
  localparam logic [5:0] EfNoSlot = 6'd63;
  localparam logic [5:0] EfSlotSipDis = 6'd3;
  localparam logic [5:0] EfSlotSysDis = 6'd4;
  localparam logic [5:0] EfSlotClassKey = 6'd7;
  localparam logic [5:0] EfSlotChipUid = 6'd11;
  localparam logic [5:0] EfSlotSipUid = 6'd13;
  localparam logic [5:0] EfSlotSysUid = 6'd15;
  localparam logic [5:0] EfSlotSigners = 6'd21;
  localparam logic [5:0] EfSlotAlgs = 6'd22;
  localparam logic [5:0] EfSlotSpare0 = 6'd32;

  function automatic logic [5:0] ef_slot_of(input logic [10:0] off);
    for (int s = 0; s < EfSlots; s++) begin
      if ((off >= EfSlotOff[s]) && (off < EfSlotOff[s+1])) return 6'(s);
    end
    return EfNoSlot;
  endfunction

  // Secret fields of the secure test mode mask (test_mode.adoc, Protection
  // While Active): 0 CHIPLET_UID, 1 SIP_UID, 2 SYS_UID, 3 CLASS_KEY; 4 none.
  function automatic logic [2:0] ef_secret_of(input logic [5:0] s);
    case (s)
      EfSlotChipUid: return 3'd0;
      EfSlotSipUid: return 3'd1;
      EfSlotSysUid: return 3'd2;
      EfSlotClassKey: return 3'd3;
      default: return 3'd4;
    endcase
  endfunction

  // Lifecycle raw class (lifecycle_controller.adoc, Per-LC-state Feature
  // Control Profile): 0 TEST_DEV, 1 PROD, 2 PROD_END, 3 RMA_SIP, 4
  // RMA_CHIPLET, 5 INVALID.
  localparam logic [2:0] EfTd = 3'd0;
  localparam logic [2:0] EfProd = 3'd1;
  localparam logic [2:0] EfPe = 3'd2;
  localparam logic [2:0] EfRs = 3'd3;
  localparam logic [2:0] EfRc = 3'd4;
  localparam logic [2:0] EfInv = 3'd5;
  function automatic logic [2:0] ef_cls(input logic [3:0] raw);
    if (raw == 4'b0000) return EfTd;
    if (raw == 4'b0001) return EfProd;
    if (raw == 4'b1000) return EfPe;
    if (raw[3:1] == 3'b001) return EfRs;
    if (raw[3:1] == 3'b011) return EfRc;
    return EfInv;
  endfunction

  // Disable vector groups (lifecycle_controller.adoc, Disable Vector Format):
  // 0 DBG_1 [23:0], 1 DBG_2 [47:24], 2 Function [63:48].
  function automatic logic [23:0] ef_grp(input logic [63:0] v, input int unsigned g);
    case (g)
      0: return v[23:0];
      1: return v[47:24];
      default: return {8'h00, v[63:48]};
    endcase
  endfunction
  function automatic logic [23:0] ef_gmask(input int unsigned g);
    return (g == 2) ? 24'h00_FFFF : 24'hFF_FFFF;
  endfunction

  // Profile rows of the feature control table: TEST_DEV 00/10/01/11 then
  // SEC_DIS (0-4), PROD the same (5-9), PROD_END SEC_DIS 0/1 (10-11),
  // RMA_SIP (12-13), RMA_CHIPLET (14), INVALID (15-16). Demotion is
  // {DEMOTE_1, DEMOTE_2}.
  function automatic logic [4:0] ef_row(input logic [2:0] c, input logic sd, input logic [1:0] dm);
    case (c)
      EfTd: return sd ? 5'd4 : 5'(dm == 2'b00 ? 0 : dm == 2'b10 ? 1 : dm == 2'b01 ? 2 : 3);
      EfProd: return sd ? 5'd9 : 5'(dm == 2'b00 ? 5 : dm == 2'b10 ? 6 : dm == 2'b01 ? 7 : 8);
      EfPe: return sd ? 5'd11 : 5'd10;
      EfRs: return sd ? 5'd13 : 5'd12;
      EfRc: return 5'd14;
      default: return sd ? 5'd16 : 5'd15;
    endcase
  endfunction

  // Class of a group in a profile row, as the table gives it: 0 T (all ones),
  // 1 F (all zeros), 2 ~SIP_DIS, 3 ~(SIP_DIS | SYS_DIS).
  function automatic logic [2:0] ef_prof_cls(input logic [4:0] row, input int unsigned g);
    case (row)
      5'd0: return 3'd3;
      5'd1: return (g == 0) ? 3'd0 : 3'd3;
      5'd2: return (g == 1) ? 3'd0 : 3'd3;
      5'd3: return (g == 2) ? 3'd3 : 3'd0;
      5'd5, 5'd10: return (g == 2) ? 3'd3 : 3'd1;
      5'd6: return (g == 1) ? 3'd1 : 3'd3;
      5'd7: return (g == 0) ? 3'd1 : 3'd3;
      5'd8: return 3'd3;
      5'd12: return 3'd2;
      5'd15: return 3'd1;
      default: return 3'd0;  // SEC_DIS rows and RMA_CHIPLET
    endcase
  endfunction

  // Observed class of feature group g: 0 all ones, 1 all zeros, 2 ~SIP_DIS,
  // 3 ~(SIP_DIS | SYS_DIS), 4 other.
  function automatic logic [2:0] ef_obs_cls(input logic [63:0] f, input logic [63:0] sip,
                                            input logic [63:0] sys, input int unsigned g);
    logic [23:0] m, fv, sv, yv;
    m  = ef_gmask(g);
    fv = ef_grp(f, g);
    sv = ef_grp(sip, g);
    yv = ef_grp(sys, g);
    if (fv == m) return 3'd0;
    if (fv == 24'h0) return 3'd1;
    if (fv == (~sv & m)) return 3'd2;
    if (fv == (~(sv | yv) & m)) return 3'd3;
    return 3'd4;
  endfunction

  // Token status codes (token_processing.adoc, Token Matching Mechanism).
  localparam logic [5:0] EfCodeIdle = 6'h00;
  localparam logic [5:0] EfCodeMatch = 6'h15;
  localparam logic [5:0] EfCodeMismatch = 6'h2A;
  localparam logic [5:0] EfCodeErr = 6'h3F;

  // ---------------------------------------------------------------------
  // Covergroups. Each sample carries one point; the valid bit is set only
  // when the owner of the point or of the cell is in its window. A field
  // named bad is 1 when the observed outcome is not the outcome the cell
  // allows; those values are illegal_bins.
  // ---------------------------------------------------------------------
  typedef struct packed {
    logic [2:0] wn;
    logic wn_v;  // cp_window: window class
    logic rz;
    logic rz_v;  // cp_rsvd_zone: 0 low, 1 high
    logic [5:0] wr;
    logic wr_v;  // x_win_op_resp: {ignored, window, 0 rd / 1 wr, OKAY}
    logic [3:0] sf;
    logic sf_v;  // cp_shadow_field: register index
    logic [1:0] ea;
    logic ea_v;  // cp_edge_addr
    logic [3:0] cr;
    logic cr_v;  // x_ctrl_reg_op: register and op
    logic [3:0] tb;
    logic tb_v;  // x_token_blk_op: register and op
    logic ji;
    logic ji_v;  // cp_jtag_id_class: 1 nonzero
  } ef_geo_t;

  covergroup sep_efuse_map_geometry_cg with function sample (ef_geo_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_map_geometry_cg";
    // The span between the token registers and 0x1093_0600 is not declared.
    cp_window: coverpoint s.wn iff (s.wn_v) {
      bins shadow = {EfWShadow};
      bins ctrl_in = {EfWCtrlIn};
      bins ctrl_past = {EfWCtrlPast};
      bins tok_in = {EfWTokIn};
      bins rsvd = {EfWRsvd};
    }
    cp_rsvd_zone: coverpoint s.rz iff (s.rz_v) {bins low = {1'b0}; bins high = {1'b1};}
    // Sampled with fuse_sense_done_i high, for the in-extent windows only.
    // The ignored accesses are those whose response no source states: a
    // shadow write, a read-locked shadow read, a STATUS write, a write to an
    // access-R register and a read of TOKEN_EOP.
    x_win_op_resp: coverpoint s.wr iff (s.wr_v) {
      bins shadow_rd_okay = {6'b0_000_0_1};
      bins ctrl_rd_okay = {6'b0_001_0_1};
      bins ctrl_wr_okay = {6'b0_001_1_1};
      bins tok_rd_okay = {6'b0_011_0_1};
      bins tok_wr_okay = {6'b0_011_1_1};
      illegal_bins in_extent_not_okay = {
        6'b0_000_0_0, 6'b0_001_0_0, 6'b0_001_1_0, 6'b0_011_0_0, 6'b0_011_1_0
      };
      ignore_bins response_not_stated = {[6'b1_000_0_0 : 6'b1_111_1_1]};
    }
    cp_shadow_field: coverpoint s.sf iff (s.sf_v) {
      bins lc_state = {4'd0};
      bins sboot_dis = {4'd1};
      bins transient_rma_en = {4'd2};
      bins chiplet_pubk_revoke = {4'd3};
      bins status_rpt = {4'd4};
      bins rom_ctl = {4'd5};
      bins sysclk_freq_mhz = {4'd6};
      bins required_signers = {4'd7};
      bins required_algs = {4'd8};
    }
    cp_edge_addr: coverpoint s.ea iff (s.ea_v) {
      bins last_shadow_word = {2'd0};
      bins last_ctrl_reg = {2'd1};
      bins first_past_extent = {2'd2};
      bins first_reserved = {2'd3};
    }
    // The write cells of the two timeout registers are not declared.
    x_ctrl_reg_op: coverpoint s.cr iff (s.cr_v) {
      bins status_rd = {4'd0};
      bins status_wr = {4'd1};
      bins program_ctrl_rd = {4'd2};
      bins program_ctrl_wr = {4'd3};
      bins read_ctrl_rd = {4'd4};
      bins read_ctrl_wr = {4'd5};
      bins read_req_timeout_rd = {4'd6};
      bins program_req_timeout_rd = {4'd7};
      bins program_if_read_data_rd = {4'd8};
      bins read_if_read_data_rd = {4'd9};
    }
    // The TOKEN_MATCH_FAULT read is not declared.
    x_token_blk_op: coverpoint s.tb iff (s.tb_v) {
      bins sip_token_rd = {4'd0};
      bins sip_token_wr = {4'd1};
      bins chiplet_token_rd = {4'd2};
      bins chiplet_token_wr = {4'd3};
      bins sec_dis_token_rd = {4'd4};
      bins sec_dis_token_wr = {4'd5};
      bins sip_match_rd = {4'd6};
      bins chiplet_match_rd = {4'd7};
      bins sec_dis_match_rd = {4'd8};
      bins token_eop_wr = {4'd9};
    }
    // The zero value is not declared.
    cp_jtag_id_class: coverpoint s.ji iff (s.ji_v) {
      bins nonzero = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic sb;
    logic sb_v;  // cp_sboot_dis
    logic [1:0] rs;
    logic rs_v;  // cp_required_signers
    logic [3:0] al;
    logic al_v;  // x_algs_owner_value: owner * 4 + value
    logic [1:0] sr;
    logic sr_v;  // cp_status_rpt
    logic [3:0] rc;
    logic rc_v;  // cp_rom_ctl: {0, endianness} or {1, swap class}
    logic [1:0] sc;
    logic sc_v;  // cp_sysclk_class: 0 one, 1 middle, 2 max
    logic [1:0] rv;
    logic rv_v;  // cp_revoke_class
    logic [2:0] vb;
    logic vb_v;  // x_version_bit: field * 3 + index class
  } ef_fld_t;

  covergroup sep_efuse_field_value_cg with function sample (ef_fld_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_field_value_cg";
    cp_sboot_dis: coverpoint s.sb iff (s.sb_v) {bins zero = {1'b0}; bins one = {1'b1};}
    cp_required_signers: coverpoint s.rs iff (s.rs_v) {bins value[] = {[2'd0 : 2'd3]};}
    // Owner chiplet [3:0], SiP [7:4], system [11:8] x bits 1:0 of the nibble.
    x_algs_owner_value: coverpoint s.al iff (s.al_v) {
      bins chiplet[] = {[4'd0 : 4'd3]};
      bins sip[] = {[4'd4 : 4'd7]};
      bins system[] = {[4'd8 : 4'd11]};
    }
    cp_status_rpt: coverpoint s.sr iff (s.sr_v) {bins value[] = {[2'd0 : 2'd3]};}
    // Swap class: 0 zero, 1 to 5 the single bit 1 to 5, 6 all five, 7 other.
    cp_rom_ctl: coverpoint s.rc iff (s.rc_v) {
      bins endian_0 = {4'b0_000};
      bins endian_1 = {4'b0_001};
      bins swap_zero = {4'b1_000};
      bins swap_single[] = {[4'b1_001 : 4'b1_101]};
      bins swap_all = {4'b1_110};
      bins swap_other = {4'b1_111};
    }
    // Value 0 is "ignored" and is not drawn, so it has no bin.
    cp_sysclk_class: coverpoint s.sc iff (s.sc_v) {
      bins one = {2'd0}; bins middle = {2'd1}; bins max = {2'd2};
    }
    cp_revoke_class: coverpoint s.rv iff (s.rv_v) {
      bins zero = {2'd0}; bins one_bit = {2'd1}; bins all_26 = {2'd2}; bins other = {2'd3};
    }
    // {BL1_VERSION, BL2_VERSION} x burned bit index {0, 1 to 254, 255}.
    x_version_bit: coverpoint s.vb iff (s.vb_v) {
      bins bl1[] = {[3'd0 : 3'd2]}; bins bl2[] = {[3'd3 : 3'd5]};
    }
  endgroup

  typedef struct packed {
    logic [2:0] sc;
    logic sc_v;  // cp_state_class
    logic [4:0] pr;
    logic pr_v;  // cp_profile_row
    logic [10:0] xr;
    logic xr_v;  // x_row_group_class: {bad, row, group, class}
    logic [2:0] oc;
    logic oc_v;  // cp_or_class: {group, mixed}
    logic rd;
    logic rd_v;  // cp_rma_dis_nonzero: 0 RMA_SIP, 1 RMA_CHIPLET
  } ef_prof_t;

  covergroup sep_lc_feat_ctrl_profile_cg with function sample (ef_prof_t s);
    option.per_instance = 1;
    option.name = "sep_lc_feat_ctrl_profile_cg";
    cp_state_class: coverpoint s.sc iff (s.sc_v) {
      bins test_dev = {EfTd};
      bins prod = {EfProd};
      bins prod_end = {EfPe};
      bins rma_sip = {EfRs};
      bins rma_chiplet = {EfRc};
      bins invalid = {EfInv};
    }
    cp_profile_row: coverpoint s.pr iff (s.pr_v) {bins row[] = {[5'd0 : 5'd16]};}
    // 17 rows x 3 groups with the class of the table (51 cells). The class is
    // in bits 2:0 of the cell; bad is 1 when the observed class is another.
    x_row_group_class: coverpoint s.xr iff (s.xr_v) {
      bins r0[] = {11'h003, 11'h00B, 11'h013};
      bins r1[] = {11'h020, 11'h02B, 11'h033};
      bins r2[] = {11'h043, 11'h048, 11'h053};
      bins r3[] = {11'h060, 11'h068, 11'h073};
      bins r4[] = {11'h080, 11'h088, 11'h090};
      bins r5[] = {11'h0A1, 11'h0A9, 11'h0B3};
      bins r6[] = {11'h0C3, 11'h0C9, 11'h0D3};
      bins r7[] = {11'h0E1, 11'h0EB, 11'h0F3};
      bins r8[] = {11'h103, 11'h10B, 11'h113};
      bins r9[] = {11'h120, 11'h128, 11'h130};
      bins r10[] = {11'h141, 11'h149, 11'h153};
      bins r11[] = {11'h160, 11'h168, 11'h170};
      bins r12[] = {11'h182, 11'h18A, 11'h192};
      bins r13[] = {11'h1A0, 11'h1A8, 11'h1B0};
      bins r14[] = {11'h1C0, 11'h1C8, 11'h1D0};
      bins r15[] = {11'h1E1, 11'h1E9, 11'h1F1};
      bins r16[] = {11'h200, 11'h208, 11'h210};
      illegal_bins wrong_class = {[11'h400 : 11'h7FF]};
    }
    cp_or_class: coverpoint s.oc iff (s.oc_v) {
      bins dbg_1_zero = {3'b00_0};
      bins dbg_1_mixed = {3'b00_1};
      bins dbg_2_zero = {3'b01_0};
      bins dbg_2_mixed = {3'b01_1};
      bins function_zero = {3'b10_0};
      bins function_mixed = {3'b10_1};
    }
    cp_rma_dis_nonzero: coverpoint s.rd iff (s.rd_v) {
      bins rma_sip = {1'b0}; bins rma_chiplet = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [3:0] nb;
    logic nb_v;  // x_named_bit_value: {named bit, value}
    logic [4:0] cb;
    logic cb_v;  // x_closed_bit_owner: {bit index, 0 SIP_DIS / 1 SYS_DIS}
    logic [4:0] dg;
    logic dg_v;  // x_demote_group: {0 DEMOTE_1 / 1 DEMOTE_2, 0 TD / 1 PROD, groups}
  } ef_bit_t;

  covergroup sep_lc_feature_bit_semantics_cg with function sample (ef_bit_t s);
    option.per_instance = 1;
    option.name = "sep_lc_feature_bit_semantics_cg";
    // Named bit 0 SEP_DBG, 1 CHIPLET_DBG, 2 SEP_FUSE_DBG, 3 SMC_FUSE_DBG,
    // 4 SIP_DBG.
    x_named_bit_value: coverpoint s.nb iff (s.nb_v) {
      bins sep_dbg[] = {4'b000_0, 4'b000_1};
      bins chiplet_dbg[] = {4'b001_0, 4'b001_1};
      bins sep_fuse_dbg[] = {4'b010_0, 4'b010_1};
      bins smc_fuse_dbg[] = {4'b011_0, 4'b011_1};
      bins sip_dbg[] = {4'b100_0, 4'b100_1};
    }
    // Bit index k of {0, 1, 2, 3, 4, 23, 24, 25, 47, 48, 63} x owner.
    x_closed_bit_owner: coverpoint s.cb iff (s.cb_v) {
      bins cells[] = {[5'd0 : 5'd21]};
    }
    // DEMOTE_1 changes DBG_1 only and DEMOTE_2 changes DBG_2 only. Groups:
    // bit 0 DBG_1, bit 1 DBG_2, bit 2 Function.
    x_demote_group: coverpoint s.dg iff (s.dg_v) {
      bins demote_1_test_dev = {5'b0_0_001};
      bins demote_1_prod = {5'b0_1_001};
      bins demote_2_test_dev = {5'b1_0_010};
      bins demote_2_prod = {5'b1_1_010};
      wildcard illegal_bins demote_1_other_group = {5'b0_?_?1?, 5'b0_?_1??};
      wildcard illegal_bins demote_2_other_group = {5'b1_?_??1, 5'b1_?_1??};
    }
  endgroup

  typedef struct packed {
    logic [2:0] sp;
    logic sp_v;  // x_sep_port: {Case 3, SEP_FUSE_DBG, other than all-open}
    logic [2:0] mp;
    logic mp_v;  // x_smc_port: {Case 2, SMC_FUSE_DBG, other than all-open}
    logic [1:0] ns;
    logic ns_v;  // cp_nesting
  } ef_dtp_t;

  covergroup sep_dtp_gating_ladder_cg with function sample (ef_dtp_t s);
    option.per_instance = 1;
    option.name = "sep_dtp_gating_ladder_cg";
    // The port is Case 3 AND SEP_FUSE_DBG: same as the all-open cell only
    // when both hold. No bin names the active level.
    x_sep_port: coverpoint s.sp iff (s.sp_v) {
      bins case3_fuse_same = {3'b11_0};
      bins case3_nofuse_other = {3'b10_1};
      bins nocase3_fuse_other = {3'b01_1};
      bins nocase3_nofuse_other = {3'b00_1};
      illegal_bins opposite = {3'b11_1, 3'b10_0, 3'b01_0, 3'b00_0};
    }
    x_smc_port: coverpoint s.mp iff (s.mp_v) {
      bins case2_fuse_same = {3'b11_0};
      bins case2_nofuse_other = {3'b10_1};
      bins nocase2_fuse_other = {3'b01_1};
      bins nocase2_nofuse_other = {3'b00_1};
      illegal_bins opposite = {3'b11_1, 3'b10_0, 3'b01_0, 3'b00_0};
    }
    // Case 3 implies Case 2 by definition, so no reverse value can occur.
    cp_nesting: coverpoint s.ns iff (s.ns_v) {
      bins case1_only = {2'd1}; bins case2_not_case3 = {2'd2}; bins case3 = {2'd3};
    }
  endgroup

  typedef struct packed {
    logic [4:0] rs;
    logic rs_v;  // x_raw16_sigint: {lc_sigint_i, raw}
    logic [4:0] ss;
    logic ss_v;  // x_sigint_state_secdis_out: {bad, state * 2 + SEC_DIS}
  } ef_sig_t;

  covergroup sep_lc_sigint_failclosed_cg with function sample (ef_sig_t s);
    option.per_instance = 1;
    option.name = "sep_lc_sigint_failclosed_cg";
    x_raw16_sigint: coverpoint s.rs iff (s.rs_v) {
      bins raw[] = {[5'd0 : 5'd15]}; illegal_bins sigint_at_sense_done = {[5'd16 : 5'd31]};
    }
    // State TEST_DEV, PROD, PROD_END, RMA_SIP, RMA_CHIPLET x SEC_DIS: SEC_DIS
    // 0 gives all zeros, SEC_DIS 1 all ones. INVALID is not declared.
    x_sigint_state_secdis_out: coverpoint s.ss iff (s.ss_v) {
      bins cells[] = {[5'd0 : 5'd9]}; illegal_bins wrong_output = {[5'd16 : 5'd25]};
    }
  endgroup

  typedef struct packed {
    logic [5:0] tr;
    logic tr_v;  // x_transient: {bad, (enable * 2 + channel) * 5 + old class}
  } ef_trn_t;

  covergroup sep_lc_illegal_transition_cg with function sample (ef_trn_t s);
    option.per_instance = 1;
    option.name = "sep_lc_illegal_transition_cg";
    // Old class 0 TEST_DEV, 1 PROD, 2 RMA_SIP, 3 RMA_CHIPLET, 4 INVALID;
    // channel 0 SIP, 1 CHIPLET. Updated is legal for enable 1 with SIP from
    // TEST_DEV or PROD and with CHIPLET from RMA_SIP; unchanged elsewhere.
    x_transient: coverpoint s.tr iff (s.tr_v) {
      bins cells[] = {[6'd0 : 6'd19]}; illegal_bins wrong_outcome = {[6'd32 : 6'd51]};
    }
  endgroup

  typedef struct packed {
    logic [7:0] sp;
    logic sp_v;  // x_slot_prog: {bad, (slot - 1) * 2 + write-lock}
    logic [7:0] sr;
    logic sr_v;  // x_slot_read: {bad, (slot - 1) * 2 + read-lock}
    logic [3:0] ko;
    logic ko_v;  // x_kind_op: {bad, kind * 2 + op}
    logic [1:0] nf;
    logic nf_v;  // x_neighbor_free: {0 previous / 1 next, 0 program / 1 read}
    logic [1:0] ex;
    logic ex_v;  // x_exempt: 0 LC_STATE, 1 LOCKS, 2 LOCKS_SPARE
    logic sl;
    logic sl_v;  // cp_sense_fills_locked: 0 secret, 1 other
    logic [3:0] sw;
    logic sw_v;  // x_shadow_write_lock: {bad, field * 2 + write-lock}
    logic [1:0] lo;
    logic lo_v;  // cp_lock_order
    logic pv;
    logic pv_v;  // cp_prog_visibility
    logic [2:0] rc;
    logic rc_v;  // cp_round_count
    logic [2:0] lp;
    logic lp_v;  // x_lc_prog_gate: {bit 2, other channel only, landed}
  } ef_lock_t;

  covergroup sep_efuse_lock_policy_cg with function sample (ef_lock_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_lock_policy_cg";
    // Lock clear: the program lands; lock set: it is refused.
    x_slot_prog: coverpoint s.sp iff (s.sp_v) {
      bins cells[] = {[8'd0 : 8'd79]}; illegal_bins wrong_outcome = {[8'd128 : 8'd207]};
    }
    // Lock clear: the frontdoor read returns the sensed word; lock set: the
    // read-interface request sets efuse_req_error.
    x_slot_read: coverpoint s.sr iff (s.sr_v) {
      bins cells[] = {[8'd0 : 8'd79]}; illegal_bins wrong_outcome = {[8'd128 : 8'd207]};
    }
    // Kind 0 none, 1 write, 2 read, 3 write and read; op 0 program, 1 read.
    x_kind_op: coverpoint s.ko iff (s.ko_v) {
      bins cells[] = {[4'd0 : 4'd7]}; illegal_bins wrong_outcome = {[4'd8 : 4'd15]};
    }
    x_neighbor_free: coverpoint s.nf iff (s.nf_v) {
      bins previous_program = {2'b0_0};
      bins previous_read = {2'b0_1};
      bins next_program = {2'b1_0};
      bins next_read = {2'b1_1};
    }
    x_exempt: coverpoint s.ex iff (s.ex_v) {
      bins lc_state = {2'd0}; bins locks = {2'd1}; bins locks_spare = {2'd2};
    }
    cp_sense_fills_locked: coverpoint s.sl iff (s.sl_v) {
      bins secret_field = {1'b0}; bins other_field = {1'b1};
    }
    // Field 0 SIP_DIS, 1 SYS_DIS, 2 REQUIRED_SIGNERS, 3 REQUIRED_ALGS: lock
    // clear changes the shadow (OR), lock set leaves it unchanged.
    x_shadow_write_lock: coverpoint s.sw iff (s.sw_v) {
      bins cells[] = {[4'd0 : 4'd7]}; illegal_bins wrong_outcome = {[4'd8 : 4'd15]};
    }
    cp_lock_order: coverpoint s.lo iff (s.lo_v) {
      bins write_before_lock_lands = {2'd0};
      bins write_after_lock_blocked = {2'd1};
      bins zero_write_keeps_lock = {2'd2};
    }
    cp_prog_visibility: coverpoint s.pv iff (s.pv_v) {
      bins shadow_unchanged_after_program = {1'b0}; bins resense_shows_program = {1'b1};
    }
    cp_round_count: coverpoint s.rc iff (s.rc_v) {bins k[] = {[3'd1 : 3'd4]};}
    // (bit 2, other channel matched only) is not a bin.
    x_lc_prog_gate: coverpoint s.lp iff (s.lp_v) {
      bins bit1_own_landed = {3'b0_0_1};
      bins bit1_other_refused = {3'b0_1_0};
      bins bit2_own_landed = {3'b1_0_1};
      illegal_bins wrong_outcome = {3'b0_0_0, 3'b0_1_1, 3'b1_0_0};
    }
  endgroup

  typedef struct packed {
    logic [4:0] sc;
    logic sc_v;  // x_state_combo: state * 4 + {DEMOTE_1, DEMOTE_2}
    logic ao;
    logic ao_v;  // cp_assert_order: 0 DEMOTE_1 first, 1 DEMOTE_2 first
    logic [3:0] rv;
    logic rv_v;  // cp_reset_vector: {demote 1, lock 1, demote 2, lock 2}
    logic [4:0] oi;
    logic oi_v;  // x_otp_invariant: state * 4 + {DEMOTE_1, DEMOTE_2}
    logic [1:0] ec;
    logic ec_v;  // x_export_codeword: {register, non-complementary}
    logic ex;
    logic ex_v;  // cp_export_changes: register
  } ef_dem_t;

  covergroup sep_lc_demotion_cg with function sample (ef_dem_t s);
    option.per_instance = 1;
    option.name = "sep_lc_demotion_cg";
    x_state_combo: coverpoint s.sc iff (s.sc_v) {bins cells[] = {[5'd0 : 5'd23]};}
    cp_assert_order: coverpoint s.ao iff (s.ao_v) {
      bins demote_1_first = {1'b0}; bins demote_2_first = {1'b1};
    }
    // A reset of a clear state has nothing to clear.
    cp_reset_vector: coverpoint s.rv iff (s.rv_v) {
      bins vector[] = {[4'd1 : 4'd15]}; ignore_bins clear_state = {4'd0};
    }
    x_otp_invariant: coverpoint s.oi iff (s.oi_v) {bins cells[] = {[5'd0 : 5'd23]};}
    // No bin names a polarity.
    x_export_codeword: coverpoint s.ec iff (s.ec_v) {
      bins demote_1_complementary = {2'b0_0};
      bins demote_2_complementary = {2'b1_0};
      illegal_bins non_complementary = {2'b0_1, 2'b1_1};
    }
    cp_export_changes: coverpoint s.ex iff (s.ex_v) {
      bins demote_1 = {1'b0}; bins demote_2 = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [4:0] rl;
    logic rl_v;  // x_reg_lock_write: {register, old lock, write, changed}
    logic [3:0] cn;
    logic cn_v;  // x_committed_next: {register, demote, 0 set / 1 zero, changed}
    logic ci;
    logic ci_v;  // cp_independence: register written while the other is locked
    logic pu;
    logic pu_v;  // cp_profile_unchanged: register
  } ef_dlk_t;

  covergroup sep_lc_demote_lock_cg with function sample (ef_dlk_t s);
    option.per_instance = 1;
    option.name = "sep_lc_demote_lock_cg";
    // Write 0 set demote (0x1), 1 set lock (0x2), 2 zero. With lock 0, set
    // demote and set lock change and zero is unchanged; with lock 1 every
    // write is unchanged.
    x_reg_lock_write: coverpoint s.rl iff (s.rl_v) {
      bins r1_open_set_demote = {5'b0_0_00_1};
      bins r1_open_set_lock = {5'b0_0_01_1};
      bins r1_open_zero = {5'b0_0_10_0};
      bins r1_locked_set_demote = {5'b0_1_00_0};
      bins r1_locked_set_lock = {5'b0_1_01_0};
      bins r1_locked_zero = {5'b0_1_10_0};
      bins r2_open_set_demote = {5'b1_0_00_1};
      bins r2_open_set_lock = {5'b1_0_01_1};
      bins r2_open_zero = {5'b1_0_10_0};
      bins r2_locked_set_demote = {5'b1_1_00_0};
      bins r2_locked_set_lock = {5'b1_1_01_0};
      bins r2_locked_zero = {5'b1_1_10_0};
      wildcard illegal_bins change_while_locked = {5'b?_1_??_1};
    }
    x_committed_next: coverpoint s.cn iff (s.cn_v) {
      bins unchanged[] = {4'd0, 4'd2, 4'd4, 4'd6, 4'd8, 4'd10, 4'd12, 4'd14};
      illegal_bins changed = {4'd1, 4'd3, 4'd5, 4'd7, 4'd9, 4'd11, 4'd13, 4'd15};
    }
    cp_independence: coverpoint s.ci iff (s.ci_v) {
      bins r2_write_while_r1_locked = {1'b1}; bins r1_write_while_r2_locked = {1'b0};
    }
    cp_profile_unchanged: coverpoint s.pu iff (s.pu_v) {
      bins demote_1 = {1'b0}; bins demote_2 = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [2:0] cv;
    logic cv_v;  // x_ch_verdict: {channel, 0 Match / 1 Mismatch}
    logic [5:0] cd;
    logic cd_v;  // cp_code
    logic [4:0] cs;
    logic cs_v;  // x_ch_shape: {bad, channel * 3 + shape}
    logic [2:0] ph;
    logic ph_v;  // x_rma_go_phase: {channel, 0 before / 1 after sense done}
    logic [1:0] ci;
    logic ci_v;  // cp_independence: channel
    logic [1:0] hw;
    logic hw_v;  // cp_hold_word_write: channel
    logic [1:0] gi;
    logic gi_v;  // cp_go_idle_first: channel
    logic [1:0] rt;
    logic rt_v;  // cp_retention
  } ef_tch_t;

  covergroup sep_token_channel_cg with function sample (ef_tch_t s);
    option.per_instance = 1;
    option.name = "sep_token_channel_cg";
    // Channel 0 RMA_SIP, 1 RMA_CHIPLET, 2 SEC_DIS.
    x_ch_verdict: coverpoint s.cv iff (s.cv_v) {
      bins rma_sip[] = {3'b00_0, 3'b00_1};
      bins rma_chiplet[] = {3'b01_0, 3'b01_1};
      bins sec_dis[] = {3'b10_0, 3'b10_1};
    }
    cp_code: coverpoint s.cd iff (s.cd_v) {
      bins idle = {EfCodeIdle};
      bins match = {EfCodeMatch};
      bins mismatch = {EfCodeMismatch};
      bins error = {EfCodeErr};
      illegal_bins other = {[6'h01 : 6'h14], [6'h16 : 6'h29], [6'h2B : 6'h3E]};
    }
    // Shape 0 all zeros, 1 all ones, 2 the token words of another channel.
    // The legal verdict is Mismatch. (SEC_DIS, all zeros) is not declared.
    x_ch_shape: coverpoint s.cs iff (s.cs_v) {
      bins cells[] = {5'd0, 5'd1, 5'd2, 5'd3, 5'd4, 5'd5, 5'd7, 5'd8};
      illegal_bins match = {[5'd16 : 5'd24]};
    }
    x_rma_go_phase: coverpoint s.ph iff (s.ph_v) {
      bins sip_before_sense_idle = {3'b00_0};
      bins sip_after_sense_match = {3'b00_1};
      bins chiplet_before_sense_idle = {3'b01_0};
      bins chiplet_after_sense_match = {3'b01_1};
    }
    cp_independence: coverpoint s.ci iff (s.ci_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_hold_word_write: coverpoint s.hw iff (s.hw_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_go_idle_first: coverpoint s.gi iff (s.gi_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_retention: coverpoint s.rt iff (s.rt_v) {
      bins words_kept = {2'd0}; bins idle_before_sense = {2'd1}; bins match_after_sense = {2'd2};
    }
  endgroup

  typedef struct packed {
    logic [4:0] kc;
    logic kc_v;  // x_ch_kind_copy: channel * 6 + kind * 3 + copy
    logic [1:0] cf;
    logic cf_v;  // x_ch_common_flip: {sticky rose, 0 Match->Mismatch / 1 back}
    logic [3:0] fe;
    logic fe_v;  // x_ch_forced_err: {channel, sticky, interrupt}
    logic [2:0] rt;
    logic rt_v;  // x_ch_retry
    logic [1:0] nc;
    logic nc_v;  // cp_no_clear: channel
    logic [1:0] rc;
    logic rc_v;  // cp_reset_clear: channel
    logic so;
    logic so_v;  // cp_secdis_off_under_fault
    logic [2:0] lf;
    logic lf_v;  // x_ch_latch_freeze: {0 RMA_CHIPLET / 1 SEC_DIS, released, bad}
    logic [2:0] il;
    logic il_v;  // cp_irq_line: {sticky channel, line differs from the OR}
  } ef_tf_t;

  covergroup sep_token_fault_cg with function sample (ef_tf_t s);
    option.per_instance = 1;
    option.name = "sep_token_fault_cg";
    // Kind 0 collapsed pair, 1 one copy dissents. The copy-0 collapsed cells
    // and the copy-0 RMA_SIP dissent cell are not declared.
    x_ch_kind_copy: coverpoint s.kc iff (s.kc_v) {
      bins rma_sip[] = {5'd1, 5'd2, 5'd4, 5'd5};
      bins rma_chiplet[] = {5'd7, 5'd8, 5'd9, 5'd10, 5'd11};
      bins sec_dis[] = {5'd13, 5'd14, 5'd15, 5'd16, 5'd17};
    }
    // RMA_CHIPLET only: a unanimous legal flip with no go raises no sticky bit.
    x_ch_common_flip: coverpoint s.cf iff (s.cf_v) {
      bins match_to_mismatch = {2'b0_0};
      bins mismatch_to_match = {2'b0_1};
      illegal_bins sticky_rose = {2'b1_0, 2'b1_1};
    }
    x_ch_forced_err: coverpoint s.fe iff (s.fe_v) {
      bins rma_sip = {4'b00_1_1};
      bins rma_chiplet = {4'b01_1_1};
      bins sec_dis = {4'b10_1_1};
      wildcard illegal_bins error_without_sticky = {4'b??_0_?};
    }
    // 0 RMA_SIP Match, 1 RMA_SIP Mismatch, 2 RMA_CHIPLET Match, 3 RMA_CHIPLET
    // Mismatch, 4 SEC_DIS Match. (SEC_DIS, Mismatch) is not declared.
    x_ch_retry: coverpoint s.rt iff (s.rt_v) {
      bins cells[] = {[3'd0 : 3'd4]};
    }
    cp_no_clear: coverpoint s.nc iff (s.nc_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_reset_clear: coverpoint s.rc iff (s.rc_v) {bins channel[] = {[2'd0 : 2'd2]};}
    cp_secdis_off_under_fault: coverpoint s.so iff (s.so_v) {bins sec_dis_low = {1'b1};}
    // Under the freeze the sticky digest and valid bit keep their values;
    // after the release the digest is replaced. The RMA_SIP cells and the
    // result code under the freeze are not declared.
    x_ch_latch_freeze: coverpoint s.lf iff (s.lf_v) {
      bins chiplet_frozen_kept = {3'b0_0_0};
      bins chiplet_released_replaced = {3'b0_1_0};
      bins sec_dis_frozen_kept = {3'b1_0_0};
      bins sec_dis_released_replaced = {3'b1_1_0};
      illegal_bins changed_under_freeze = {3'b0_0_1, 3'b1_0_1};
    }
    // Single-channel sticky values 001, 010, 100. Multi-channel values are
    // not declared.
    cp_irq_line: coverpoint s.il iff (s.il_v) {
      bins sip_only = {3'b00_0};
      bins chiplet_only = {3'b01_0};
      bins sec_dis_only = {3'b10_0};
      illegal_bins line_differs = {3'b00_1, 3'b01_1, 3'b10_1};
    }
  endgroup

  typedef struct packed {
    logic [1:0] mp;
    logic mp_v;  // cp_match_phase: 0 before, 1 during, 2 after sense
    logic [2:0] vo;
    logic vo_v;  // x_verdict_out: {0 Match / 1 Mismatch / 2 Error, sec_dis_i}
    logic [4:0] df;
    logic df_v;  // x_state_demote_forced: {bad, cell}
  } ef_act_t;

  covergroup sep_sec_dis_activation_cg with function sample (ef_act_t s);
    option.per_instance = 1;
    option.name = "sep_sec_dis_activation_cg";
    cp_match_phase: coverpoint s.mp iff (s.mp_v) {
      bins before_sense = {2'd0}; bins during_sense = {2'd1}; bins after_sense = {2'd2};
    }
    x_verdict_out: coverpoint s.vo iff (s.vo_v) {
      bins match_on = {3'b00_1};
      bins mismatch_off = {3'b01_0};
      bins error_off = {3'b10_0};
      illegal_bins wrong_output = {3'b00_0, 3'b01_1, 3'b10_1};
    }
    // Cells 0-3 TEST_DEV x {00, 10, 01, 11}, 4-7 PROD x the same, 8
    // PROD_END, 9 RMA_SIP, 10 INVALID. The RMA_CHIPLET cell is not declared.
    x_state_demote_forced: coverpoint s.df iff (s.df_v) {
      bins cells[] = {[5'd0 : 5'd10]}; illegal_bins feat_not_all_ones = {[5'd16 : 5'd26]};
    }
  endgroup

  typedef struct packed {
    logic [2:0] dr;
    logic dr_v;  // x_digest_replay: {channel, Match}
    logic ss;
    logic ss_v;  // cp_stops_sense: 0 match during sense, 1 before sense
    logic [2:0] sf;
    logic sf_v;  // x_state_strap_feat: state * 2 + strap
    logic rv;
    logic rv_v;  // cp_reset_values_hold
  } ef_rob_t;

  covergroup sep_sec_dis_robustness_cg with function sample (ef_rob_t s);
    option.per_instance = 1;
    option.name = "sep_sec_dis_robustness_cg";
    x_digest_replay: coverpoint s.dr iff (s.dr_v) {
      bins rma_sip_mismatch = {3'b00_0};
      bins rma_chiplet_mismatch = {3'b01_0};
      bins sec_dis_mismatch = {3'b10_0};
      illegal_bins match = {3'b00_1, 3'b01_1, 3'b10_1};
    }
    cp_stops_sense: coverpoint s.ss iff (s.ss_v) {
      bins match_during_sense = {1'b0}; bins match_before_sense = {1'b1};
    }
    // State 0 TEST_DEV, 1 PROD, 2 RMA_SIP.
    x_state_strap_feat: coverpoint s.sf iff (s.sf_v) {
      bins cells[] = {[3'd0 : 3'd5]};
    }
    // The LC_STATE word is excluded.
    cp_reset_values_hold: coverpoint s.rv iff (s.rv_v) {
      bins shadow_at_reset_values = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [2:0] ca;
    logic ca_v;  // cp_case
    logic [3:0] fl;
    logic fl_v;  // cp_flags: {read_status, read_addr, program_addr, req}
    logic [6:0] cf;
    logic cf_v;  // x_case_flags: {case, flags}
    logic [2:0] cc;
    logic cc_v;  // x_case_cmd: {cell, forbidden command seen}
    logic [1:0] fc;
    logic fc_v;  // cp_flag_clear
    logic ss;
    logic ss_v;  // cp_sense_status_word
    logic [1:0] pl;
    logic pl_v;  // x_prog_lifecycle: {0 withheld / 1 released, bad}
    logic at;
    logic at_v;  // cp_accepted_twin: 0 read, 1 program
  } ef_ifs_t;

  covergroup sep_efuse_if_status_cg with function sample (ef_ifs_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_if_status_cg";
    cp_case: coverpoint s.ca iff (s.ca_v) {
      bins pre_sense_prog = {3'd0};
      bins read_no_enable = {3'd1};
      bins read_oob = {3'd2};
      bins prog_oob = {3'd3};
      bins prog_wlocked = {3'd4};
      bins read_rlocked = {3'd5};
      bins both_enables = {3'd6};
      bins prog_data0 = {3'd7};
    }
    // Sampled for read_no_enable, read_oob, prog_oob, prog_wlocked and the
    // accepted twins.
    cp_flags: coverpoint s.fl iff (s.fl_v) {
      bins f0000 = {4'b0000};
      bins f1000 = {4'b1000};
      bins f1100 = {4'b1100};
      bins f0010 = {4'b0010};
      bins f0001 = {4'b0001};
      illegal_bins other = {4'b0011, [4'b0100 : 4'b0111], [4'b1001 : 4'b1011], [4'b1101 : 4'b1111]};
    }
    // read_rlocked grades req_error only. The RDL does not state the flags of
    // pre_sense_prog, both_enables and prog_data0.
    x_case_flags: coverpoint s.cf iff (s.cf_v) {
      bins read_no_enable_1000 = {7'b001_1000};
      bins read_oob_1100 = {7'b010_1100};
      bins prog_oob_0010 = {7'b011_0010};
      bins prog_wlocked_0001 = {7'b100_0001};
      wildcard bins read_rlocked_req = {7'b101_???1};
      illegal_bins wrong_flags = {
        [7'b001_0000 : 7'b001_0111], [7'b001_1001 : 7'b001_1111],
        [7'b010_0000 : 7'b010_1011], [7'b010_1101 : 7'b010_1111],
        [7'b011_0000 : 7'b011_0001], [7'b011_0011 : 7'b011_1111],
        7'b100_0000, [7'b100_0010 : 7'b100_1111]
      };
      wildcard illegal_bins read_rlocked_no_req = {7'b101_???0};
      ignore_bins flags_not_stated = {[7'b000_0000 : 7'b000_1111], [7'b110_0000 : 7'b111_1111]};
    }
    // Cell 0 pre_sense_prog with no program command, 1 read_rlocked and 2
    // both_enables with no read command.
    x_case_cmd: coverpoint s.cc iff (s.cc_v) {
      bins pre_sense_prog_no_program = {3'b00_0};
      bins read_rlocked_no_read = {3'b01_0};
      bins both_enables_no_read = {3'b10_0};
      illegal_bins forbidden_command = {3'b00_1, 3'b01_1, 3'b10_1};
    }
    cp_flag_clear: coverpoint s.fc iff (s.fc_v) {
      bins read_addr_error = {2'd0}; bins program_addr_error = {2'd1}; bins req_error = {2'd2};
    }
    // Words 0 to 9 and 255 are not declared.
    cp_sense_status_word: coverpoint s.ss iff (s.ss_v) {
      bins word_10_to_254 = {1'b1};
    }
    // The outcome with the program timeout enabled is not a bin.
    x_prog_lifecycle: coverpoint s.pl iff (s.pl_v) {
      bins withheld = {2'b0_0};
      bins released = {2'b1_0};
      illegal_bins wrong_status = {2'b0_1, 2'b1_1};
    }
    cp_accepted_twin: coverpoint s.at iff (s.at_v) {
      bins valid_read = {1'b0}; bins landed_program = {1'b1};
    }
  endgroup

  typedef struct packed {
    logic [4:0] pb;
    logic pb_v;  // x_prog_block: {bad, class * 2 + strap}
    logic [2:0] sp;
    logic sp_v;  // x_secret_probe: {field, nonzero}
    logic [1:0] sk;
    logic sk_v;  // x_secret_read_kept: field
  } ef_stm_t;

  covergroup sep_efuse_secure_tm_cg with function sample (ef_stm_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_secure_tm_cg";
    // Class 0 256-bit field, 1 32-bit field, 2 DIS bit, 3 LOCKS bit, 4 spare
    // word. Strap 0: the command reaches the shim; strap 1: none.
    x_prog_block: coverpoint s.pb iff (s.pb_v) {
      bins cells[] = {[5'd0 : 5'd9]}; illegal_bins wrong_outcome = {[5'd16 : 5'd25]};
    }
    // Field 0 CHIPLET_UID, 1 SIP_UID, 2 SYS_UID, 3 CLASS_KEY, at strap 1.
    x_secret_probe: coverpoint s.sp iff (s.sp_v) {
      bins chiplet_uid_zero = {3'b00_0};
      bins sip_uid_zero = {3'b01_0};
      bins sys_uid_zero = {3'b10_0};
      bins class_key_zero = {3'b11_0};
      illegal_bins nonzero = {3'b00_1, 3'b01_1, 3'b10_1, 3'b11_1};
    }
    x_secret_read_kept: coverpoint s.sk iff (s.sk_v) {
      bins chiplet_uid = {2'd0};
      bins sip_uid = {2'd1};
      bins sys_uid = {2'd2};
      bins class_key = {2'd3};
    }
  endgroup

  typedef struct packed {
    logic [1:0] st;
    logic st_v;  // cp_state: 0 PROD, 1 RMA_SIP, 2 integrity error
    logic [2:0] cl;
    logic cl_v;  // cp_class
    logic rp;
    logic rp_v;  // cp_resp: 0 OKAY, 1 not OKAY
    logic [5:0] so;
    logic so_v;  // x_state_class_op: {bad, state * 8 + class-op}
    logic gi;
    logic gi_v;  // cp_gate_independent_of_feat: 0 PROD, 1 RMA_SIP
  } ef_jtg_t;

  covergroup sep_efuse_jtag_policy_cg with function sample (ef_jtg_t s);
    option.per_instance = 1;
    option.name = "sep_efuse_jtag_policy_cg";
    cp_state: coverpoint s.st iff (s.st_v) {
      bins prod = {2'd0}; bins rma_sip = {2'd1}; bins integrity_error = {2'd2};
    }
    // TOKEN_MATCH_FAULT is not declared.
    cp_class: coverpoint s.cl iff (s.cl_v) {
      bins shadow_word = {3'd0};
      bins ctrl_reg = {3'd1};
      bins token_word = {3'd2};
      bins token_eop = {3'd3};
      bins match_reg = {3'd4};
    }
    cp_resp: coverpoint s.rp iff (s.rp_v) {bins okay = {1'b0}; bins not_okay = {1'b1};}
    // Class-op 0 token word read, 1 token word write, 2 TOKEN_EOP write,
    // 3 match read (allowed, OKAY); 4 shadow read, 5 shadow write, 6 control
    // read, 7 control write (denied, not OKAY). (PROD, token word read) and
    // (PROD, token word write) are ignored.
    x_state_class_op: coverpoint s.so iff (s.so_v) {
      bins cells[] = {[6'd2 : 6'd23]};
      ignore_bins prod_token_word = {6'd0, 6'd1, 6'd32, 6'd33};
      illegal_bins wrong_response = {[6'd34 : 6'd55]};
    }
    cp_gate_independent_of_feat: coverpoint s.gi iff (s.gi_v) {
      bins prod = {1'b0}; bins rma_sip = {1'b1};
    }
  endgroup

  sep_efuse_map_geometry_cg       u_sep_efuse_map_geometry_cg       = new();
  sep_efuse_field_value_cg        u_sep_efuse_field_value_cg        = new();
  sep_lc_feat_ctrl_profile_cg     u_sep_lc_feat_ctrl_profile_cg     = new();
  sep_lc_feature_bit_semantics_cg u_sep_lc_feature_bit_semantics_cg = new();
  sep_dtp_gating_ladder_cg        u_sep_dtp_gating_ladder_cg        = new();
  sep_lc_sigint_failclosed_cg     u_sep_lc_sigint_failclosed_cg     = new();
  sep_lc_illegal_transition_cg    u_sep_lc_illegal_transition_cg    = new();
  sep_efuse_lock_policy_cg        u_sep_efuse_lock_policy_cg        = new();
  sep_lc_demotion_cg              u_sep_lc_demotion_cg              = new();
  sep_lc_demote_lock_cg           u_sep_lc_demote_lock_cg           = new();
  sep_token_channel_cg            u_sep_token_channel_cg            = new();
  sep_token_fault_cg              u_sep_token_fault_cg              = new();
  sep_sec_dis_activation_cg       u_sep_sec_dis_activation_cg       = new();
  sep_sec_dis_robustness_cg       u_sep_sec_dis_robustness_cg       = new();
  sep_efuse_if_status_cg          u_sep_efuse_if_status_cg          = new();
  sep_efuse_secure_tm_cg          u_sep_efuse_secure_tm_cg          = new();
  sep_efuse_jtag_policy_cg        u_sep_efuse_jtag_policy_cg        = new();

  // ---------------------------------------------------------------------
  // Common levels, decodes and snapshots.
  // ---------------------------------------------------------------------
  wire ef_live = !in_reset && !skip_fuse_sense_q;
  wire ef_sensed = ef_live && (fuse_sense_done_i === 1'b1);
  wire ef_sd = (sec_dis_i === 1'b1);
  wire ef_sig = (lc_sigint_i === 1'b1);
  wire [2:0] ef_lc = ef_cls(efuse_lc_raw_i);
  wire ef_d1 = (demote_1_i == 2'b01);
  wire ef_d2 = (demote_2_i == 2'b01);
  wire [1:0] ef_dm = {ef_d1, ef_d2};
  wire [63:0] ef_locks = efuse_shadow_i[32*EfWLocks+:64];
  wire [31:0] ef_locks_sp = efuse_shadow_i[32*EfWLocksSp+:32];
  wire [31:0] ef_lc_word = efuse_shadow_i[32*EfWLc+:32];
  wire [63:0] ef_sip_dis = efuse_shadow_i[32*EfWSipDis+:64];
  wire [63:0] ef_sys_dis = efuse_shadow_i[32*EfWSysDis+:64];
  wire ef_trans_en = efuse_shadow_i[32*EfWTrans];
  // Assigned lock bits: LOCKS [63:0] and LOCKS_SPARE [17:0] (sep_efuse_map.adoc).
  wire ef_all_locked = (ef_locks == '1) && (ef_locks_sp[17:0] == '1);

  function automatic logic ef_wlock(input logic [5:0] s);
    if (s < 6'd32) return ef_locks[2*s];
    if (s < 6'(EfSlots)) return ef_locks_sp[2*(s-6'd32)];
    return 1'b0;
  endfunction
  function automatic logic ef_rlock(input logic [5:0] s);
    if (s < 6'd32) return ef_locks[2*s+1];
    if (s < 6'(EfSlots)) return ef_locks_sp[2*(s-6'd32)+1];
    return 1'b0;
  endfunction
  function automatic logic [31:0] ef_word(input logic [9:0] byte_off);
    return efuse_shadow_i[32*byte_off[9:2]+:32];
  endfunction
  function automatic logic ef_field_nz(input logic [5:0] s);
    for (int w = int'(EfSlotOff[s][10:2]); w < int'(EfSlotOff[s+1][10:2]); w++) begin
      if (efuse_shadow_i[32*w+:32] != 32'h0) return 1'b1;
    end
    return 1'b0;
  endfunction

  // Post-guard shim command (READ 2'b00, PROGRAM 2'b01, PROGRAM_READ_BACK
  // 2'b10, interface.adoc Fuse Command Protocol) and response.
  wire ef_cmd_v = (shim_cmd_i.valid === 1'b1);
  wire ef_cmd_rd = ef_cmd_v && (shim_cmd_i.command == efuse_pkg::FUSE_COMMAND_READ);
  wire ef_cmd_pg = ef_cmd_v && (shim_cmd_i.command == efuse_pkg::FUSE_COMMAND_PROGRAM);
  wire [12:0] ef_cmd_addr = 13'(shim_cmd_i.address);
  wire ef_resp_v = (shim_resp_i.valid === 1'b1);

  // Frontdoor completions with any response (rd_okay and wr_okay are OKAY
  // only). One outstanding single-beat transaction, as for the Phase 1 bins.
  wire ef_wr_cmpl = !in_reset && b_hs && (aw_out_q == 4'd1) && (w_beats_q == 2'd1);
  wire ef_rd_cmpl = rd_cmpl;
  wire [2:0] ef_wr_win = ef_win(aw_addr_q);
  wire [2:0] ef_rd_win = ef_win(ar_addr_q);

  // State at the AW handshake of each write, before the write takes effect.
  logic [EfFuseBits-1:0] ef_aw_shadow = '0;
  logic [63:0] ef_aw_feat = '0;
  logic [1:0] ef_aw_d1 = 2'b10, ef_aw_d2 = 2'b10;
  logic ef_aw_l1 = 1'b0, ef_aw_l2 = 1'b0;
  logic [2:0] ef_aw_fault = '0;
  logic [2:0] ef_aw_flags = '0;  // {read_addr, program_addr, req} errors
  logic ef_aw_pcmd_v = 1'b0;  // a PROGRAM command reached the shim since the AW
  logic [12:0] ef_aw_pcmd_addr = '0;
  always @(posedge clk_i) begin
    if (aw_hs) begin
      ef_aw_shadow <= efuse_shadow_i;
      ef_aw_feat <= feat_ctrl_i;
      ef_aw_d1 <= demote_1_i;
      ef_aw_d2 <= demote_2_i;
      ef_aw_l1 <= (demote_lock_1_i === 1'b1);
      ef_aw_l2 <= (demote_lock_2_i === 1'b1);
      ef_aw_fault <= tok_fault_i;
      ef_aw_flags <= {rd_addr_err_i === 1'b1, pg_addr_err_i === 1'b1, req_err_i === 1'b1};
      ef_aw_pcmd_v <= ef_cmd_pg;
      ef_aw_pcmd_addr <= ef_cmd_addr;
    end else if (ef_cmd_pg) begin
      ef_aw_pcmd_v <= 1'b1;
      ef_aw_pcmd_addr <= ef_cmd_addr;
    end
  end

  // Program and read enables, as the last frontdoor write left them.
  logic ef_pen_q = 1'b0;
  logic ef_pg_tmo_en_q = 1'b0;
  always @(posedge clk_i) begin
    if (in_reset) begin
      ef_pen_q <= 1'b0;
      ef_pg_tmo_en_q <= 1'b0;
    end else if (wr_okay && (aw_addr_q == EfPgCtrl)) begin
      ef_pen_q <= |(wr_data & EfPgEnMask);
    end else if (wr_okay && (aw_addr_q == EfPgTmo)) begin
      ef_pg_tmo_en_q <= |(wr_data & EfPgTmoEnMask);
    end
  end

  // Sense-done rise and the first reset-release clock.
  logic ef_fuse_q = 1'b0;
  logic ef_rst_q = 1'b1;
  always @(posedge clk_i) begin
    ef_fuse_q <= (fuse_sense_done_i === 1'b1);
    ef_rst_q  <= in_reset;
  end
  wire ef_sense_rise = fuse_sense;  // rising edge, +skip_fuse_sense excluded
  wire ef_rel = ef_rst_q && !in_reset;
  wire ef_rst_fall = !ef_rst_q && in_reset;

  // Feature change: any change of the profile inputs, sampled once they have
  // been stable for EfFeatSettle clocks (the specification gives no decode
  // latency). The sense-done rise also starts a settle. ef_fs_* is the state
  // at the previous settled sample, for the points that compare two samples.
  localparam int unsigned EfFvW = 4 + 1 + 2 + 2 + 64 + 64 + 64 + 1;
  wire [EfFvW-1:0] ef_fv = {
    efuse_lc_raw_i, sec_dis_i, demote_1_i, demote_2_i, ef_sip_dis, ef_sys_dis, feat_ctrl_i,
    lc_sigint_i
  };
  logic [EfFvW-1:0] ef_fv_q = '0;
  logic ef_sensed_q = 1'b0;
  logic ef_fv_pend = 1'b0;
  int unsigned ef_fv_cnt = 0;
  wire ef_feat_ev = ef_sensed && ef_fv_pend && (ef_fv_cnt == EfFeatSettle) && (ef_fv === ef_fv_q);
  always @(posedge clk_i) begin
    ef_fv_q <= ef_fv;
    ef_sensed_q <= ef_sensed;
    if (!ef_sensed) begin
      ef_fv_pend <= 1'b0;
      ef_fv_cnt  <= 0;
    end else if ((ef_fv !== ef_fv_q) || !ef_sensed_q) begin
      ef_fv_pend <= 1'b1;
      ef_fv_cnt  <= 0;
    end else if (ef_fv_pend) begin
      if (ef_fv_cnt == EfFeatSettle) ef_fv_pend <= 1'b0;
      else ef_fv_cnt <= ef_fv_cnt + 1;
    end
  end
  logic ef_fs_v = 1'b0;
  logic [2:0] ef_fs_lc = '0;
  logic ef_fs_sd = 1'b0, ef_fs_sig = 1'b0;
  logic [1:0] ef_fs_d1 = 2'b10, ef_fs_d2 = 2'b10;
  logic [63:0] ef_fs_feat = '0, ef_fs_sip = '0, ef_fs_sys = '0;
  logic [31:0] ef_fs_lcw = '0;
  logic [3:0] ef_fs_raw = '0;
  always @(posedge clk_i) begin
    if (!ef_sensed) begin
      ef_fs_v <= 1'b0;
    end else if (ef_feat_ev) begin
      ef_fs_v    <= 1'b1;
      ef_fs_lc   <= ef_lc;
      ef_fs_raw  <= efuse_lc_raw_i;
      ef_fs_sd   <= ef_sd;
      ef_fs_sig  <= ef_sig;
      ef_fs_d1   <= demote_1_i;
      ef_fs_d2   <= demote_2_i;
      ef_fs_feat <= feat_ctrl_i;
      ef_fs_sip  <= ef_sip_dis;
      ef_fs_sys  <= ef_sys_dis;
      ef_fs_lcw  <= ef_lc_word;
    end
  end

  // Token change: a change of a status code, SEC_DIS, a sticky bit, the
  // interrupt line or a go pulse, sampled once they have been stable for
  // EfTokSettle clocks (N), so a cell that compares two of them samples at a
  // settled point. ef_ts_* holds the previous settled sample.
  localparam int unsigned EfTvW = 6 + 6 + 6 + 1 + 3 + 1 + 3;
  wire ef_irq = (irq_token_fault_i === 1'b1);
  wire [EfTvW-1:0] ef_tv = {
    tok_sip_i, tok_chp_i, tok_sdis_i, sec_dis_i, tok_fault_i, irq_token_fault_i, token_go_i
  };
  logic [EfTvW-1:0] ef_tv_q = '0;
  logic ef_tv_pend = 1'b0;
  int unsigned ef_tv_cnt = 0;
  wire ef_tok_ev = ef_live && ef_tv_pend && (ef_tv_cnt == EfTokSettle) && (ef_tv === ef_tv_q);
  always @(posedge clk_i) begin
    ef_tv_q <= ef_tv;
    if (!ef_live) begin
      ef_tv_pend <= 1'b0;
      ef_tv_cnt  <= 0;
    end else if (ef_tv !== ef_tv_q) begin
      ef_tv_pend <= 1'b1;
      ef_tv_cnt  <= 0;
    end else if (ef_tv_pend) begin
      if (ef_tv_cnt == EfTokSettle) ef_tv_pend <= 1'b0;
      else ef_tv_cnt <= ef_tv_cnt + 1;
    end
  end
  wire [2:0][5:0] ef_code = {tok_sdis_i, tok_chp_i, tok_sip_i};
  logic ef_ts_v = 1'b0;
  logic [2:0][5:0] ef_ts_code = '0;
  logic [2:0] ef_ts_fault = '0;
  always @(posedge clk_i) begin
    if (!ef_live) ef_ts_v <= 1'b0;
    else if (ef_tok_ev) begin
      ef_ts_v     <= 1'b1;
      ef_ts_code  <= ef_code;
      ef_ts_fault <= tok_fault_i;
    end
  end

  // One-point sample helpers.
  task automatic ef_geo(input int unsigned which, input logic [5:0] v);
    ef_geo_t e;
    e = '0;
    case (which)
      0: begin
        e.wn = v[2:0];
        e.wn_v = 1'b1;
      end
      1: begin
        e.rz = v[0];
        e.rz_v = 1'b1;
      end
      2: begin
        e.wr = v;
        e.wr_v = 1'b1;
      end
      3: begin
        e.sf = v[3:0];
        e.sf_v = 1'b1;
      end
      4: begin
        e.ea = v[1:0];
        e.ea_v = 1'b1;
      end
      5: begin
        e.cr = v[3:0];
        e.cr_v = 1'b1;
      end
      6: begin
        e.tb = v[3:0];
        e.tb_v = 1'b1;
      end
      default: begin
        e.ji = v[0];
        e.ji_v = 1'b1;
      end
    endcase
    u_sep_efuse_map_geometry_cg.sample(e);
  endtask

  task automatic ef_lk(input int unsigned which, input logic [7:0] v);
    ef_lock_t e;
    e = '0;
    case (which)
      0: begin
        e.sp = v;
        e.sp_v = 1'b1;
      end
      1: begin
        e.sr = v;
        e.sr_v = 1'b1;
      end
      2: begin
        e.ko = v[3:0];
        e.ko_v = 1'b1;
      end
      3: begin
        e.nf = v[1:0];
        e.nf_v = 1'b1;
      end
      4: begin
        e.ex = v[1:0];
        e.ex_v = 1'b1;
      end
      5: begin
        e.sl = v[0];
        e.sl_v = 1'b1;
      end
      6: begin
        e.sw = v[3:0];
        e.sw_v = 1'b1;
      end
      7: begin
        e.lo = v[1:0];
        e.lo_v = 1'b1;
      end
      8: begin
        e.pv = v[0];
        e.pv_v = 1'b1;
      end
      9: begin
        e.rc = v[2:0];
        e.rc_v = 1'b1;
      end
      default: begin
        e.lp = v[2:0];
        e.lp_v = 1'b1;
      end
    endcase
    u_sep_efuse_lock_policy_cg.sample(e);
  endtask

  task automatic ef_tc(input int unsigned which, input logic [5:0] v);
    ef_tch_t e;
    e = '0;
    case (which)
      0: begin
        e.cv = v[2:0];
        e.cv_v = 1'b1;
      end
      1: begin
        e.cd = v;
        e.cd_v = 1'b1;
      end
      2: begin
        e.cs = v[4:0];
        e.cs_v = 1'b1;
      end
      3: begin
        e.ph = v[2:0];
        e.ph_v = 1'b1;
      end
      4: begin
        e.ci = v[1:0];
        e.ci_v = 1'b1;
      end
      5: begin
        e.hw = v[1:0];
        e.hw_v = 1'b1;
      end
      6: begin
        e.gi = v[1:0];
        e.gi_v = 1'b1;
      end
      default: begin
        e.rt = v[1:0];
        e.rt_v = 1'b1;
      end
    endcase
    u_sep_token_channel_cg.sample(e);
  endtask

  task automatic ef_tfs(input int unsigned which, input logic [4:0] v);
    ef_tf_t e;
    e = '0;
    case (which)
      0: begin
        e.kc = v;
        e.kc_v = 1'b1;
      end
      1: begin
        e.cf = v[1:0];
        e.cf_v = 1'b1;
      end
      2: begin
        e.fe = v[3:0];
        e.fe_v = 1'b1;
      end
      3: begin
        e.rt = v[2:0];
        e.rt_v = 1'b1;
      end
      4: begin
        e.nc = v[1:0];
        e.nc_v = 1'b1;
      end
      5: begin
        e.rc = v[1:0];
        e.rc_v = 1'b1;
      end
      6: begin
        e.so = v[0];
        e.so_v = 1'b1;
      end
      7: begin
        e.lf = v[2:0];
        e.lf_v = 1'b1;
      end
      default: begin
        e.il = v[2:0];
        e.il_v = 1'b1;
      end
    endcase
    u_sep_token_fault_cg.sample(e);
  endtask

  task automatic ef_ifs(input int unsigned which, input logic [6:0] v);
    ef_ifs_t e;
    e = '0;
    case (which)
      0: begin
        e.ca = v[2:0];
        e.ca_v = 1'b1;
      end
      1: begin
        e.fl = v[3:0];
        e.fl_v = 1'b1;
      end
      2: begin
        e.cf = v;
        e.cf_v = 1'b1;
      end
      3: begin
        e.cc = v[2:0];
        e.cc_v = 1'b1;
      end
      4: begin
        e.fc = v[1:0];
        e.fc_v = 1'b1;
      end
      5: begin
        e.ss = v[0];
        e.ss_v = 1'b1;
      end
      6: begin
        e.pl = v[1:0];
        e.pl_v = 1'b1;
      end
      default: begin
        e.at = v[0];
        e.at_v = 1'b1;
      end
    endcase
    u_sep_efuse_if_status_cg.sample(e);
  endtask

  task automatic ef_act(input int unsigned which, input logic [4:0] v);
    ef_act_t e;
    e = '0;
    case (which)
      0: begin
        e.mp = v[1:0];
        e.mp_v = 1'b1;
      end
      1: begin
        e.vo = v[2:0];
        e.vo_v = 1'b1;
      end
      default: begin
        e.df = v;
        e.df_v = 1'b1;
      end
    endcase
    u_sep_sec_dis_activation_cg.sample(e);
  endtask

  task automatic ef_rob(input int unsigned which, input logic [2:0] v);
    ef_rob_t e;
    e = '0;
    case (which)
      0: begin
        e.dr = v;
        e.dr_v = 1'b1;
      end
      1: begin
        e.ss = v[0];
        e.ss_v = 1'b1;
      end
      2: begin
        e.sf = v;
        e.sf_v = 1'b1;
      end
      default: begin
        e.rv = v[0];
        e.rv_v = 1'b1;
      end
    endcase
    u_sep_sec_dis_robustness_cg.sample(e);
  endtask

  // ---------------------------------------------------------------------
  // sep_efuse_map_geometry_cg: frontdoor completions in 0x1093_0000 to
  // 0x1093_FFFF, and the JTAG ID at sense done.
  // ---------------------------------------------------------------------
  task automatic ef_geo_access(input logic [31:0] a, input logic wr, input logic ok,
                               input logic [2:0] size);
    logic [2:0] w;
    logic [10:0] off;
    logic ign;
    w   = ef_win(a);
    off = 11'(a - EfMapBase);
    if (ef_own_win) begin
      ef_geo(0, 6'(w));
      if (w == EfWRsvd) ef_geo(1, 6'(a >= EfRsvdHigh));
      if ((fuse_sense_done_i === 1'b1) && (w inside {EfWShadow, EfWCtrlIn, EfWTokIn})) begin
        ign = ((w == EfWShadow) && wr) || ((w == EfWShadow) && !wr && ef_rlock(ef_slot_of(off))) ||
            (wr && (a == EfStatus)) || (wr && (a inside {EfPgData, EfRdData, EfMatchSip,
                                                         EfMatchChip, EfMatchSec, EfMatchFault})) ||
            (!wr && (a == EfTokEop));
        ef_geo(2, {ign, w, wr, ok});
      end
      if (a == EfMapEnd - 32'd4) ef_geo(4, 6'd0);
      if (a == EfCtrlEnd - 32'd4) ef_geo(4, 6'd1);
      if (a == EfCtrlEnd) ef_geo(4, 6'd2);
      if (a == EfRsvdBase) ef_geo(4, 6'd3);
      case (a)
        EfStatus: ef_geo(5, wr ? 6'd1 : 6'd0);
        EfPgCtrl: ef_geo(5, wr ? 6'd3 : 6'd2);
        EfRdCtrl: ef_geo(5, wr ? 6'd5 : 6'd4);
        EfRdTmo: if (!wr) ef_geo(5, 6'd6);
        EfPgTmo: if (!wr) ef_geo(5, 6'd7);
        EfPgData: if (!wr) ef_geo(5, 6'd8);
        EfRdData: if (!wr) ef_geo(5, 6'd9);
        default: ;
      endcase
      if (in_win(a, EfTokSip, EfTokChip)) ef_geo(6, wr ? 6'd1 : 6'd0);
      if (in_win(a, EfTokChip, EfTokSec)) ef_geo(6, wr ? 6'd3 : 6'd2);
      if (in_win(a, EfTokSec, EfTokEop)) ef_geo(6, wr ? 6'd5 : 6'd4);
    end
    if (ef_own_tch) begin
      if (!wr && (a == EfMatchSip)) ef_geo(6, 6'd6);
      if (!wr && (a == EfMatchChip)) ef_geo(6, 6'd7);
      if (!wr && (a == EfMatchSec)) ef_geo(6, 6'd8);
      if (wr && (a == EfTokEop)) ef_geo(6, 6'd9);
    end
    // The used-bit leg reads each narrow register with a 32-bit OKAY read.
    if (ef_own_fld && !wr && ok && (size == 3'd2) && (fuse_sense_done_i === 1'b1)) begin
      case (a)
        SEP_EFUSE_MAP_LC_STATE_REG_ADDR: ef_geo(3, 6'd0);
        SEP_EFUSE_MAP_SBOOT_DIS_REG_ADDR: ef_geo(3, 6'd1);
        SEP_EFUSE_MAP_TRANSIENT_RMA_EN_REG_ADDR: ef_geo(3, 6'd2);
        SEP_EFUSE_MAP_CHIPLET_PUBK_REVOKE_REG_ADDR: ef_geo(3, 6'd3);
        SEP_EFUSE_MAP_STATUS_RPT_REG_ADDR: ef_geo(3, 6'd4);
        SEP_EFUSE_MAP_ROM_CTL_REG_ADDR: ef_geo(3, 6'd5);
        SEP_EFUSE_MAP_SYSCLK_FREQ_MHZ_REG_ADDR: ef_geo(3, 6'd6);
        SEP_EFUSE_MAP_REQUIRED_SIGNERS_REG_ADDR: ef_geo(3, 6'd7);
        SEP_EFUSE_MAP_REQUIRED_ALGS_REG_ADDR: ef_geo(3, 6'd8);
        default: ;
      endcase
    end
  endtask

  always @(posedge clk_i) begin
    if (ef_wr_cmpl && (ef_wr_win != EfWNone)) begin
      ef_geo_access(aw_addr_q, 1'b1, lsu_b_resp_i == AxiOkay, aw_size_q);
    end
    if (ef_rd_cmpl && (ef_rd_win != EfWNone)) begin
      ef_geo_access(ar_addr_q, 1'b0, lsu_r_resp_i == AxiOkay, ar_size_q);
    end
    if (ef_sense_rise && ef_own_fld && (jtag_id_i !== '0) && !$isunknown(jtag_id_i)) begin
      ef_geo(7, 6'd1);
    end
  end

  // ---------------------------------------------------------------------
  // sep_efuse_field_value_cg: narrow fields at sense done; x_version_bit
  // from the new set bit of BL1_VERSION or BL2_VERSION at the first sense
  // done after a program. The previous sensed copy survives the cold reset
  // between the program and the resense.
  // ---------------------------------------------------------------------
  logic [511:0] ef_vb_prev = '0;
  logic ef_vb_pv = 1'b0;
  logic ef_vb_prog = 1'b0;
  function automatic logic [1:0] ef_bitcls(input logic [255:0] v);
    for (int i = 0; i < 256; i++) begin
      if (v[i]) return (i == 0) ? 2'd0 : (i == 255) ? 2'd2 : 2'd1;
    end
    return 2'd0;
  endfunction
  always @(posedge clk_i) begin
    ef_fld_t e;
    logic [31:0] w;
    logic [4:0] sw;
    logic [10:0] clk;
    logic [511:0] cur, gain;
    if (ef_cmd_pg) ef_vb_prog <= 1'b1;
    if (ef_sense_rise) begin
      if (ef_own_fld) begin
        e = '0;
        e.sb = efuse_shadow_i[32*EfWSboot];
        e.sb_v = 1'b1;
        e.rs = efuse_shadow_i[32*EfWSigners+:2];
        e.rs_v = 1'b1;
        e.sr = efuse_shadow_i[32*EfWStatusRpt+:2];
        e.sr_v = 1'b1;
        w = efuse_shadow_i[32*EfWRevoke+:32];
        e.rv = (w == 32'h0) ? 2'd0 : ($countones(w) == 1) ? 2'd1 : (w == EfRevokeAll) ? 2'd2 : 2'd3;
        e.rv_v = 1'b1;
        clk = efuse_shadow_i[32*EfWSysclk+:11];
        e.sc = (clk == 11'd1) ? 2'd0 : (clk == 11'h7FF) ? 2'd2 : 2'd1;
        e.sc_v = (clk != 11'd0);
        w = efuse_shadow_i[32*EfWRomCtl+:32];
        e.rc = {1'b0, 2'b00, w[0]};
        e.rc_v = 1'b1;
        u_sep_efuse_field_value_cg.sample(e);
        sw = w[5:1];
        e = '0;
        e.rc = (sw == 5'd0) ? 4'b1_000 : (sw == 5'h1F) ? 4'b1_110 : 4'b1_111;
        for (int i = 0; i < 5; i++) begin
          if (sw == (5'd1 << i)) e.rc = {1'b1, 3'(i + 1)};
        end
        e.rc_v = 1'b1;
        u_sep_efuse_field_value_cg.sample(e);
        w = efuse_shadow_i[32*EfWAlgs+:32];
        for (int o = 0; o < 3; o++) begin
          e = '0;
          e.al = 4'(o * 4) + 4'(w[4*o+:2]);
          e.al_v = 1'b1;
          u_sep_efuse_field_value_cg.sample(e);
        end
      end
      cur = {efuse_shadow_i[32*EfWBl2+:256], efuse_shadow_i[32*EfWBl1+:256]};
      gain = cur & ~ef_vb_prev;
      if (ef_own_lock && ef_vb_pv && ef_vb_prog) begin
        if ($countones(gain[255:0]) == 1) begin
          e = '0;
          e.vb = 3'(ef_bitcls(gain[255:0]));
          e.vb_v = 1'b1;
          u_sep_efuse_field_value_cg.sample(e);
        end
        if ($countones(gain[511:256]) == 1) begin
          e = '0;
          e.vb = 3'd3 + 3'(ef_bitcls(gain[511:256]));
          e.vb_v = 1'b1;
          u_sep_efuse_field_value_cg.sample(e);
        end
      end
      ef_vb_prev <= cur;
      ef_vb_pv   <= 1'b1;
      ef_vb_prog <= 1'b0;
    end
  end

  // ---------------------------------------------------------------------
  // Feature-change points: sep_lc_feat_ctrl_profile_cg,
  // sep_lc_feature_bit_semantics_cg, sep_dtp_gating_ladder_cg,
  // x_sigint_state_secdis_out, the feature points of sep_lc_demotion_cg,
  // x_state_demote_forced and x_state_strap_feat.
  // ---------------------------------------------------------------------
  // Bits of x_closed_bit_owner (in that order) and the named feature bits
  // (lifecycle_controller.adoc, Disable Vector Format).
  localparam int unsigned EfClosedBit[11] = '{0, 1, 2, 3, 4, 23, 24, 25, 47, 48, 63};
  localparam int unsigned EfBitSepDbg = 0;
  localparam int unsigned EfBitChipDbg = 1;
  localparam int unsigned EfBitSepFuseDbg = 2;
  localparam int unsigned EfBitSmcFuseDbg = 3;
  localparam int unsigned EfBitSipDbg = 24;
  localparam int unsigned EfNamedBit[5] = '{
      EfBitSepDbg,
      EfBitChipDbg,
      EfBitSepFuseDbg,
      EfBitSmcFuseDbg,
      EfBitSipDbg
  };
  logic ef_dtp_ref_v = 1'b0;
  logic ef_dtp_ref_sep = 1'b0, ef_dtp_ref_smc = 1'b0;

  always @(posedge clk_i) begin
    ef_prof_t pe;
    ef_bit_t be;
    ef_dtp_t de;
    ef_sig_t se;
    ef_dem_t me;
    logic [4:0] row;
    logic [2:0] oc;
    logic [23:0] sg, yg, og, m;
    logic c1, c2, c3, ao, sep_p, smc_p, ref_sep, ref_smc, ref_v;
    logic [1:0] fs_dm;
    logic [2:0] chg;
    int unsigned b;
    if (ef_feat_ev) begin
      fs_dm = {ef_fs_d1 == 2'b01, ef_fs_d2 == 2'b01};
      if (ef_own_fc) begin
        // sep_lc_feat_ctrl_profile_cg. The row and class points need a state
        // code that passes the integrity check.
        row = ef_row(ef_lc, ef_sd, ef_dm);
        pe = '0;
        pe.sc = ef_lc;
        pe.sc_v = 1'b1;
        pe.pr = row;
        pe.pr_v = !ef_sig;
        pe.rd = (ef_lc == EfRc);
        pe.rd_v = (ef_lc inside {EfRs, EfRc}) && ((ef_sip_dis | ef_sys_dis) != 64'h0);
        u_sep_lc_feat_ctrl_profile_cg.sample(pe);
        for (int g = 0; g < 3; g++) begin
          m  = ef_gmask(g);
          sg = ef_grp(ef_sip_dis, g);
          yg = ef_grp(ef_sys_dis, g);
          og = sg | yg;
          pe = '0;
          pe.oc = {2'(g), og != 24'h0};
          pe.oc_v = (og != m);
          // Guard: SIP_DIS slice nonzero, SYS_DIS has a bit outside SIP_DIS,
          // OR neither zero nor all ones, so the four classes differ.
          if (!ef_sig && (sg != 24'h0) && ((yg & ~sg) != 24'h0) && (og != 24'h0) && (og != m)) begin
            oc = ef_obs_cls(feat_ctrl_i, ef_sip_dis, ef_sys_dis, g);
            pe.xr = {oc != ef_prof_cls(row, g), row, 2'(g), oc};
            pe.xr_v = 1'b1;
          end
          u_sep_lc_feat_ctrl_profile_cg.sample(pe);
        end

        // sep_lc_feature_bit_semantics_cg.
        for (int k = 0; k < 5; k++) begin
          be = '0;
          be.nb = {3'(k), feat_ctrl_i[EfNamedBit[k]]};
          be.nb_v = 1'b1;
          u_sep_lc_feature_bit_semantics_cg.sample(be);
        end
        if (ef_fs_v && (ef_fs_lc == ef_lc) && (ef_fs_sd == ef_sd) && (ef_fs_sig == ef_sig) &&
            (fs_dm == ef_dm)) begin
          for (int k = 0; k < 11; k++) begin
            b = EfClosedBit[k];
            if (ef_fs_feat[b] && !feat_ctrl_i[b] && !(ef_fs_sip[b] || ef_fs_sys[b]) &&
                (ef_sip_dis[b] || ef_sys_dis[b])) begin
              be = '0;
              be.cb = 5'(k * 2) + 5'(!(ef_sip_dis[b] && !ef_fs_sip[b]));
              be.cb_v = 1'b1;
              u_sep_lc_feature_bit_semantics_cg.sample(be);
            end
          end
        end
        if (ef_fs_v && (ef_fs_lc == ef_lc) && (ef_lc inside {EfTd, EfProd}) && (ef_fs_sd == ef_sd) &&
            (ef_fs_sig == ef_sig) && (ef_fs_sip == ef_sip_dis) && (ef_fs_sys == ef_sys_dis) &&
            (((fs_dm == 2'b00) && (ef_dm == 2'b10)) || ((fs_dm == 2'b00) && (ef_dm == 2'b01)) ||
             ((fs_dm == 2'b01) && (ef_dm == 2'b11)) || ((fs_dm == 2'b10) && (ef_dm == 2'b11)))) begin
          chg = {
            ef_grp(ef_fs_feat, 2) != ef_grp(feat_ctrl_i, 2),
            ef_grp(ef_fs_feat, 1) != ef_grp(feat_ctrl_i, 1),
            ef_grp(ef_fs_feat, 0) != ef_grp(feat_ctrl_i, 0)
          };
          be = '0;
          be.dg = {ef_d2 && (fs_dm[0] == 1'b0), ef_lc == EfProd, chg};
          be.dg_v = 1'b1;
          u_sep_lc_feature_bit_semantics_cg.sample(be);
        end

        // sep_dtp_gating_ladder_cg. The port value enters only as "same as"
        // or "other than" its value in the all-open cell of the leaf.
        c1 = feat_ctrl_i[EfBitSipDbg];
        c2 = c1 && feat_ctrl_i[EfBitChipDbg];
        c3 = c2 && feat_ctrl_i[EfBitSepDbg];
        sep_p = (sep_fuse_dft_disable_i === 1'b1);
        smc_p = (smc_fuse_dft_disable_i === 1'b1);
        ref_v = ef_dtp_ref_v;
        ref_sep = ef_dtp_ref_sep;
        ref_smc = ef_dtp_ref_smc;
        if (c3 && feat_ctrl_i[EfBitSepFuseDbg] && feat_ctrl_i[EfBitSmcFuseDbg]) begin
          ref_v = 1'b1;
          ref_sep = sep_p;
          ref_smc = smc_p;
          ef_dtp_ref_v <= 1'b1;
          ef_dtp_ref_sep <= sep_p;
          ef_dtp_ref_smc <= smc_p;
        end
        de = '0;
        de.sp = {c3, feat_ctrl_i[EfBitSepFuseDbg], sep_p != ref_sep};
        de.sp_v = ref_v;
        de.mp = {c2, feat_ctrl_i[EfBitSmcFuseDbg], smc_p != ref_smc};
        de.mp_v = ref_v;
        de.ns = c3 ? 2'd3 : c2 ? 2'd2 : 2'd1;
        de.ns_v = c1;
        u_sep_dtp_gating_ladder_cg.sample(de);

        // sep_lc_demotion_cg feature points.
        me = '0;
        me.sc = 5'(ef_lc * 4) + 5'(ef_dm);
        me.sc_v = 1'b1;
        me.ec = {1'b0, !(demote_1_i inside {2'b10, 2'b01})};
        me.ec_v = 1'b1;
        if (ef_fs_v && (fs_dm != ef_dm) && (ef_fs_raw == efuse_lc_raw_i) && (ef_fs_lcw == ef_lc_word)) begin
          me.oi = 5'(ef_lc * 4) + 5'(ef_dm);
          me.oi_v = 1'b1;
        end
        u_sep_lc_demotion_cg.sample(me);
        me = '0;
        me.ec = {1'b1, !(demote_2_i inside {2'b10, 2'b01})};
        me.ec_v = 1'b1;
        u_sep_lc_demotion_cg.sample(me);

        // x_state_demote_forced: cells 0-3 TEST_DEV and 4-7 PROD in the
        // order 00, 10, 01, 11 of {DEMOTE_1, DEMOTE_2}.
        if (ef_sd && (ef_lc != EfRc)) begin
          logic [3:0] dcell;
          case (ef_lc)
            EfTd: dcell = 4'(ef_dm == 2'b00 ? 0 : ef_dm == 2'b10 ? 1 : ef_dm == 2'b01 ? 2 : 3);
            EfProd: dcell = 4'(ef_dm == 2'b00 ? 4 : ef_dm == 2'b10 ? 5 : ef_dm == 2'b01 ? 6 : 7);
            EfPe: dcell = 4'd8;
            EfRs: dcell = 4'd9;
            default: dcell = 4'd10;
          endcase
          ef_act(2, {feat_ctrl_i != '1, dcell});
        end
        // x_state_strap_feat: sampled with sec_dis_i 0.
        if (!ef_sd && (ef_lc inside {EfTd, EfProd, EfRs})) begin
          ef_rob(2,
                 3'((ef_lc == EfTd ? 0 : ef_lc == EfProd ? 1 : 2) * 2) + 3'(secure_tm_i === 1'b1));
        end
      end

      // x_sigint_state_secdis_out: lc_sigint_i high, INVALID excluded.
      if (ef_own_cw && ef_sig && (ef_lc != EfInv)) begin
        oc = (feat_ctrl_i == 64'h0) ? 3'd0 : (feat_ctrl_i == '1) ? 3'd1 : 3'd2;
        se = '0;
        se.ss = {oc != {2'b00, ef_sd}, 4'(ef_lc * 2) + 4'(ef_sd)};
        se.ss_v = 1'b1;
        u_sep_lc_sigint_failclosed_cg.sample(se);
      end
    end
  end

  // x_raw16_sigint: a complementary state byte {~r, r} at sense done.
  always @(posedge clk_i) begin
    ef_sig_t se;
    if (ef_sense_rise && ef_own_fc && (ef_lc_word[7:4] == ~ef_lc_word[3:0])) begin
      se = '0;
      se.rs = {ef_sig, ef_lc_word[3:0]};
      se.rs_v = 1'b1;
      u_sep_lc_sigint_failclosed_cg.sample(se);
    end
  end

  // ---------------------------------------------------------------------
  // x_transient: a match code on RMA_SIP or RMA_CHIPLET, the old class at
  // the match rise, and the LC_STATE word outcome within EfTransWin clocks
  // (a sampler parameter no longer than the window W of the owning test).
  // ---------------------------------------------------------------------
  logic ef_tr_arm = 1'b0;
  logic ef_tr_en = 1'b0, ef_tr_ch = 1'b0;
  logic [2:0] ef_tr_cls = '0;
  logic [31:0] ef_tr_lcw = '0;
  int unsigned ef_tr_cnt = 0;
  logic [5:0] ef_sip_q = '0, ef_chp_q = '0;
  always @(posedge clk_i) begin
    ef_trn_t e;
    logic [2:0] ci;
    logic upd, exp_upd, rise_s, rise_c;
    ef_sip_q <= tok_sip_i;
    ef_chp_q <= tok_chp_i;
    rise_s = (tok_sip_i == EfCodeMatch) && (ef_sip_q != EfCodeMatch);
    rise_c = (tok_chp_i == EfCodeMatch) && (ef_chp_q != EfCodeMatch);
    if (!ef_sensed || !ef_own_tr) begin
      ef_tr_arm <= 1'b0;
    end else if (!ef_tr_arm && (rise_s || rise_c) && (ef_lc != EfPe)) begin
      ef_tr_arm <= 1'b1;
      ef_tr_en  <= ef_trans_en;
      ef_tr_ch  <= !rise_s;
      ef_tr_cls <= (ef_lc == EfTd) ? 3'd0 : (ef_lc == EfProd) ? 3'd1 : (ef_lc == EfRs) ? 3'd2 :
          (ef_lc == EfRc) ? 3'd3 : 3'd4;
      ef_tr_lcw <= ef_lc_word;
      ef_tr_cnt <= 0;
    end else if (ef_tr_arm) begin
      upd = (ef_lc_word != ef_tr_lcw);
      if (upd || (ef_tr_cnt == EfTransWin)) begin
        exp_upd = ef_tr_en && ((!ef_tr_ch && (ef_tr_cls <= 3'd1)) || (ef_tr_ch && (ef_tr_cls == 3'd2)));
        e = '0;
        e.tr = {upd != exp_upd, 5'((32'(ef_tr_en) * 2 + 32'(ef_tr_ch)) * 5 + 32'(ef_tr_cls))};
        e.tr_v = 1'b1;
        u_sep_lc_illegal_transition_cg.sample(e);
        ef_tr_arm <= 1'b0;
      end else begin
        ef_tr_cnt <= ef_tr_cnt + 1;
      end
    end
  end

  // ---------------------------------------------------------------------
  // Program and read requests: a frontdoor go on EFUSE_PROGRAM_CTRL or
  // EFUSE_READ_CTRL. A program lands when a PROGRAM command to its bit
  // address reaches the shim (shim_cmd_i) after the AW of the go.
  // ---------------------------------------------------------------------
  logic ef_pg_v = 1'b0;  // a program request is open
  logic [15:0] ef_pg_addr = '0;
  logic ef_pg_data = 1'b0, ef_pg_en = 1'b0, ef_pg_sensed = 1'b0, ef_pg_stm = 1'b0;
  logic [1:0] ef_pg_tok = '0;  // {RMA_CHIPLET, RMA_SIP} matched at the go
  logic ef_pg_seen = 1'b0;
  logic [31:0] ef_pg_pre = '0;  // sensed word of the target before the program
  logic ef_pg_lock_open = 1'b0;  // waits for the STATUS read that ends it
  logic ef_pg_idle_open = 1'b0;  // waits for the idle interface
  int unsigned ef_pg_cnt = 0;
  logic ef_rg_v = 1'b0;
  logic [15:0] ef_rg_addr = '0;
  logic ef_rg_en = 1'b0, ef_rg_pen = 1'b0;
  logic ef_rg_rcmd = 1'b0;  // a READ command reached the shim since the AW of the go
  logic ef_rg_lock_open = 1'b0, ef_rg_idle_open = 1'b0, ef_rg_win_open = 1'b0;
  int unsigned ef_rg_cnt = 0;
  logic ef_aw_rcmd_v = 1'b0;
  always @(posedge clk_i) begin
    if (aw_hs) ef_aw_rcmd_v <= ef_cmd_rd;
    else if (ef_cmd_rd) ef_aw_rcmd_v <= 1'b1;
  end
  wire ef_pg_go = wr_okay && (aw_addr_q == EfPgCtrl) && |(wr_data & EfPgGoMask);
  wire ef_rg_go = wr_okay && (aw_addr_q == EfRdCtrl) && |(wr_data & EfRdGoMask);
  wire ef_status_rd = rd_okay && (ar_addr_q == EfStatus);
  wire ef_idle = (efuse_read_busy_i !== 1'b1) && (efuse_program_busy_i !== 1'b1);
  wire [3:0] ef_flags = {
    efuse_read_error_i === 1'b1, rd_addr_err_i === 1'b1, pg_addr_err_i === 1'b1, req_err_i === 1'b1
  };

  // Case of a request (efuse_interface_ctrl.adoc): 0 pre_sense_prog,
  // 1 read_no_enable, 2 read_oob, 3 prog_oob, 4 prog_wlocked, 5
  // read_rlocked, 6 both_enables, 7 prog_data0, 8 accepted twin, 15 none.
  function automatic logic [3:0] ef_pg_case(input logic [15:0] a, input logic d, input logic en,
                                            input logic sensed);
    if (!sensed) return 4'd0;
    if (a >= 16'(EfFuseBits)) return 4'd3;
    if (ef_wlock(ef_slot_of(11'(a[12:3])))) return 4'd4;
    if (!d) return 4'd7;
    if (en) return 4'd8;
    return 4'd15;
  endfunction
  function automatic logic [3:0] ef_rg_case(input logic [15:0] a, input logic en, input logic pen);
    if (!en) return 4'd1;
    if (pen) return 4'd6;
    if (a >= 16'(EfFuseBits)) return 4'd2;
    if (ef_rlock(ef_slot_of(11'(a[12:3])))) return 4'd5;
    return 4'd8;
  endfunction
  logic [3:0] ef_pg_cs = 4'd15, ef_rg_cs = 4'd15;

  // Window of x_case_cmd for pre_sense_prog: reset release to sense done.
  logic ef_ps_go = 1'b0, ef_ps_prog = 1'b0;
  // both_enables: from the go to the next cold reset.
  logic ef_be_arm = 1'b0, ef_be_rcmd = 1'b0;

  // Lock policy, if-status and secure test mode sampling of a program end.
  task automatic ef_prog_lock_end();
    logic [5:0] s, sn;
    logic wl, rl, landed;
    logic [9:0] off;
    off = ef_pg_addr[12:3];
    s = ef_slot_of({1'b0, off});
    landed = ef_pg_seen;
    if (ef_own_lock && ef_pg_data && (ef_pg_addr < 16'(EfFuseBits)) && (s != EfNoSlot) &&
        (s != 6'd0)) begin
      wl = ef_wlock(s);
      rl = ef_rlock(s);
      ef_lk(0, {landed == wl, 7'((s - 6'd1) * 2) + 7'(wl)});
      ef_lk(2, 8'({landed == wl, rl, wl, 1'b0}));
      if (!wl && !rl && landed) begin
        if (ef_wlock(s - 6'd1) || ef_rlock(s - 6'd1)) ef_lk(3, 8'd0);
        sn = s + 6'd1;
        if ((sn < 6'(EfSlots)) && (ef_wlock(sn) || ef_rlock(sn))) ef_lk(3, 8'd2);
      end
      if (landed && (ef_word(off) == ef_pg_pre)) ef_lk(8, 8'd0);
    end
    // x_lc_prog_gate: LC_STATE bit 1 is gated by the RMA_SIP match, bit 2 by
    // the RMA_CHIPLET match (otp_fuse_controller.adoc, Fuse Programming and
    // RMA Authorization).
    if (ef_own_tr && ef_pg_data) begin
      if (ef_pg_addr == 16'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET * 8 + 1)) begin
        if (ef_pg_tok[0]) ef_lk(10, {5'd0, 1'b0, 1'b0, landed});
        else if (ef_pg_tok[1]) ef_lk(10, {5'd0, 1'b0, 1'b1, landed});
      end else if (ef_pg_addr == 16'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET * 8 + 2)) begin
        if (ef_pg_tok[1]) ef_lk(10, {5'd0, 1'b1, 1'b0, landed});
      end
    end
  endtask

  // cp_prog_visibility bin 1: the next sense done after a landed program.
  logic ef_pv_pend = 1'b0;
  logic [7:0] ef_pv_word = '0;
  logic [4:0] ef_pv_bit = '0;
  logic [31:0] ef_pv_pre = '0;

  always @(posedge clk_i) begin
    ef_stm_t te;
    logic [5:0] s;
    logic [9:0] off;
    logic [2:0] cls;
    if (in_reset) begin
      ef_pg_v <= 1'b0;
      ef_pg_lock_open <= 1'b0;
      ef_pg_idle_open <= 1'b0;
      ef_rg_v <= 1'b0;
      ef_rg_lock_open <= 1'b0;
      ef_rg_idle_open <= 1'b0;
      ef_rg_win_open <= 1'b0;
    end else begin
      // Program go.
      if (ef_pg_go) begin
        ef_pg_v <= 1'b1;
        ef_pg_addr <= 16'(wr_data & EfPgAddrMask);
        ef_pg_data <= |(wr_data & EfPgDataMask);
        ef_pg_en <= |(wr_data & EfPgEnMask);
        ef_pg_sensed <= (fuse_sense_done_i === 1'b1);
        ef_pg_stm <= (secure_tm_i === 1'b1);
        ef_pg_tok <= {tok_chp_i == EfCodeMatch, tok_sip_i == EfCodeMatch};
        ef_pg_seen <= ef_aw_pcmd_v && (13'(wr_data & EfPgAddrMask) == ef_aw_pcmd_addr) &&
            ((wr_data & EfPgAddrMask) < 32'(EfFuseBits));
        ef_pg_pre <= ef_aw_shadow[32*(wr_data[12:5])+:32];
        ef_pg_lock_open <= 1'b1;
        ef_pg_idle_open <= 1'b1;
        ef_pg_cnt <= 0;
        ef_pg_cs <= ef_pg_case(16'(wr_data & EfPgAddrMask), |(wr_data & EfPgDataMask),
                               |(wr_data & EfPgEnMask), fuse_sense_done_i === 1'b1);
        if (fuse_sense_done_i !== 1'b1) ef_ps_go <= 1'b1;
      end else if (ef_pg_v) begin
        if (ef_cmd_pg && (16'(ef_cmd_addr) == ef_pg_addr)) ef_pg_seen <= 1'b1;
        if (ef_pg_cnt < EfBothWin) ef_pg_cnt <= ef_pg_cnt + 1;
        if (ef_pg_lock_open && ef_status_rd && (efuse_program_busy_i !== 1'b1)) begin
          ef_pg_lock_open <= 1'b0;
          ef_prog_lock_end();
          if (ef_own_lock && ef_pg_data && ef_pg_seen) begin
            ef_pv_pend <= 1'b1;
            ef_pv_word <= ef_pg_addr[12:5];
            ef_pv_bit <= ef_pg_addr[4:0];
            ef_pv_pre <= ef_pg_pre;
          end
        end
        if (ef_pg_idle_open && (ef_pg_cnt >= EfGoSettle) && ef_idle) begin
          ef_pg_idle_open <= 1'b0;
          // sep_efuse_if_status_cg program cases and twin.
          if (ef_own_ifs && (ef_pg_cs != 4'd15)) begin
            if (ef_pg_cs == 4'd8) begin
              ef_ifs(1, 7'(ef_flags));
              if (ef_pg_seen && (ef_flags == 4'b0000)) ef_ifs(7, 7'd1);
            end else begin
              ef_ifs(0, 7'(ef_pg_cs));
              ef_ifs(2, {ef_pg_cs[2:0], ef_flags});
              if (ef_pg_cs inside {4'd3, 4'd4}) ef_ifs(1, 7'(ef_flags));
            end
          end
          // x_prog_block: program class at the strap of the go. LC_STATE is
          // gated by the token and is not a class.
          off = ef_pg_addr[12:3];
          s = ef_slot_of({1'b0, off});
          cls = 3'd7;
          if (off < 10'(SEP_EFUSE_MAP_LC_STATE_REG_OFFSET)) cls = 3'd3;
          else if (s inside {EfSlotSipDis, EfSlotSysDis}) cls = 3'd2;
          else if ((s >= EfSlotSpare0) && (s < 6'(EfSlots))) cls = 3'd4;
          else if ((s != 6'd0) && (s != EfNoSlot) && ((EfSlotOff[s+1] - EfSlotOff[s]) == 11'd32))
            cls = 3'd0;
          else if ((s != 6'd0) && (s != EfNoSlot) && ((EfSlotOff[s+1] - EfSlotOff[s]) == 11'd4))
            cls = 3'd1;
          if (ef_own_stm && ef_pg_data && ef_pg_sensed && (ef_pg_addr < 16'(EfFuseBits)) && (cls != 3'd7)) begin
            te = '0;
            te.pb = {ef_pg_seen == ef_pg_stm, 4'(cls * 2) + 4'(ef_pg_stm)};
            te.pb_v = 1'b1;
            u_sep_efuse_secure_tm_cg.sample(te);
          end
        end
        if (!ef_pg_lock_open && !ef_pg_idle_open) ef_pg_v <= 1'b0;
      end

      // Read go.
      if (ef_rg_go) begin
        ef_rg_v <= 1'b1;
        ef_rg_addr <= 16'(wr_data & EfRdAddrMask);
        ef_rg_en <= |(wr_data & EfRdEnMask);
        ef_rg_pen <= ef_pen_q;
        ef_rg_rcmd <= ef_aw_rcmd_v;
        ef_rg_lock_open <= 1'b1;
        ef_rg_idle_open <= 1'b1;
        ef_rg_win_open <= 1'b0;
        ef_rg_cnt <= 0;
        ef_rg_cs <= ef_rg_case(16'(wr_data & EfRdAddrMask), |(wr_data & EfRdEnMask), ef_pen_q);
        if (ef_rg_case(
                16'(wr_data & EfRdAddrMask), |(wr_data & EfRdEnMask), ef_pen_q
            ) == 4'd6) begin
          ef_be_arm <= 1'b1;
          ef_be_rcmd <= ef_aw_rcmd_v;
        end
      end else if (ef_rg_v) begin
        if (ef_cmd_rd) ef_rg_rcmd <= 1'b1;
        if (ef_rg_cnt < EfBothWin + EfCmdWin) ef_rg_cnt <= ef_rg_cnt + 1;
        // x_slot_read and x_kind_op, read-locked kind: the STATUS read that
        // ends the request carries efuse_req_error.
        if (ef_rg_lock_open && ef_status_rd && (efuse_read_busy_i !== 1'b1)) begin
          ef_rg_lock_open <= 1'b0;
          s = ef_slot_of(11'(ef_rg_addr[12:3]));
          if (ef_own_lock && ef_rg_en && !ef_rg_pen && (ef_rg_addr < 16'(EfFuseBits)) &&
              (s != EfNoSlot) && (s != 6'd0) && ef_rlock(
                  s
              )) begin
            ef_lk(1, {(rd_data & EfReqErrMask) == 32'h0, 7'((s - 6'd1) * 2 + 1)});
            ef_lk(2, 8'({(rd_data & EfReqErrMask) == 32'h0, 1'b1, ef_wlock(s), 1'b1}));
          end
        end
        if (ef_rg_idle_open && (((ef_rg_cnt >= EfGoSettle) && ef_idle && (ef_rg_cs != 4'd6)) ||
                                ((ef_rg_cs == 4'd6) && (ef_rg_cnt == EfBothWin)))) begin
          ef_rg_idle_open <= 1'b0;
          ef_rg_win_open <= (ef_rg_cs == 4'd5);
          ef_rg_cnt <= 0;
          if (ef_own_ifs) begin
            if (ef_rg_cs == 4'd8) begin
              ef_ifs(1, 7'(ef_flags));
              if ((efuse_read_done_i === 1'b1) && (efuse_read_error_i !== 1'b1)) ef_ifs(7, 7'd0);
            end else begin
              ef_ifs(0, 7'(ef_rg_cs));
              ef_ifs(2, {ef_rg_cs[2:0], ef_flags});
              if (ef_rg_cs inside {4'd1, 4'd2}) ef_ifs(1, 7'(ef_flags));
            end
          end
        end
        // x_case_cmd read_rlocked: no READ command from the go to EfCmdWin
        // clocks after the idle sample.
        if (ef_rg_win_open && !ef_rg_idle_open && (ef_rg_cnt == EfCmdWin)) begin
          ef_rg_win_open <= 1'b0;
          if (ef_own_ifs) ef_ifs(3, {4'd0, 2'd1, ef_rg_rcmd || ef_cmd_rd});
        end
        if (!ef_rg_lock_open && !ef_rg_idle_open && !ef_rg_win_open) ef_rg_v <= 1'b0;
      end
    end
  end

  // x_case_cmd pre_sense_prog and both_enables windows; cp_prog_visibility
  // bin 1. These span a reset, so they do not clear on it.
  always @(posedge clk_i) begin
    if (ef_rel) begin
      ef_ps_go   <= 1'b0;
      ef_ps_prog <= 1'b0;
    end else if (!in_reset && ef_cmd_pg && (fuse_sense_done_i !== 1'b1)) begin
      ef_ps_prog <= 1'b1;
    end
    if (ef_sense_rise) begin
      if (ef_ps_go && ef_own_ifs) ef_ifs(3, {4'd0, 2'd0, ef_ps_prog});
      if (ef_pv_pend && ef_own_lock) begin
        if (efuse_shadow_i[32*ef_pv_word+ef_pv_bit] &&
            ((efuse_shadow_i[32*ef_pv_word+:32] & ef_pv_pre) == ef_pv_pre)) begin
          ef_lk(8, 8'd1);
        end
      end
      ef_pv_pend <= 1'b0;
    end
    if (ef_be_arm) begin
      if (ef_cmd_rd && !in_reset) ef_be_rcmd <= 1'b1;
      if (ef_rst_fall) begin
        if (ef_own_ifs) ef_ifs(3, {4'd0, 2'd2, ef_be_rcmd});
        ef_be_arm <= 1'b0;
      end
    end
  end

  // ---------------------------------------------------------------------
  // Frontdoor reads of the shadow map: x_slot_read and x_kind_op (lock
  // clear), x_neighbor_free (read), x_exempt, x_secret_probe and
  // x_secret_read_kept.
  // ---------------------------------------------------------------------
  always @(posedge clk_i) begin
    ef_stm_t te;
    logic [10:0] off;
    logic [5:0] s, sn;
    logic [2:0] f;
    logic bad;
    if (ef_rd_cmpl && (ef_rd_win == EfWShadow) && (fuse_sense_done_i === 1'b1)) begin
      off = 11'(ar_addr_q - EfMapBase);
      s = ef_slot_of(off);
      f = ef_secret_of(s);
      // Lock leaf reads at strap 0, where the frontdoor and the sensed-shadow
      // output carry the same word.
      if (rd_okay && ef_own_lock && (secure_tm_i !== 1'b1)) begin
        if ((s != EfNoSlot) && (s != 6'd0) && !ef_rlock(s)) begin
          bad = (rd_data != ef_word(off[9:0]));
          ef_lk(1, {bad, 7'((s - 6'd1) * 2)});
          ef_lk(2, 8'({bad, 1'b0, ef_wlock(s), 1'b1}));
          if (!ef_wlock(s) && !bad) begin
            if (ef_wlock(s - 6'd1) || ef_rlock(s - 6'd1)) ef_lk(3, 8'd1);
            sn = s + 6'd1;
            if ((sn < 6'(EfSlots)) && (ef_wlock(sn) || ef_rlock(sn))) ef_lk(3, 8'd3);
          end
        end
        if (ef_all_locked && (rd_data == ef_word(off[9:0]))) begin
          if (ar_addr_q == SEP_EFUSE_MAP_LC_STATE_REG_ADDR) ef_lk(4, 8'd0);
          if (ar_addr_q inside {SEP_EFUSE_MAP_LOCKS_REG_ADDR, SEP_EFUSE_MAP_LOCKS_REG_ADDR + 32'd4})
            ef_lk(4, 8'd1);
          if (ar_addr_q == SEP_EFUSE_MAP_LOCKS_SPARE_REG_ADDR) ef_lk(4, 8'd2);
        end
      end
      if (ef_own_stm && (secure_tm_i === 1'b1) && (f != 3'd4)) begin
        te = '0;
        if (stored_shadow_i[32*off[9:2]+:32] != 32'h0) begin
          te.sp = {f[1:0], ef_word(off[9:0]) != 32'h0};
          te.sp_v = 1'b1;
        end
        if (rd_okay && !ef_rlock(s) && (rd_data != 32'h0)) begin
          te.sk = f[1:0];
          te.sk_v = 1'b1;
        end
        u_sep_efuse_secure_tm_cg.sample(te);
      end
    end
  end

  // cp_sense_fills_locked and cp_round_count at sense done. The previous
  // sensed copy survives the cold reset between two senses.
  logic [EfFuseBits-1:0] ef_rc_prev = '0;
  logic ef_rc_pv = 1'b0;
  int unsigned ef_rc_k = 0;
  always @(posedge clk_i) begin
    logic sec, oth;
    int unsigned k;
    if (ef_sense_rise) begin
      sec = 1'b0;
      oth = 1'b0;
      for (int s = 1; s < EfSlots; s++) begin
        if (ef_rlock(6'(s)) && ef_field_nz(6'(s))) begin
          if (ef_secret_of(6'(s)) != 3'd4) sec = 1'b1;
          else oth = 1'b1;
        end
      end
      if (ef_own_lock && sec) ef_lk(5, 8'd0);
      if (ef_own_lock && oth) ef_lk(5, 8'd1);
      k = (ef_rc_pv && ((efuse_shadow_i & ~ef_rc_prev) != '0)) ? ef_rc_k + 1 : 0;
      if (ef_own_lock && (k >= 1) && (k <= 4)) ef_lk(9, 8'(k));
      ef_rc_k <= k;
      ef_rc_prev <= efuse_shadow_i;
      ef_rc_pv <= 1'b1;
    end
  end

  // ---------------------------------------------------------------------
  // Write effects, EfWrSettle clocks after the B of a frontdoor write, against
  // the state at its AW: x_shadow_write_lock, cp_lock_order,
  // cp_export_changes, sep_lc_demote_lock_cg, cp_no_clear and cp_flag_clear.
  // A second write that completes inside the settle drops the first (a
  // missed hit, never a false one).
  // ---------------------------------------------------------------------
  logic ef_pw_v = 1'b0;
  int unsigned ef_pw_cnt = 0;
  logic [31:0] ef_pw_addr = '0, ef_pw_data = '0;
  logic ef_pw_ok = 1'b0;
  logic [EfFuseBits-1:0] ef_pw_shadow = '0;
  logic [63:0] ef_pw_feat = '0;
  logic [1:0] ef_pw_d1 = 2'b10, ef_pw_d2 = 2'b10;
  logic ef_pw_l1 = 1'b0, ef_pw_l2 = 1'b0;
  logic [2:0] ef_pw_fault = '0, ef_pw_flags = '0;

  always @(posedge clk_i) begin
    ef_dem_t me;
    ef_dlk_t ke;
    logic [10:0] off;
    logic [5:0] s;
    logic [31:0] pre, now, pre_l, now_l;
    logic [1:0] f;
    logic wl, chg, r, ol, od, nd, nl, l_other, d_other_pre, d_other_now;
    logic [1:0] wcls;
    logic [2:0] clr, now_flags;
    if (in_reset) begin
      ef_pw_v <= 1'b0;
    end else if (ef_wr_cmpl) begin
      ef_pw_v <= 1'b1;
      ef_pw_cnt <= 0;
      ef_pw_addr <= aw_addr_q;
      ef_pw_data <= wr_data;
      ef_pw_ok <= (lsu_b_resp_i == AxiOkay);
      ef_pw_shadow <= ef_aw_shadow;
      ef_pw_feat <= ef_aw_feat;
      ef_pw_d1 <= ef_aw_d1;
      ef_pw_d2 <= ef_aw_d2;
      ef_pw_l1 <= ef_aw_l1;
      ef_pw_l2 <= ef_aw_l2;
      ef_pw_fault <= ef_aw_fault;
      ef_pw_flags <= ef_aw_flags;
    end else if (ef_pw_v && (ef_pw_cnt < EfWrSettle)) begin
      ef_pw_cnt <= ef_pw_cnt + 1;
    end else if (ef_pw_v) begin
      ef_pw_v <= 1'b0;
      // Shadow writes (sensed shadow before and after).
      if (ef_win(ef_pw_addr) == EfWShadow) begin
        off = 11'(ef_pw_addr - EfMapBase);
        s = ef_slot_of(off);
        pre = ef_pw_shadow[32*off[9:2]+:32];
        now = ef_word(off[9:0]);
        // Write-lock as the LOCKS words of the shadow held at the AW.
        wl = (s < 6'd32) ? ef_pw_shadow[32*EfWLocks+2*s] :
            (s < 6'(EfSlots)) ? ef_pw_shadow[32*EfWLocksSp+2*(s-6'd32)] : 1'b0;
        chg = (now != pre);
        f = (s == EfSlotSipDis) ? 2'd0 : (s == EfSlotSysDis) ? 2'd1 : (s == EfSlotSigners) ? 2'd2 : 2'd3;
        if (ef_own_lock && (s inside {EfSlotSipDis, EfSlotSysDis, EfSlotSigners, EfSlotAlgs}) &&
            ((ef_pw_data & ~pre) != 32'h0)) begin
          ef_lk(6, 8'({wl ? chg : !chg, f, wl}));
          if (!wl && chg) ef_lk(7, 8'd0);
          if (wl && !chg) ef_lk(7, 8'd1);
        end
        // A write that clears a set lock bit leaves every set bit set.
        if (ef_own_lock && (s == EfNoSlot) && (pre != 32'h0) && ((ef_pw_data & pre) != pre) &&
            ((now & pre) == pre)) begin
          ef_lk(7, 8'd2);
        end
      end
      // DEMOTE_1 / DEMOTE_2 (sep_lifecycle_ctrl.adoc, DEMOTE_1: demote bit 0,
      // lock bit 1).
      if (ef_pw_ok && (ef_pw_addr inside {EfDemote1, EfDemote2})) begin
        r = (ef_pw_addr == EfDemote2);
        od = r ? (ef_pw_d2 == 2'b01) : (ef_pw_d1 == 2'b01);
        ol = r ? ef_pw_l2 : ef_pw_l1;
        nd = r ? (demote_2_i == 2'b01) : (demote_1_i == 2'b01);
        nl = r ? (demote_lock_2_i === 1'b1) : (demote_lock_1_i === 1'b1);
        l_other = r ? ef_pw_l1 : ef_pw_l2;
        d_other_pre = r ? (ef_pw_d1 == 2'b01) : (ef_pw_d2 == 2'b01);
        d_other_now = r ? (demote_1_i == 2'b01) : (demote_2_i == 2'b01);
        chg = (od != nd) || (ol != nl);
        wcls = (ef_pw_data == EfDemoteMask) ? 2'd0 : (ef_pw_data == EfDemLockMask) ? 2'd1 :
            (ef_pw_data == 32'h0) ? 2'd2 : 2'd3;
        if (ef_own_fc) begin
          if (|(ef_pw_data & EfDemoteMask)) begin
            me = '0;
            me.ex = r;
            me.ex_v = r ? (demote_2_i != ef_pw_d2) : (demote_1_i != ef_pw_d1);
            u_sep_lc_demotion_cg.sample(me);
          end
          ke = '0;
          if ((wcls != 2'd3) && !((wcls == 2'd0) && od)) begin
            ke.rl = {r, ol, wcls, chg};
            ke.rl_v = 1'b1;
          end
          if (ol && (wcls inside {2'd0, 2'd2})) begin
            ke.cn = {r, od, wcls == 2'd2, chg};
            ke.cn_v = 1'b1;
          end
          if (!ol && chg && l_other) begin
            ke.ci = r;
            ke.ci_v = 1'b1;
          end
          if (ol && (feat_ctrl_i == ef_pw_feat) && (d_other_pre == d_other_now) && (ef_grp(
                  ef_pw_shadow[32*EfWSipDis+:64] | ef_pw_shadow[32*EfWSysDis+:64], r
              ) != 24'h0)) begin
            ke.pu = r;
            ke.pu_v = 1'b1;
          end
          u_sep_lc_demote_lock_cg.sample(ke);
        end
      end
      // TOKEN_MATCH_FAULT (efuse_mmr.adoc): a write of 1 to a set bit.
      if ((ef_pw_addr == EfMatchFault) && ef_own_tf) begin
        if (|(ef_pw_data & EFUSE_MMR_TOKEN_MATCH_FAULT_RMA_SIP_TOKEN_FAULT_MASK) && ef_pw_fault[0] &&
            (tok_fault_i[0] === 1'b1))
          ef_tfs(4, 5'd0);
        if (|(ef_pw_data & EFUSE_MMR_TOKEN_MATCH_FAULT_RMA_CHIPLET_TOKEN_FAULT_MASK) && ef_pw_fault[1] &&
            (tok_fault_i[1] === 1'b1))
          ef_tfs(4, 5'd1);
        if (|(ef_pw_data & EFUSE_MMR_TOKEN_MATCH_FAULT_SECURE_DISABLE_TOKEN_FAULT_MASK) &&
            ef_pw_fault[2] && (tok_fault_i[2] === 1'b1))
          ef_tfs(4, 5'd2);
      end
      // EFUSE_INTERFACE_CTRL_STATUS: one clear bit written over a set flag;
      // the flag falls and the other flags keep their values.
      if ((ef_pw_addr == EfStatus) && ef_own_ifs) begin
        clr = {|(ef_pw_data & EfRdAddrClrMask), |(ef_pw_data & EfPgAddrClrMask),
               |(ef_pw_data & EfReqErrClrMask)};
        now_flags = {rd_addr_err_i === 1'b1, pg_addr_err_i === 1'b1, req_err_i === 1'b1};
        if ($countones(clr) == 1) begin
          if (clr[2] && ef_pw_flags[2] && !now_flags[2] && (now_flags[1:0] == ef_pw_flags[1:0]))
            ef_ifs(4, 7'd0);
          if (clr[1] && ef_pw_flags[1] && !now_flags[1] &&
              ({now_flags[2], now_flags[0]} == {ef_pw_flags[2], ef_pw_flags[0]}))
            ef_ifs(4, 7'd1);
          if (clr[0] && ef_pw_flags[0] && !now_flags[0] && (now_flags[2:1] == ef_pw_flags[2:1]))
            ef_ifs(4, 7'd2);
        end
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_lc_demotion_cg clocked points: cp_assert_order and cp_reset_vector.
  // The reset vector is taken on the last clock before rst_ni falls and
  // checked at the next sense done, so the tracker does not clear on reset.
  // ---------------------------------------------------------------------
  logic [1:0] ef_ao_first = 2'd0;  // 1 DEMOTE_1 first, 2 DEMOTE_2 first
  logic ef_ao_both_q = 1'b0;
  logic [3:0] ef_rv_last = '0, ef_rv_vec = '0;
  logic ef_rv_pend = 1'b0;
  always @(posedge clk_i) begin
    ef_dem_t me;
    logic [3:0] vec;
    vec = {ef_d1, demote_lock_1_i === 1'b1, ef_d2, demote_lock_2_i === 1'b1};
    if (!in_reset) begin
      ef_rv_last <= vec;
      ef_ao_both_q <= ef_d1 && ef_d2;
      if (!ef_d1 && !ef_d2) ef_ao_first <= 2'd0;
      else if ((ef_ao_first == 2'd0) && ef_d1 && !ef_d2) ef_ao_first <= 2'd1;
      else if ((ef_ao_first == 2'd0) && ef_d2 && !ef_d1) ef_ao_first <= 2'd2;
      if (ef_d1 && ef_d2 && !ef_ao_both_q && (ef_ao_first != 2'd0) && ef_own_fc && ef_sensed) begin
        me = '0;
        me.ao = (ef_ao_first == 2'd2);
        me.ao_v = 1'b1;
        u_sep_lc_demotion_cg.sample(me);
      end
    end else begin
      ef_ao_first <= 2'd0;
      ef_ao_both_q <= 1'b0;
    end
    if (ef_rst_fall) begin
      ef_rv_pend <= 1'b1;
      ef_rv_vec  <= ef_rv_last;
    end
    if (ef_sense_rise && ef_rv_pend) begin
      ef_rv_pend <= 1'b0;
      if (ef_own_fc && (vec == 4'h0)) begin
        me = '0;
        me.rv = ef_rv_vec;
        me.rv_v = 1'b1;
        u_sep_lc_demotion_cg.sample(me);
      end
    end
  end

  // ---------------------------------------------------------------------
  // Token channels. A go on channel c arms a tracker; its verdict is the
  // first non-idle code after the code has read idle at least once since
  // the go (token_processing.adoc, Token Submission: a start clears digest
  // validity, so the comparison reads idle until the new digest is there).
  // Channel 0 RMA_SIP, 1 RMA_CHIPLET, 2 SEC_DIS.
  // ---------------------------------------------------------------------
  logic [2:0] ef_go_arm = '0, ef_go_idle = '0, ef_go_busy0 = '0, ef_go_sensed = '0;
  logic [2:0] ef_go_others_ok = '0, ef_go_fault = '0, ef_go_replay = '0;
  logic [2:0][1:0] ef_go_shape = '0;
  logic [2:0] ef_go_shape_v = '0;
  logic [2:0] ef_pre_arm = '0, ef_pre_bad = '0;  // RMA go before sense done
  logic [2:0][5:0] ef_code_q = '0;
  logic [2:0][7:0][31:0] ef_words_q = '0;
  logic [2:0] ef_hw_arm = '0;
  logic [2:0][5:0] ef_hw_code = '0;
  int unsigned ef_hw_cnt[3] = '{0, 0, 0};
  logic [2:0] ef_fault_q = '0;
  logic [7:0][31:0] ef_ret_words = '0, ef_last_sipw = '0;
  logic [5:0] ef_last_sipc = '0;
  logic ef_ret_pend = 1'b0, ef_ret_wait = 1'b0, ef_ret_nogo = 1'b0;
  wire [2:0][255:0] ef_dig = {
    sec_disable_expected_i, efuse_shadow_i[32*EfWChipDig+:256], efuse_shadow_i[32*EfWSipDig+:256]
  };

  function automatic logic ef_nonidle(input logic [5:0] c);
    return (c != EfCodeIdle) && !$isunknown(c);
  endfunction
  // Words equal to a 256-bit value, in either word order.
  function automatic logic ef_words_eq(input logic [7:0][31:0] w, input logic [255:0] d);
    logic rev;
    rev = 1'b1;
    for (int i = 0; i < 8; i++) if (w[i] != d[32*(7-i)+:32]) rev = 1'b0;
    return (w == d) || rev;
  endfunction

  always @(posedge clk_i) begin
    logic [5:0] code, v;
    logic [1:0] o1, o2;
    if (!ef_live) begin
      ef_go_arm <= '0;
      ef_pre_arm <= '0;
      ef_hw_arm <= '0;
    end else begin
      for (int c = 0; c < 3; c++) begin
        code = ef_code[c];
        o1 = 2'((c + 1) % 3);
        o2 = 2'((c + 2) % 3);
        // cp_code: every new status value of each channel.
        if ((code !== ef_code_q[c]) && !$isunknown(code)) begin
          if ((code == EfCodeErr) ? ef_own_tf : (ef_own_tch || ((code != EfCodeIdle) &&
              (code != EfCodeMatch) && (code != EfCodeMismatch) && ef_own_tf))) begin
            ef_tc(1, code);
          end
        end
        if (token_go_i[c] === 1'b1) begin
          ef_go_arm[c] <= 1'b1;
          ef_go_idle[c] <= !ef_nonidle(code);
          ef_go_busy0[c] <= ef_nonidle(code);
          ef_go_sensed[c] <= (fuse_sense_done_i === 1'b1);
          ef_go_others_ok[c] <= ef_nonidle(ef_code[o1]) && ef_nonidle(ef_code[o2]);
          ef_go_fault[c] <= (tok_fault_i[c] === 1'b1);
          ef_go_replay[c] <= ef_words_eq(tok_words_i[c], ef_dig[c]);
          ef_go_shape_v[c] <= 1'b1;
          if (tok_words_i[c] == '0) ef_go_shape[c] <= 2'd0;
          else if (tok_words_i[c] == '1) ef_go_shape[c] <= 2'd1;
          else if ((tok_words_i[c] == tok_words_i[o1]) || (tok_words_i[c] == tok_words_i[o2]))
            ef_go_shape[c] <= 2'd2;
          else ef_go_shape_v[c] <= 1'b0;
          if ((c < 2) && (fuse_sense_done_i !== 1'b1)) begin
            ef_pre_arm[c] <= 1'b1;
            ef_pre_bad[c] <= 1'b0;
          end
        end else if (ef_go_arm[c]) begin
          if (!ef_nonidle(code)) ef_go_idle[c] <= 1'b1;
          if ((ef_code[o1] != ef_code_q[o1]) || (ef_code[o2] != ef_code_q[o2]))
            ef_go_others_ok[c] <= 1'b0;
          if (ef_go_idle[c] && ef_nonidle(code)) begin
            ef_go_arm[c] <= 1'b0;
            if (ef_own_tch) begin
              if (code inside {EfCodeMatch, EfCodeMismatch}) begin
                ef_tc(0, {1'b0, 2'(c), code == EfCodeMismatch});
                if (ef_go_shape_v[c] && !((c == 2) && (ef_go_shape[c] == 2'd0)))
                  ef_tc(2, {1'b0, code == EfCodeMatch, 4'(c * 3) + 4'(ef_go_shape[c])});
                if ((c < 2) && ef_go_sensed[c] && (code == EfCodeMatch))
                  ef_tc(3, {3'd0, 2'(c), 1'b1});
                if (ef_go_replay[c]) ef_rob(0, {2'(c), code == EfCodeMatch});
              end
              if (ef_go_others_ok[c] && (ef_code[o1] == ef_code_q[o1]) && (ef_code[o2] == ef_code_q[o2]))
                ef_tc(4, 6'(c));
              if (ef_go_busy0[c]) ef_tc(6, 6'(c));
            end
            // x_ch_retry: a valid go after a fault, with the sticky bit and
            // the interrupt line still high.
            if (ef_own_tf && ef_go_fault[c] && (tok_fault_i[c] === 1'b1) && ef_irq &&
                (code inside {EfCodeMatch, EfCodeMismatch}) && !((c == 2) && (code == EfCodeMismatch))) begin
              ef_tfs(3, 5'(c * 2) + 5'(code == EfCodeMismatch));
            end
          end
        end
        // x_rma_go_phase, before sense: the code stays idle until sense done.
        if (ef_pre_arm[c] && (fuse_sense_done_i !== 1'b1) && ef_nonidle(code))
          ef_pre_bad[c] <= 1'b1;
        if (ef_pre_arm[c] && ef_sense_rise) begin
          ef_pre_arm[c] <= 1'b0;
          if (ef_own_tch && !ef_pre_bad[c] && !ef_nonidle(code)) ef_tc(3, {3'd0, 2'(c), 1'b0});
        end
        // cp_hold_word_write: a token word changes while a non-idle code is
        // held, and the code is unchanged EfTokSettle clocks later.
        if ((tok_words_i[c] !== ef_words_q[c]) && ef_nonidle(code) && !ef_go_arm[c]) begin
          ef_hw_arm[c] <= 1'b1;
          ef_hw_code[c] <= code;
          ef_hw_cnt[c] <= 0;
        end else if (ef_hw_arm[c]) begin
          if ((token_go_i[c] === 1'b1) || (code != ef_hw_code[c])) begin
            ef_hw_arm[c] <= 1'b0;
          end else if (ef_hw_cnt[c] == EfTokSettle) begin
            ef_hw_arm[c] <= 1'b0;
            if (ef_own_tch) ef_tc(5, 6'(c));
          end else begin
            ef_hw_cnt[c] <= ef_hw_cnt[c] + 1;
          end
        end
      end
    end
    ef_code_q <= ef_code;
    ef_words_q <= tok_words_i;
  end

  // cp_retention: a cold reset with an RMA_SIP Match held. The words and the
  // code are taken on the last clock before rst_ni falls.
  always @(posedge clk_i) begin
    if (!in_reset) begin
      ef_last_sipw <= tok_words_i[0];
      ef_last_sipc <= tok_sip_i;
    end
    if (ef_rst_fall) begin
      ef_ret_pend  <= (ef_last_sipc == EfCodeMatch);
      ef_ret_words <= ef_last_sipw;
      ef_ret_wait  <= 1'b0;
    end
    if (ef_rel && ef_ret_pend) begin
      ef_ret_pend <= 1'b0;
      ef_ret_wait <= 1'b1;
      ef_ret_nogo <= 1'b1;
      if (ef_own_tch && !skip_fuse_sense_q) begin
        if (tok_words_i[0] === ef_ret_words) ef_tc(7, 6'd0);
        if ((tok_sip_i == EfCodeIdle) && (fuse_sense_done_i !== 1'b1)) ef_tc(7, 6'd1);
      end
    end else if (ef_ret_wait && !in_reset) begin
      if (token_go_i[0] === 1'b1) ef_ret_nogo <= 1'b0;
      if (ef_nonidle(tok_sip_i)) begin
        ef_ret_wait <= 1'b0;
        if (ef_own_tch && ef_ret_nogo && (token_go_i[0] !== 1'b1) && (fuse_sense_done_i === 1'b1) &&
            (tok_sip_i == EfCodeMatch))
          ef_tc(7, 6'd2);
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_token_fault_cg.
  // ---------------------------------------------------------------------
  logic ef_cf_arm = 1'b0, ef_cf_dir = 1'b0, ef_cf_fault = 1'b0, ef_cf_go = 1'b0;
  logic ef_so_arm = 1'b0;
  logic [2:0] ef_rc_fault_last = '0;
  logic [2:0] ef_rc_pend = '0;
  logic [1:0] ef_lf_te_q = '0, ef_lf_go = '0, ef_lf_chg = '0, ef_lf_rel = '0, ef_lf_rel_go = '0;
  logic [1:0][255:0] ef_lf_dig = '0;
  logic [1:0] ef_lf_vld = '0;
  int unsigned ef_lf_cnt[2] = '{0, 0};

  // Copy and kind of a fault on channel c from its gated rails: a collapsed
  // pair is match_p[i] == match_n[i]; a dissent is one copy whose legal pair
  // differs from the other two. 5'd31 when neither.
  function automatic logic [4:0] ef_kind_copy(input int unsigned c);
    logic [2:0] p, n, col;
    p = cmp_match_p_i[3*c+:3];
    n = cmp_match_n_i[3*c+:3];
    col = ~(p ^ n);
    for (int i = 0; i < 3; i++) begin
      if (col == (3'b001 << i)) return 5'(c * 6 + i);
    end
    if (col == 3'b000) begin
      for (int i = 0; i < 3; i++) begin
        if ((p == (3'b001 << i)) || (p == ~(3'b001 << i))) return 5'(c * 6 + 3 + i);
      end
    end
    return 5'd31;
  endfunction

  always @(posedge clk_i) begin
    logic [4:0] kc;
    int unsigned c1;
    if (!in_reset) begin
      ef_fault_q <= tok_fault_i;
      ef_rc_fault_last <= tok_fault_i;
    end
    if (ef_live) begin
      for (int c = 0; c < 3; c++) begin
        if ((tok_fault_i[c] === 1'b1) && !ef_fault_q[c] && ef_own_tf) begin
          kc = ef_kind_copy(c);
          if (kc != 5'd31) ef_tfs(0, kc);
          if (c == 2) ef_so_arm <= 1'b1;
        end
      end
      // x_ch_common_flip on RMA_CHIPLET: a flip between Match and Mismatch
      // with no go since the last code change.
      if (token_go_i[1] === 1'b1) ef_cf_go <= 1'b1;
      if (tok_chp_i != ef_chp_q) begin
        ef_cf_go <= 1'b0;
        if (!ef_cf_go && (token_go_i[1] !== 1'b1) &&
            (((ef_chp_q == EfCodeMatch) && (tok_chp_i == EfCodeMismatch)) ||
             ((ef_chp_q == EfCodeMismatch) && (tok_chp_i == EfCodeMatch)))) begin
          ef_cf_arm <= 1'b1;
          ef_cf_dir <= (tok_chp_i == EfCodeMatch);
          ef_cf_fault <= (tok_fault_i[1] === 1'b1);
        end
      end
      if (ef_tok_ev) begin
        if (ef_cf_arm) begin
          ef_cf_arm <= 1'b0;
          if (ef_own_tf) ef_tfs(1, {3'd0, (tok_fault_i[1] === 1'b1) && !ef_cf_fault, ef_cf_dir});
        end
        if (ef_so_arm) begin
          ef_so_arm <= 1'b0;
          if (ef_own_tf && !ef_sd) ef_tfs(6, 5'd1);
        end
        if (ef_own_tf) begin
          for (int c = 0; c < 3; c++) begin
            if (ef_code[c] == EfCodeErr) ef_tfs(2, {1'b0, 2'(c), tok_fault_i[c] === 1'b1, ef_irq});
          end
          for (int c = 0; c < 3; c++) begin
            if (tok_fault_i === (3'b001 << c)) ef_tfs(8, {2'b00, 2'(c), !ef_irq});
          end
        end
      end
    end else begin
      ef_cf_arm <= 1'b0;
      ef_so_arm <= 1'b0;
    end
    // cp_reset_clear: the sticky bit and the line are 0 after the reset.
    if (ef_rst_fall) ef_rc_pend <= ef_rc_fault_last;
    if (ef_rel) begin
      ef_rc_pend <= '0;
      for (int c = 0; c < 3; c++) begin
        if (ef_rc_pend[c] && ef_own_tf && (tok_fault_i[c] === 1'b0) && (irq_token_fault_i === 1'b0))
          ef_tfs(5, 5'(c));
      end
    end
    // x_ch_latch_freeze on RMA_CHIPLET (index 0) and SEC_DIS (index 1).
    for (int i = 0; i < 2; i++) begin
      c1 = i + 1;
      ef_lf_te_q[i] <= (latch_test_en_i[c1] === 1'b1);
      if (in_reset) begin
        ef_lf_rel[i] <= 1'b0;
      end else if ((latch_test_en_i[c1] === 1'b1) && !ef_lf_te_q[i]) begin
        ef_lf_dig[i] <= latch_sticky_i[c1];
        ef_lf_vld[i] <= latch_valid_i[c1];
        ef_lf_go[i] <= 1'b0;
        ef_lf_chg[i] <= 1'b0;
        ef_lf_rel[i] <= 1'b0;
      end else if (latch_test_en_i[c1] === 1'b1) begin
        if (token_go_i[c1] === 1'b1) ef_lf_go[i] <= 1'b1;
        if ((latch_sticky_i[c1] !== ef_lf_dig[i]) || (latch_valid_i[c1] !== ef_lf_vld[i]))
          ef_lf_chg[i] <= 1'b1;
      end else if (ef_lf_te_q[i]) begin
        if (ef_lf_go[i] && ef_own_tf) ef_tfs(7, {2'b00, 1'(i), 1'b0, ef_lf_chg[i]});
        ef_lf_rel[i] <= ef_lf_go[i];
        ef_lf_rel_go[i] <= 1'b0;
        ef_lf_cnt[i] <= 0;
      end else if (ef_lf_rel[i]) begin
        if (token_go_i[c1] === 1'b1) ef_lf_rel_go[i] <= 1'b1;
        if (ef_lf_rel_go[i] && (latch_sticky_i[c1] !== ef_lf_dig[i])) begin
          ef_lf_rel[i] <= 1'b0;
          if (ef_own_tf) ef_tfs(7, {2'b00, 1'(i), 1'b1, 1'b0});
        end else if (ef_lf_cnt[i] == EfLatchWin) begin
          ef_lf_rel[i] <= 1'b0;
        end else begin
          ef_lf_cnt[i] <= ef_lf_cnt[i] + 1;
        end
      end
    end
  end

  // ---------------------------------------------------------------------
  // sep_sec_dis_activation_cg: cp_match_phase and x_verdict_out.
  // sep_sec_dis_robustness_cg: cp_stops_sense and cp_reset_values_hold.
  // ---------------------------------------------------------------------
  // cp_stops_sense bound (clk_i edges), outcome-bound rule of the graded
  // window: sep_sec_dis_timing_rand_test writes its window W (three times
  // the sense time it measures in the run) and writes 0 when its wait ends.
  // The bin fills only for a hold of W clocks. Monitor-only; it gates a
  // sample and is never a bin value.
  int unsigned efuse_sdis_hold_bound = 0;
  logic ef_sd_q = 1'b0;
  logic ef_ss_arm = 1'b0, ef_ss_phase = 1'b0, ef_ss_bad = 1'b0;
  logic [EfFuseBits-1:0] ef_ss_snap = '0;
  int unsigned ef_ss_cnt = 0;
  logic ef_rvh_done = 1'b0;
  // Clocks since the last reset release; a SEC_DIS that is high within
  // EfGoSettle clocks of the release counts as held at the release.
  int unsigned ef_since_rel = 0;
  logic ef_mp_before_done = 1'b0;
  wire ef_rel_win = !in_reset && (ef_since_rel <= EfGoSettle);
  always @(posedge clk_i) begin
    if (in_reset) ef_since_rel <= 0;
    else if (ef_since_rel <= EfGoSettle) ef_since_rel <= ef_since_rel + 1;
  end
  localparam logic [EfFuseBits-1:0] EfLcWordMask = EfFuseBits'(32'hFFFF_FFFF) << (32 * EfWLc);
  always @(posedge clk_i) begin
    logic open;
    ef_sd_q <= ef_sd && !in_reset;
    open = ef_live && ef_sd && (fuse_sense_done_i !== 1'b1);
    if (ef_live) begin
      if (ef_rel) ef_mp_before_done <= 1'b0;
      if (ef_rel_win && ef_sd && !ef_mp_before_done && (fuse_sense_done_i !== 1'b1)) begin
        ef_mp_before_done <= 1'b1;
        if (ef_own_sdt) ef_act(0, 5'd0);
      end
      if (!ef_rel_win && ef_sd && !ef_sd_q) begin
        if ((fuse_sense_done_i !== 1'b1) && ef_own_sdt) ef_act(0, 5'd1);
        if ((fuse_sense_done_i === 1'b1) && ef_own_fc) ef_act(0, 5'd2);
      end
      // x_verdict_out at a settled token change with a non-idle SEC_DIS code.
      if (ef_tok_ev) begin
        if ((tok_sdis_i == EfCodeMatch) && ef_own_fc) ef_act(1, {2'b00, 2'd0, ef_sd});
        if ((tok_sdis_i == EfCodeMismatch) && ef_own_fc) ef_act(1, {2'b00, 2'd1, ef_sd});
        if ((tok_sdis_i == EfCodeErr) && ef_own_tf) ef_act(1, {2'b00, 2'd2, ef_sd});
      end
    end
    // cp_stops_sense: phase 0 from a SEC_DIS rise during sense, phase 1 from
    // a reset release with SEC_DIS already high.
    if (!open) begin
      ef_ss_arm <= 1'b0;
    end else if (!ef_ss_arm && !ef_sd_q) begin
      ef_ss_arm <= 1'b1;
      ef_ss_phase <= ef_rel_win;
      ef_ss_bad <= 1'b0;
      ef_ss_snap <= efuse_shadow_i;
      ef_ss_cnt <= 0;
    end else if (ef_ss_arm) begin
      if (efuse_shadow_i !== ef_ss_snap) ef_ss_bad <= 1'b1;
      ef_ss_cnt <= ef_ss_cnt + 1;
      if ((efuse_sdis_hold_bound != 0) && (ef_ss_cnt + 1 == efuse_sdis_hold_bound)) begin
        if (ef_own_sdt && !ef_ss_bad && (efuse_shadow_i === ef_ss_snap))
          ef_rob(1, {2'b00, ef_ss_phase});
      end
    end
    // cp_reset_values_hold: once per held window after a reset release.
    if (ef_rel) ef_rvh_done <= 1'b0;
    if (open && !ef_rvh_done && ef_own_sdt && ((efuse_shadow_i & ~EfLcWordMask) == '0)) begin
      ef_rob(3, 3'd1);
      ef_rvh_done <= 1'b1;
    end
  end

  // ---------------------------------------------------------------------
  // sep_efuse_if_status_cg shim points: cp_sense_status_word and
  // x_prog_lifecycle.
  // ---------------------------------------------------------------------
  logic [12:0] ef_ssw_last = '0;
  logic ef_ssw_pend = 1'b0;
  logic [7:0] ef_ssw_w = '0;
  typedef enum logic [1:0] {
    EfPlIdle,
    EfPlWait,
    EfPlHeld,
    EfPlRel
  } ef_pl_e;
  ef_pl_e ef_pl_st = EfPlIdle;
  int unsigned ef_pl_cnt = 0;
  logic ef_pl_done_seen = 1'b0, ef_pdone_q = 1'b0, ef_cmd_pg_q = 1'b0;
  always @(posedge clk_i) begin
    logic [7:0] w;
    ef_pdone_q <= (efuse_program_done_i === 1'b1);
    ef_cmd_pg_q <= ef_cmd_pg;
    if (ef_rst_fall) ef_ssw_pend <= 1'b0;
    if (ef_live && (fuse_sense_done_i !== 1'b1)) begin
      if (ef_cmd_rd) ef_ssw_last <= ef_cmd_addr;
      if (ef_resp_v && (shim_resp_i.status === 1'b1)) begin
        w = ef_ssw_last[12:5];
        if ((w >= 8'd10) && (w <= 8'd254)) begin
          ef_ssw_pend <= 1'b1;
          ef_ssw_w <= w;
        end
      end
    end
    if (ef_sense_rise && ef_ssw_pend) begin
      ef_ssw_pend <= 1'b0;
      if (ef_own_shim && (efuse_shadow_i[32*ef_ssw_w+:32] == 32'h0)) ef_ifs(5, 7'd1);
    end
    // x_prog_lifecycle: a PROGRAM command with the program timeout off.
    if (in_reset) begin
      ef_pl_st <= EfPlIdle;
    end else begin
      case (ef_pl_st)
        EfPlIdle: begin
          if (ef_cmd_pg && !ef_cmd_pg_q && !ef_pg_tmo_en_q) begin
            ef_pl_st  <= EfPlWait;
            ef_pl_cnt <= 0;
          end
        end
        EfPlWait: begin
          if (ef_resp_v) begin
            ef_pl_st <= EfPlIdle;
          end else if (ef_pl_cnt == EfProgN) begin
            if (ef_own_shim) begin
              ef_ifs(
                  6, {
                  5'd0, 1'b0, !((efuse_program_busy_i === 1'b1) && (efuse_program_done_i !== 1'b1))
                  });
            end
            ef_pl_st <= EfPlHeld;
          end else begin
            ef_pl_cnt <= ef_pl_cnt + 1;
          end
        end
        EfPlHeld: begin
          if (ef_resp_v) begin
            ef_pl_st <= EfPlRel;
            ef_pl_done_seen <= 1'b0;
            ef_pl_cnt <= 0;
          end
        end
        default: begin
          if (!ef_pl_done_seen) begin
            if ((efuse_program_done_i === 1'b1) && !ef_pdone_q) ef_pl_done_seen <= 1'b1;
          end else if (ef_pl_cnt == EfProgN) begin
            if (ef_own_shim) begin
              ef_ifs(6, {
                     5'd0,
                     1'b1,
                     !((efuse_program_done_i === 1'b1) &&
                                        (efuse_program_error_i !== 1'b1) &&
                                        (efuse_program_busy_i !== 1'b1))
                     });
            end
            ef_pl_st <= EfPlIdle;
          end else begin
            ef_pl_cnt <= ef_pl_cnt + 1;
          end
        end
      endcase
    end
  end

  // ---------------------------------------------------------------------
  // sep_efuse_jtag_policy_cg: completion of a JTAG AXI-Lite access, class
  // from the address. The policy before sense done is not declared.
  // ---------------------------------------------------------------------
  logic [31:0] ef_j_aw = '0, ef_j_ar = '0;
  always @(posedge clk_i) begin
    ef_jtg_t je;
    logic [31:0] a;
    logic wr, ok, allowed, fire;
    logic [2:0] cl, cop;
    logic [1:0] st;
    if ((jtag_req_i.aw_valid === 1'b1) && (jtag_resp_i.aw_ready === 1'b1))
      ef_j_aw <= 32'(jtag_req_i.aw.addr);
    if ((jtag_req_i.ar_valid === 1'b1) && (jtag_resp_i.ar_ready === 1'b1))
      ef_j_ar <= 32'(jtag_req_i.ar.addr);
    fire = 1'b0;
    wr = 1'b0;
    ok = 1'b0;
    a = '0;
    if ((jtag_resp_i.b_valid === 1'b1) && (jtag_req_i.b_ready === 1'b1)) begin
      fire = 1'b1;
      wr = 1'b1;
      ok = (jtag_resp_i.b.resp == AxiOkay);
      a = ef_j_aw;
    end else if ((jtag_resp_i.r_valid === 1'b1) && (jtag_req_i.r_ready === 1'b1)) begin
      fire = 1'b1;
      ok = (jtag_resp_i.r.resp == AxiOkay);
      a = ef_j_ar;
    end
    if (fire && ef_sensed) begin
      cl = in_win(a, EfMapBase, EfMapEnd) ? 3'd0 : in_win(a, EfCtrlBase, EfCtrlEnd) ? 3'd1 :
          in_win(a, EfTokSip, EfTokEop) ? 3'd2 : (a == EfTokEop) ? 3'd3 :
          in_win(a, EfMatchSip, EfMatchFault) ? 3'd4 : 3'd7;
      st = ((jtag_filt_sigint_i === 1'b1) && (ef_lc == EfTd)) ? 2'd2 :
          (jtag_filt_sigint_i === 1'b1) ? 2'd3 : (ef_lc == EfProd) ? 2'd0 : (ef_lc == EfRs) ? 2'd1 : 2'd3;
      case (cl)
        3'd2: cop = wr ? 3'd1 : 3'd0;
        3'd3: cop = 3'd2;  // TOKEN_EOP read is not declared
        3'd4: cop = 3'd3;  // match write is not declared
        3'd0: cop = wr ? 3'd5 : 3'd4;
        3'd1: cop = wr ? 3'd7 : 3'd6;
        default: cop = 3'd7;
      endcase
      allowed = (cop < 3'd4);
      if ((cl != 3'd7) && (st != 2'd3) && ((st == 2'd2) ? ef_own_cw : ef_own_jtag)) begin
        je = '0;
        je.st = st;
        je.st_v = 1'b1;
        je.cl = cl;
        je.cl_v = 1'b1;
        je.rp = !ok;
        je.rp_v = 1'b1;
        if (!((cl == 3'd3) && !wr) && !((cl == 3'd4) && wr)) begin
          je.so = {allowed ? !ok : ok, 5'(st * 8) + 5'(cop)};
          je.so_v = 1'b1;
        end
        je.gi = st[0];
        je.gi_v = allowed && ok && (st != 2'd2) && (feat_ctrl_i[47:0] == 48'h0);
        u_sep_efuse_jtag_policy_cg.sample(je);
      end
    end
  end

endmodule : sep_fcov

`endif
